#[must_use]
pub fn builtin_rules() -> Vec<RuleMetadata> {
    let mut rules = Vec::new();
    rules.extend(core_rules());
    rules.extend(agent_rules());
    rules.extend(go_rules());
    rules.extend(node_rules());
    rules.extend(java_rules());
    rules.extend(python_rules());
    rules.extend(csharp_rules());
    rules.extend(php_rules());
    rules.extend(rust_rules());
    rules.extend(tier3_language_rules());
    rules.extend(security_rules());
    rules.extend(supply_chain_rules());
    rules.extend(infra_rules());
    rules.sort_by(|left, right| left.id.cmp(&right.id));
    rules
}

#[must_use]
pub fn scan_project(graph: &ProjectGraph, config: &Config) -> Vec<Finding> {
    scan_project_with_external(graph, config).findings
}

#[must_use]
pub fn scan_project_with_external(graph: &ProjectGraph, config: &Config) -> ScanOutput {
    scan_project_with_external_and_facts(graph, config, None)
}

#[must_use]
pub fn scan_project_with_external_and_facts(
    graph: &ProjectGraph,
    config: &Config,
    analysis_facts: Option<&AnalysisFacts>,
) -> ScanOutput {
    let metadata = builtin_rules()
        .into_iter()
        .map(|rule| (rule.id.clone(), rule))
        .collect::<BTreeMap<_, _>>();
    let disabled = config
        .disabled_rules
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let mut findings = Vec::new();
    if has_go(graph) {
        scan_go_project(graph, &metadata, &disabled, analysis_facts, &mut findings);
    }
    if has_node(graph) {
        scan_node_project(graph, &metadata, &disabled, analysis_facts, &mut findings);
    }
    if has_java(graph) {
        scan_java_project(graph, &metadata, &disabled, analysis_facts, &mut findings);
    }
    if has_python(graph) {
        scan_python_project(graph, &metadata, &disabled, analysis_facts, &mut findings);
    }
    if has_csharp(graph) {
        scan_csharp_project(graph, &metadata, &disabled, analysis_facts, &mut findings);
    }
    if has_php(graph) {
        scan_php_project(graph, &metadata, &disabled, analysis_facts, &mut findings);
    }
    if has_rust(graph) {
        scan_rust_project(graph, &metadata, &disabled, analysis_facts, &mut findings);
    }
    if has_tier3_language(graph) {
        scan_tier3_language_project(graph, &metadata, &disabled, analysis_facts, &mut findings);
    }
    scan_agent_patterns(graph, &metadata, &disabled, &mut findings);
    scan_unsupported_language_coverage(graph, &metadata, &disabled, &mut findings);
    scan_generic_security(graph, &metadata, &disabled, &mut findings);
    scan_supply_chain(graph, &metadata, &disabled, &mut findings);
    scan_infra_project(graph, &metadata, &disabled, analysis_facts, &mut findings);

    let mut external_tool_versions = Vec::new();
    let mut external_tool_executions = Vec::new();
    let cache = CacheStore::new(&graph.root, CacheSettings::from_config(config));
    if has_go(graph) && config.external_tools.deep {
        run_go_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }
    if has_java(graph) && config.external_tools.deep {
        run_java_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }
    if has_node(graph) && config.external_tools.deep {
        run_node_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }
    if has_python(graph) && config.external_tools.deep {
        run_python_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }
    if has_csharp(graph) && config.external_tools.deep {
        run_csharp_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }
    if has_php(graph) && config.external_tools.deep {
        run_php_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }
    if has_rust(graph) && config.external_tools.deep {
        run_rust_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }
    if has_tier3_language(graph) && config.external_tools.deep {
        run_tier3_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }
    if config.external_tools.deep && !graph.inventory.files.is_empty() {
        run_security_infra_external_tools(
            graph,
            config,
            &cache,
            &disabled,
            &mut findings,
            &mut external_tool_versions,
            &mut external_tool_executions,
        );
    }

    for finding in &mut findings {
        finding.suppressed = is_suppressed(finding, &config.suppressions);
    }

    ScanOutput {
        findings: backend_doctor_core::sort_findings(dedupe_findings(findings)),
        external_tool_versions,
        external_tool_executions,
    }
}

fn scan_go_project(
    graph: &ProjectGraph,
    metadata: &BTreeMap<String, RuleMetadata>,
    disabled: &BTreeSet<String>,
    analysis_facts: Option<&AnalysisFacts>,
    findings: &mut Vec<Finding>,
) {
    let go_files = graph
        .inventory
        .files
        .iter()
        .filter(|path| path.extension().is_some_and(|ext| ext == "go"))
        .cloned()
        .collect::<Vec<_>>();
    let go_frameworks = graph
        .services
        .iter()
        .filter(|service| service.languages.iter().any(|language| language == "Go"))
        .flat_map(|service| service.frameworks.iter().cloned())
        .collect::<BTreeSet<_>>();
    let context = GoFileScanContext {
        graph,
        metadata,
        disabled,
        analysis_facts,
        go_frameworks: &go_frameworks,
    };

    for relative in &go_files {
        let absolute = graph.root.join(relative);
        let Ok(text) = fs::read_to_string(&absolute) else {
            continue;
        };
        scan_go_file(&context, relative, &text, findings);
    }

    scan_go_semantic_duplicates(graph, metadata, disabled, &go_files, findings);
    scan_go_service_level(
        graph,
        metadata,
        disabled,
        &go_frameworks,
        &go_files,
        findings,
    );
}

#[must_use]
pub fn parse_eslint_json(output: &str) -> Vec<EslintDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    let Some(files) = value.as_array() else {
        return Vec::new();
    };
    files
        .iter()
        .flat_map(|file| {
            let path = file
                .get("filePath")
                .and_then(Value::as_str)
                .map(PathBuf::from)
                .unwrap_or_else(|| PathBuf::from("."));
            file.get("messages")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .map(move |message| {
                    let severity = match message.get("severity").and_then(Value::as_u64) {
                        Some(2) => Severity::Error,
                        Some(1) => Severity::Warning,
                        _ => Severity::Info,
                    };
                    EslintDiagnostic {
                        path: path.clone(),
                        line: message
                            .get("line")
                            .and_then(Value::as_u64)
                            .and_then(|value| u32::try_from(value).ok()),
                        column: message
                            .get("column")
                            .and_then(Value::as_u64)
                            .and_then(|value| u32::try_from(value).ok()),
                        rule_id: message
                            .get("ruleId")
                            .and_then(Value::as_str)
                            .map(str::to_string),
                        message: message
                            .get("message")
                            .and_then(Value::as_str)
                            .unwrap_or("ESLint diagnostic")
                            .to_string(),
                        severity,
                        fixable: message.get("fix").is_some(),
                    }
                })
        })
        .collect()
}

#[must_use]
pub fn parse_typescript_diagnostics(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            let (path, rest) = trimmed.split_once('(')?;
            let (location, rest) = rest.split_once("):")?;
            let mut parts = location.split(',');
            let line_no = parts.next()?.parse::<u32>().ok()?;
            let column = parts.next().and_then(|value| value.parse::<u32>().ok());
            let message = rest.trim();
            let code = message
                .split_whitespace()
                .find(|part| part.starts_with("TS"))
                .unwrap_or("TS0000")
                .trim_end_matches(':');
            Some(ExternalDiagnostic {
                source_tool: "tsc".to_string(),
                rule_id: format!("node/typescript/{code}"),
                path: PathBuf::from(path),
                line: Some(line_no),
                column,
                message: message.to_string(),
                severity: Severity::Error,
            })
        })
        .collect()
}

#[must_use]
pub fn parse_ruff_json(output: &str) -> Vec<ExternalDiagnostic> {
    serde_json::from_str::<Value>(output)
        .ok()
        .and_then(|value| value.as_array().cloned())
        .unwrap_or_default()
        .into_iter()
        .map(|item| ExternalDiagnostic {
            source_tool: "ruff".to_string(),
            rule_id: format!(
                "python/ruff/{}",
                item.get("code")
                    .and_then(Value::as_str)
                    .unwrap_or("diagnostic")
            ),
            path: PathBuf::from(item.get("filename").and_then(Value::as_str).unwrap_or(".")),
            line: item
                .get("location")
                .and_then(|value| value.get("row"))
                .and_then(Value::as_u64)
                .and_then(|value| u32::try_from(value).ok()),
            column: item
                .get("location")
                .and_then(|value| value.get("column"))
                .and_then(Value::as_u64)
                .and_then(|value| u32::try_from(value).ok()),
            message: item
                .get("message")
                .and_then(Value::as_str)
                .unwrap_or("Ruff diagnostic")
                .to_string(),
            severity: Severity::Warning,
        })
        .collect()
}

#[must_use]
pub fn parse_bandit_json(output: &str) -> Vec<ExternalDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    value
        .get("results")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|item| ExternalDiagnostic {
            source_tool: "bandit".to_string(),
            rule_id: format!(
                "python/bandit/{}",
                item.get("test_id")
                    .and_then(Value::as_str)
                    .unwrap_or("diagnostic")
            ),
            path: PathBuf::from(item.get("filename").and_then(Value::as_str).unwrap_or(".")),
            line: item
                .get("line_number")
                .and_then(Value::as_u64)
                .and_then(|value| u32::try_from(value).ok()),
            column: None,
            message: item
                .get("issue_text")
                .and_then(Value::as_str)
                .unwrap_or("Bandit diagnostic")
                .to_string(),
            severity: vulnerability_severity(
                item.get("issue_severity")
                    .and_then(Value::as_str)
                    .unwrap_or("medium"),
            ),
        })
        .collect()
}

#[must_use]
pub fn parse_pytest_output(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            if let Some((path, rest)) = trimmed.split_once(':') {
                let (line_no, message) = rest.split_once(':')?;
                if path.ends_with(".py") {
                    return Some(ExternalDiagnostic {
                        source_tool: "pytest".to_string(),
                        rule_id: "python/pytest-failure".to_string(),
                        path: PathBuf::from(path),
                        line: line_no.parse::<u32>().ok(),
                        column: None,
                        message: message.trim().to_string(),
                        severity: Severity::Error,
                    });
                }
            }
            trimmed.contains("FAILED ").then(|| ExternalDiagnostic {
                source_tool: "pytest".to_string(),
                rule_id: "python/pytest-failure".to_string(),
                path: PathBuf::from("."),
                line: Some(1),
                column: None,
                message: trimmed.to_string(),
                severity: Severity::Error,
            })
        })
        .collect()
}

#[must_use]
pub fn parse_dotnet_output(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            let (path, rest) = trimmed.split_once('(')?;
            let (location, rest) = rest.split_once("):")?;
            let (level, message) = rest.trim().split_once(':')?;
            let mut parts = location.split(',');
            let line_no = parts.next()?.parse::<u32>().ok();
            let column = parts.next().and_then(|value| value.parse::<u32>().ok());
            let code = level
                .split_whitespace()
                .find(|part| {
                    part.starts_with("CS") || part.starts_with("CA") || part.starts_with("ASP")
                })
                .unwrap_or("DOTNET");
            Some(ExternalDiagnostic {
                source_tool: "dotnet".to_string(),
                rule_id: format!("csharp/dotnet/{code}"),
                path: PathBuf::from(path),
                line: line_no,
                column,
                message: message.trim().to_string(),
                severity: if level.contains("error") {
                    Severity::Error
                } else {
                    Severity::Warning
                },
            })
        })
        .collect()
}

#[must_use]
pub fn parse_dotnet_vulnerable_packages(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter(|line| line.contains('>') && line.to_ascii_lowercase().contains("vulnerable"))
        .map(|line| ExternalDiagnostic {
            source_tool: "dotnet".to_string(),
            rule_id: "csharp/dotnet-vulnerable-package".to_string(),
            path: PathBuf::from("."),
            line: Some(1),
            column: None,
            message: line.trim().to_string(),
            severity: Severity::Error,
        })
        .collect()
}

#[must_use]
pub fn parse_phpstan_text(output: &str) -> Vec<ExternalDiagnostic> {
    parse_colon_diagnostics("phpstan", "php/phpstan", output, ".php", Severity::Warning)
}

#[must_use]
pub fn parse_phpunit_text(output: &str) -> Vec<ExternalDiagnostic> {
    parse_colon_diagnostics(
        "phpunit",
        "php/phpunit-failure",
        output,
        ".php",
        Severity::Error,
    )
}

#[must_use]
pub fn parse_composer_audit_json(output: &str) -> Vec<ExternalDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    let advisories = value
        .get("advisories")
        .and_then(Value::as_object)
        .into_iter()
        .flat_map(|items| items.values())
        .flat_map(|item| {
            item.as_array()
                .map_or_else(|| vec![item], |items| items.iter().collect())
        });
    advisories
        .map(|item| ExternalDiagnostic {
            source_tool: "composer".to_string(),
            rule_id: format!(
                "php/composer-audit/{}",
                item.get("cve")
                    .or_else(|| item.get("advisoryId"))
                    .and_then(Value::as_str)
                    .unwrap_or("advisory")
            ),
            path: PathBuf::from("composer.lock"),
            line: Some(1),
            column: None,
            message: item
                .get("title")
                .or_else(|| item.get("advisoryTitle"))
                .and_then(Value::as_str)
                .unwrap_or("Composer audit advisory")
                .to_string(),
            severity: vulnerability_severity(
                item.get("severity")
                    .and_then(Value::as_str)
                    .unwrap_or("high"),
            ),
        })
        .collect()
}

#[must_use]
pub fn parse_cargo_message_json(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| serde_json::from_str::<Value>(line).ok())
        .filter(|value| value.get("reason").and_then(Value::as_str) == Some("compiler-message"))
        .filter_map(|value| {
            let message = value.get("message")?;
            let span = message
                .get("spans")
                .and_then(Value::as_array)
                .and_then(|spans| {
                    spans.iter().find(|span| {
                        span.get("is_primary")
                            .and_then(Value::as_bool)
                            .unwrap_or(false)
                    })
                })
                .or_else(|| {
                    message
                        .get("spans")
                        .and_then(Value::as_array)
                        .and_then(|spans| spans.first())
                })?;
            let level = message
                .get("level")
                .and_then(Value::as_str)
                .unwrap_or("warning");
            let code = message
                .get("code")
                .and_then(|code| code.get("code"))
                .and_then(Value::as_str)
                .unwrap_or(level);
            Some(ExternalDiagnostic {
                source_tool: "cargo".to_string(),
                rule_id: format!("rust/cargo/{code}"),
                path: PathBuf::from(span.get("file_name").and_then(Value::as_str).unwrap_or(".")),
                line: span
                    .get("line_start")
                    .and_then(Value::as_u64)
                    .and_then(|value| u32::try_from(value).ok()),
                column: span
                    .get("column_start")
                    .and_then(Value::as_u64)
                    .and_then(|value| u32::try_from(value).ok()),
                message: message
                    .get("message")
                    .and_then(Value::as_str)
                    .unwrap_or("Cargo diagnostic")
                    .to_string(),
                severity: lint_severity(Some(level)),
            })
        })
        .collect()
}

#[must_use]
pub fn parse_cargo_audit_json(output: &str) -> Vec<ExternalDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    value
        .get("vulnerabilities")
        .and_then(|value| value.get("list"))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|item| {
            let advisory = item.get("advisory").unwrap_or(item);
            ExternalDiagnostic {
                source_tool: "cargo-audit".to_string(),
                rule_id: format!(
                    "rust/cargo-audit/{}",
                    advisory
                        .get("id")
                        .and_then(Value::as_str)
                        .unwrap_or("advisory")
                ),
                path: PathBuf::from("Cargo.lock"),
                line: Some(1),
                column: None,
                message: advisory
                    .get("title")
                    .and_then(Value::as_str)
                    .unwrap_or("Cargo audit vulnerability")
                    .to_string(),
                severity: Severity::Error,
            }
        })
        .collect()
}

fn parse_colon_diagnostics(
    source_tool: &str,
    rule_id: &str,
    output: &str,
    extension: &str,
    severity: Severity,
) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            let (path, rest) = trimmed.split_once(':')?;
            if !path.ends_with(extension) {
                return None;
            }
            let (line_no, message) = rest.split_once(':').unwrap_or((rest, ""));
            Some(ExternalDiagnostic {
                source_tool: source_tool.to_string(),
                rule_id: rule_id.to_string(),
                path: PathBuf::from(path),
                line: line_no.parse::<u32>().ok(),
                column: None,
                message: message.trim().to_string(),
                severity: severity.clone(),
            })
        })
        .collect()
}

#[must_use]
pub fn parse_npm_audit_json(output: &str) -> Vec<NpmAuditDiagnostic> {
    parse_node_audit_json("npm", output)
}

#[must_use]
pub fn parse_pnpm_audit_json(output: &str) -> Vec<NpmAuditDiagnostic> {
    parse_node_audit_json("pnpm", output)
}

#[must_use]
pub fn parse_yarn_audit_json(output: &str) -> Vec<NpmAuditDiagnostic> {
    let diagnostics = parse_node_audit_json("yarn", output);
    if !diagnostics.is_empty() {
        return diagnostics;
    }
    output
        .lines()
        .filter_map(|line| {
            let value = serde_json::from_str::<Value>(line).ok()?;
            let advisory = value
                .get("data")
                .and_then(|data| data.get("advisory"))
                .or_else(|| value.get("advisory"))?;
            let package = advisory
                .get("module_name")
                .or_else(|| advisory.get("package"))
                .and_then(Value::as_str)
                .unwrap_or("dependency");
            let title = advisory
                .get("title")
                .or_else(|| advisory.get("overview"))
                .and_then(Value::as_str)
                .unwrap_or("yarn audit vulnerability");
            Some(NpmAuditDiagnostic {
                source_tool: "yarn".to_string(),
                package: package.to_string(),
                advisory: title.to_string(),
                severity: npm_severity(
                    advisory
                        .get("severity")
                        .and_then(Value::as_str)
                        .unwrap_or("info"),
                ),
                via: vec![title.to_string()],
            })
        })
        .collect()
}

#[must_use]
pub fn parse_bun_audit_json(output: &str) -> Vec<NpmAuditDiagnostic> {
    parse_node_audit_json("bun", output)
}

#[must_use]
pub fn findings_from_eslint_diagnostics(
    graph: &ProjectGraph,
    diagnostics: &[EslintDiagnostic],
    disabled: &BTreeSet<String>,
) -> Vec<Finding> {
    diagnostics
        .iter()
        .filter_map(|diagnostic| {
            let rule_suffix = diagnostic.rule_id.as_deref().unwrap_or("fatal");
            let rule_id = format!("node/eslint/{rule_suffix}");
            if is_rule_disabled(disabled, &rule_id) {
                return None;
            }
            Some(external_node_finding(
                graph,
                &diagnostic.path,
                diagnostic.line,
                diagnostic.column,
                &rule_id,
                "eslint",
                "ESLint diagnostic",
                &diagnostic.message,
                diagnostic.severity.clone(),
                Category::Maintainability,
                BTreeMap::from([("fixable".to_string(), diagnostic.fixable.to_string())]),
            ))
        })
        .collect()
}

#[must_use]
pub fn findings_from_typescript_diagnostics(
    graph: &ProjectGraph,
    diagnostics: &[ExternalDiagnostic],
    disabled: &BTreeSet<String>,
) -> Vec<Finding> {
    diagnostics
        .iter()
        .filter(|diagnostic| !is_rule_disabled(disabled, &diagnostic.rule_id))
        .map(|diagnostic| {
            external_node_finding(
                graph,
                &diagnostic.path,
                diagnostic.line,
                diagnostic.column,
                &diagnostic.rule_id,
                "tsc",
                "TypeScript compiler diagnostic",
                &diagnostic.message,
                diagnostic.severity.clone(),
                Category::Correctness,
                BTreeMap::new(),
            )
        })
        .collect()
}

#[must_use]
pub fn findings_from_node_audit_diagnostics(
    graph: &ProjectGraph,
    diagnostics: &[NpmAuditDiagnostic],
    disabled: &BTreeSet<String>,
) -> Vec<Finding> {
    if is_rule_disabled(disabled, "supply-chain/vulnerable-dependency") {
        return Vec::new();
    }
    diagnostics
        .iter()
        .map(|diagnostic| {
            external_node_finding(
                graph,
                &PathBuf::from("package.json"),
                Some(1),
                None,
                "supply-chain/vulnerable-dependency",
                &diagnostic.source_tool,
                "Vulnerable Node dependency",
                &format!("{}: {}", diagnostic.package, diagnostic.advisory),
                diagnostic.severity.clone(),
                Category::Dependencies,
                BTreeMap::from([
                    ("package".to_string(), diagnostic.package.clone()),
                    ("via".to_string(), diagnostic.via.join(",")),
                ]),
            )
        })
        .collect()
}

fn is_rule_disabled(disabled: &BTreeSet<String>, rule_id: &str) -> bool {
    disabled.iter().any(|disabled_id| {
        rule_id == disabled_id
            || rule_id
                .strip_prefix(disabled_id)
                .is_some_and(|suffix| suffix.starts_with('/'))
            || rule_id
                .rsplit('/')
                .next()
                .is_some_and(|suffix| suffix == disabled_id)
    })
}

#[allow(clippy::too_many_arguments)]
fn external_node_finding(
    graph: &ProjectGraph,
    path: &Path,
    line: Option<u32>,
    column: Option<u32>,
    rule_id: &str,
    source_tool: &str,
    title: &str,
    message: &str,
    severity: Severity,
    category: Category,
    metadata: BTreeMap<String, String>,
) -> Finding {
    let relative = path.strip_prefix(&graph.root).unwrap_or(path);
    let line = line.unwrap_or(1);
    let service = service_for_path(graph, relative);
    let fingerprint = fingerprint(rule_id, relative, line, message);
    Finding {
        id: fingerprint.clone(),
        fingerprint,
        rule_id: rule_id.to_string(),
        tool: "backend-doctor-rules".to_string(),
        source_tool: source_tool.to_string(),
        title: title.to_string(),
        message: message.to_string(),
        category,
        severity,
        confidence: Confidence::High,
        service: service.clone(),
        language: Some("Node/TypeScript".to_string()),
        framework: framework_for(graph, &service),
        location: Some(Location {
            path: relative.to_path_buf(),
            line: Some(line),
            column,
            end_line: None,
            end_column: None,
        }),
        evidence: Some(Evidence {
            snippet: backend_doctor_core::redact_text(message),
            redacted: true,
            secret_fingerprint: None,
        }),
        impact: None,
        remediation: "Review and fix the external tool diagnostic.".to_string(),
        fix: FixInfo {
            available: false,
            safety: FixSafety::None,
            description: None,
        },
        links: Vec::new(),
        metadata,
        suppressed: false,
    }
}

fn parse_node_audit_json(source_tool: &str, output: &str) -> Vec<NpmAuditDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    if let Some(vulnerabilities) = value.get("vulnerabilities").and_then(Value::as_object) {
        return vulnerabilities
            .iter()
            .map(|(package, vuln)| {
                let severity = npm_severity(
                    vuln.get("severity")
                        .and_then(Value::as_str)
                        .unwrap_or("info"),
                );
                let via = vuln
                    .get("via")
                    .and_then(Value::as_array)
                    .map(|items| {
                        items
                            .iter()
                            .filter_map(|item| {
                                item.as_str().map(str::to_string).or_else(|| {
                                    item.get("title")
                                        .and_then(Value::as_str)
                                        .map(str::to_string)
                                })
                            })
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default();
                let advisory = via
                    .first()
                    .cloned()
                    .unwrap_or_else(|| "npm audit vulnerability".to_string());
                NpmAuditDiagnostic {
                    source_tool: source_tool.to_string(),
                    package: package.clone(),
                    advisory,
                    severity,
                    via,
                }
            })
            .collect();
    }
    value
        .get("advisories")
        .and_then(Value::as_object)
        .into_iter()
        .flatten()
        .map(|(_, advisory)| {
            let package = advisory
                .get("module_name")
                .or_else(|| advisory.get("package"))
                .and_then(Value::as_str)
                .unwrap_or("dependency");
            let title = advisory
                .get("title")
                .or_else(|| advisory.get("overview"))
                .and_then(Value::as_str)
                .unwrap_or("audit vulnerability");
            NpmAuditDiagnostic {
                source_tool: source_tool.to_string(),
                package: package.to_string(),
                advisory: title.to_string(),
                severity: npm_severity(
                    advisory
                        .get("severity")
                        .and_then(Value::as_str)
                        .unwrap_or("info"),
                ),
                via: vec![title.to_string()],
            }
        })
        .collect()
}

#[must_use]
pub fn parse_maven_output(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            let without_prefix = trimmed
                .strip_prefix("[ERROR]")
                .or_else(|| trimmed.strip_prefix("[WARNING]"))
                .map(str::trim)
                .unwrap_or(trimmed);
            parse_java_tool_location("maven", without_prefix).map(|mut diagnostic| {
                diagnostic.rule_id = "java/maven-diagnostic".to_string();
                if trimmed.starts_with("[ERROR]") {
                    diagnostic.severity = Severity::Error;
                }
                diagnostic
            })
        })
        .collect()
}

#[must_use]
pub fn parse_gradle_output(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            let trimmed = line.trim();
            if trimmed.contains(" FAILED") || trimmed.starts_with("FAILURE:") {
                return Some(ExternalDiagnostic {
                    source_tool: "gradle".to_string(),
                    rule_id: "java/gradle-failure".to_string(),
                    path: PathBuf::from("."),
                    line: None,
                    column: None,
                    message: trimmed.to_string(),
                    severity: Severity::Error,
                });
            }
            parse_java_tool_location("gradle", trimmed).map(|mut diagnostic| {
                diagnostic.rule_id = "java/gradle-diagnostic".to_string();
                diagnostic
            })
        })
        .collect()
}

#[must_use]
pub fn parse_rubocop_json(output: &str) -> Vec<ExternalDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    value
        .get("files")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .flat_map(|file| {
            let path = PathBuf::from(file.get("path").and_then(Value::as_str).unwrap_or("."));
            file.get("offenses")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .map(move |offense| {
                    let cop = offense
                        .get("cop_name")
                        .and_then(Value::as_str)
                        .unwrap_or("rubocop");
                    let location = offense.get("location").and_then(Value::as_object);
                    ExternalDiagnostic {
                        source_tool: "rubocop".to_string(),
                        rule_id: format!("ruby/rubocop/{cop}"),
                        path: path.clone(),
                        line: location
                            .and_then(|location| location.get("line"))
                            .and_then(Value::as_u64)
                            .and_then(|value| u32::try_from(value).ok()),
                        column: location
                            .and_then(|location| location.get("column"))
                            .and_then(Value::as_u64)
                            .and_then(|value| u32::try_from(value).ok()),
                        message: offense
                            .get("message")
                            .and_then(Value::as_str)
                            .unwrap_or("RuboCop diagnostic")
                            .to_string(),
                        severity: lint_severity(offense.get("severity").and_then(Value::as_str)),
                    }
                })
        })
        .collect()
}

#[must_use]
