#[must_use]
pub fn parse_cppcheck_text(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            if let Some((path, rest)) = line.trim().strip_prefix('[')?.split_once("]:") {
                let (path, line_no) = path.rsplit_once(':')?;
                return Some(ExternalDiagnostic {
                    source_tool: "cppcheck".to_string(),
                    rule_id: "cpp/cppcheck".to_string(),
                    path: PathBuf::from(path),
                    line: line_no.parse::<u32>().ok(),
                    column: None,
                    message: rest.trim().to_string(),
                    severity: if rest.contains("(error)") {
                        Severity::Error
                    } else {
                        Severity::Warning
                    },
                });
            }
            parse_colon_diagnostic("cppcheck", "cpp/cppcheck", line)
        })
        .collect()
}

#[must_use]
pub fn parse_error_prone_text(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            parse_java_tool_location("error-prone", line).map(|mut diagnostic| {
                if let Some(code) = line
                    .rsplit('[')
                    .next()
                    .and_then(|tail| tail.strip_suffix(']'))
                    .filter(|code| !code.contains(' '))
                {
                    diagnostic.rule_id = format!("java/error-prone/{code}");
                } else {
                    diagnostic.rule_id = "java/error-prone".to_string();
                }
                diagnostic.severity = Severity::Warning;
                diagnostic
            })
        })
        .collect()
}

#[must_use]
pub fn parse_spotbugs_xml(output: &str) -> Vec<ExternalDiagnostic> {
    let mut diagnostics = Vec::new();
    let mut bug_type = "spotbugs".to_string();
    let mut message = "SpotBugs diagnostic".to_string();
    for line in output.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("<BugInstance") {
            bug_type = xml_attr(trimmed, "type").unwrap_or_else(|| "spotbugs".to_string());
            message = xml_attr(trimmed, "message").unwrap_or_else(|| bug_type.clone());
        }
        if trimmed.starts_with("<SourceLine") {
            let path = xml_attr(trimmed, "sourcepath")
                .or_else(|| xml_attr(trimmed, "sourcefile"))
                .unwrap_or_else(|| ".".to_string());
            let line = xml_attr(trimmed, "start").and_then(|value| value.parse::<u32>().ok());
            diagnostics.push(ExternalDiagnostic {
                source_tool: "spotbugs".to_string(),
                rule_id: format!("java/spotbugs/{bug_type}"),
                path: PathBuf::from(path),
                line,
                column: None,
                message: message.clone(),
                severity: Severity::Warning,
            });
        }
    }
    diagnostics
}

#[must_use]
pub fn parse_dependency_check_json(output: &str) -> Vec<DependencyCheckDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    let Some(dependencies) = value.get("dependencies").and_then(Value::as_array) else {
        return Vec::new();
    };
    dependencies
        .iter()
        .flat_map(|dependency| {
            let package = dependency
                .get("fileName")
                .or_else(|| dependency.get("filePath"))
                .and_then(Value::as_str)
                .unwrap_or("dependency")
                .to_string();
            dependency
                .get("vulnerabilities")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .map(move |vulnerability| {
                    let name = vulnerability
                        .get("name")
                        .and_then(Value::as_str)
                        .unwrap_or("dependency-check vulnerability");
                    let severity = java_severity(
                        vulnerability
                            .get("severity")
                            .and_then(Value::as_str)
                            .unwrap_or("info"),
                    );
                    let description = vulnerability
                        .get("description")
                        .and_then(Value::as_str)
                        .unwrap_or(name);
                    DependencyCheckDiagnostic {
                        package: package.clone(),
                        vulnerability: name.to_string(),
                        severity,
                        description: description.to_string(),
                    }
                })
        })
        .collect()
}

#[must_use]
pub fn parse_dependency_check_xml(output: &str) -> Vec<DependencyCheckDiagnostic> {
    let mut diagnostics = Vec::new();
    let mut package = "dependency".to_string();
    let mut in_vulnerability = false;
    let mut name: Option<String> = None;
    let mut severity: Option<String> = None;
    let mut description: Option<String> = None;

    for line in output.lines() {
        let trimmed = line.trim();
        if let Some(value) = xml_text(trimmed, "fileName").or_else(|| xml_text(trimmed, "filePath"))
        {
            package = value;
        } else if trimmed.starts_with("<vulnerability") {
            in_vulnerability = true;
            name = xml_text(trimmed, "name");
            severity = xml_text(trimmed, "severity");
            description = xml_text(trimmed, "description");
            if trimmed.contains("</vulnerability") {
                if let Some(vulnerability) = name.take() {
                    diagnostics.push(DependencyCheckDiagnostic {
                        package: package.clone(),
                        severity: java_severity(severity.as_deref().unwrap_or("info")),
                        description: description.clone().unwrap_or_else(|| vulnerability.clone()),
                        vulnerability,
                    });
                }
                in_vulnerability = false;
            }
        } else if trimmed.starts_with("</vulnerability") {
            if let Some(vulnerability) = name.take() {
                diagnostics.push(DependencyCheckDiagnostic {
                    package: package.clone(),
                    severity: java_severity(severity.as_deref().unwrap_or("info")),
                    description: description.clone().unwrap_or_else(|| vulnerability.clone()),
                    vulnerability,
                });
            }
            in_vulnerability = false;
        } else if in_vulnerability {
            if name.is_none() {
                name = xml_text(trimmed, "name");
            }
            if severity.is_none() {
                severity = xml_text(trimmed, "severity");
            }
            if description.is_none() {
                description = xml_text(trimmed, "description");
            }
        }
    }

    diagnostics
}

#[must_use]
pub fn parse_gitleaks_json(output: &str) -> Vec<SecretDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    value
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|item| {
            let path = item.get("File").and_then(Value::as_str)?;
            let rule_id = item
                .get("RuleID")
                .and_then(Value::as_str)
                .unwrap_or("gitleaks/secret");
            let line = item
                .get("StartLine")
                .and_then(Value::as_u64)
                .and_then(|value| u32::try_from(value).ok())
                .unwrap_or(1);
            let fingerprint = item
                .get("Fingerprint")
                .and_then(Value::as_str)
                .map(secret_fingerprint)
                .or_else(|| {
                    item.get("Secret")
                        .and_then(Value::as_str)
                        .map(secret_fingerprint)
                })
                .unwrap_or_else(|| fingerprint(rule_id, Path::new(path), line, "secret"));
            Some(SecretDiagnostic {
                rule_id: format!("security/gitleaks/{rule_id}"),
                path: PathBuf::from(path),
                line,
                message: "Gitleaks reported a secret-like value.".to_string(),
                fingerprint,
            })
        })
        .collect()
}

