#[must_use]
pub fn parse_kubelinter_json(output: &str) -> Vec<ExternalDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    value
        .get("Reports")
        .or_else(|| value.get("reports"))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|report| {
            let check = report
                .get("Check")
                .or_else(|| report.get("check"))
                .and_then(Value::as_str)
                .unwrap_or("kubelinter");
            let object = report
                .get("Object")
                .or_else(|| report.get("object"))
                .and_then(Value::as_object);
            ExternalDiagnostic {
                source_tool: "kube-linter".to_string(),
                rule_id: format!("k8s/kubelinter/{check}"),
                path: PathBuf::from(
                    report
                        .get("File")
                        .or_else(|| report.get("file"))
                        .and_then(Value::as_str)
                        .unwrap_or("."),
                ),
                line: report
                    .get("Line")
                    .or_else(|| report.get("line"))
                    .and_then(Value::as_u64)
                    .and_then(|value| u32::try_from(value).ok()),
                column: None,
                message: report
                    .get("Diagnostic")
                    .or_else(|| report.get("diagnostic"))
                    .and_then(Value::as_str)
                    .or_else(|| {
                        object
                            .and_then(|item| item.get("K8sObject"))
                            .and_then(Value::as_str)
                    })
                    .unwrap_or("KubeLinter diagnostic")
                    .to_string(),
                severity: Severity::Warning,
            }
        })
        .collect()
}

