#[must_use]
pub fn parse_semgrep_json(output: &str) -> Vec<ExternalDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    value
        .get("results")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|result| {
            let check_id = result.get("check_id").and_then(Value::as_str)?;
            let path = result.get("path").and_then(Value::as_str).unwrap_or(".");
            let start = result.get("start").and_then(Value::as_object);
            let extra = result.get("extra").and_then(Value::as_object);
            let severity = extra
                .and_then(|extra| extra.get("severity"))
                .and_then(Value::as_str)
                .map(vulnerability_severity)
                .unwrap_or(Severity::Warning);
            Some(ExternalDiagnostic {
                source_tool: "semgrep".to_string(),
                rule_id: format!("security/semgrep/{check_id}"),
                path: PathBuf::from(path),
                line: start
                    .and_then(|start| start.get("line"))
                    .and_then(Value::as_u64)
                    .and_then(|value| u32::try_from(value).ok()),
                column: start
                    .and_then(|start| start.get("col"))
                    .and_then(Value::as_u64)
                    .and_then(|value| u32::try_from(value).ok()),
                message: extra
                    .and_then(|extra| extra.get("message"))
                    .and_then(Value::as_str)
                    .unwrap_or("Semgrep security finding")
                    .to_string(),
                severity,
            })
        })
        .collect()
}

#[must_use]
pub fn parse_codeql_sarif_json(output: &str) -> Vec<ExternalDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    let mut diagnostics = Vec::new();
    for run in value
        .get("runs")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
    {
        let tool_name = run
            .get("tool")
            .and_then(|tool| tool.get("driver"))
            .and_then(|driver| driver.get("name"))
            .and_then(Value::as_str)
            .unwrap_or("codeql");
        for result in run
            .get("results")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
        {
            let rule_id = result
                .get("ruleId")
                .and_then(Value::as_str)
                .unwrap_or("sarif");
            let message = result
                .get("message")
                .and_then(|message| message.get("text"))
                .and_then(Value::as_str)
                .unwrap_or("SARIF finding");
            let location = result
                .get("locations")
                .and_then(Value::as_array)
                .and_then(|locations| locations.first())
                .and_then(|location| location.get("physicalLocation"));
            let artifact = location
                .and_then(|location| location.get("artifactLocation"))
                .and_then(|artifact| artifact.get("uri"))
                .and_then(Value::as_str)
                .unwrap_or(".");
            let region = location.and_then(|location| location.get("region"));
            diagnostics.push(ExternalDiagnostic {
                source_tool: tool_name.to_string(),
                rule_id: format!("security/codeql/{rule_id}"),
                path: PathBuf::from(artifact),
                line: region
                    .and_then(|region| region.get("startLine"))
                    .and_then(Value::as_u64)
                    .and_then(|value| u32::try_from(value).ok()),
                column: region
                    .and_then(|region| region.get("startColumn"))
                    .and_then(Value::as_u64)
                    .and_then(|value| u32::try_from(value).ok()),
                message: message.to_string(),
                severity: sarif_result_severity(result),
            });
        }
    }
    diagnostics
}

fn collect_osv_vulnerabilities(
    value: &Value,
    package_hint: Option<String>,
    diagnostics: &mut Vec<VulnerabilityDiagnostic>,
) {
    match value {
        Value::Object(map) => {
            let package = map
                .get("package")
                .and_then(|package| package.get("name").or(Some(package)))
                .and_then(Value::as_str)
                .map(str::to_string)
                .or(package_hint);
            if let Some(id) = map.get("id").and_then(Value::as_str) {
                let message = map
                    .get("summary")
                    .or_else(|| map.get("details"))
                    .and_then(Value::as_str)
                    .unwrap_or(id);
                diagnostics.push(VulnerabilityDiagnostic {
                    source_tool: "osv".to_string(),
                    rule_id: format!("security/osv/{id}"),
                    package: package.clone().unwrap_or_else(|| "dependency".to_string()),
                    vulnerability: id.to_string(),
                    severity: osv_severity(map),
                    message: message.to_string(),
                    path: PathBuf::from("."),
                    line: None,
                    reachability: map
                        .get("reachability")
                        .and_then(Value::as_str)
                        .map(|value| value.to_ascii_lowercase()),
                });
            }
            for child in map.values() {
                collect_osv_vulnerabilities(child, package.clone(), diagnostics);
            }
        }
        Value::Array(items) => {
            for child in items {
                collect_osv_vulnerabilities(child, package_hint.clone(), diagnostics);
            }
        }
        _ => {}
    }
}

fn collect_checkov_failed_checks(value: &Value, diagnostics: &mut Vec<ExternalDiagnostic>) {
    match value {
        Value::Object(map) => {
            if let Some(failed) = map.get("failed_checks").and_then(Value::as_array) {
                for check in failed {
                    let check_id = check
                        .get("check_id")
                        .and_then(Value::as_str)
                        .unwrap_or("CHECKOV");
                    diagnostics.push(ExternalDiagnostic {
                        source_tool: "checkov".to_string(),
                        rule_id: format!("terraform/checkov/{check_id}"),
                        path: PathBuf::from(
                            check
                                .get("file_path")
                                .and_then(Value::as_str)
                                .unwrap_or(".")
                                .trim_start_matches('/'),
                        ),
                        line: check
                            .get("file_line_range")
                            .and_then(Value::as_array)
                            .and_then(|lines| lines.first())
                            .and_then(Value::as_u64)
                            .and_then(|value| u32::try_from(value).ok()),
                        column: None,
                        message: check
                            .get("check_name")
                            .and_then(Value::as_str)
                            .unwrap_or("Checkov failed check")
                            .to_string(),
                        severity: Severity::Warning,
                    });
                }
            }
            for child in map.values() {
                collect_checkov_failed_checks(child, diagnostics);
            }
        }
        Value::Array(items) => {
            for child in items {
                collect_checkov_failed_checks(child, diagnostics);
            }
        }
        _ => {}
    }
}

fn lint_severity(value: Option<&str>) -> Severity {
    match value.unwrap_or("").to_ascii_lowercase().as_str() {
        "critical" => Severity::Critical,
        "error" => Severity::Error,
        "warning" | "warn" => Severity::Warning,
        _ => Severity::Info,
    }
}

fn brakeman_confidence_severity(value: Option<&str>) -> Severity {
    match value.unwrap_or("").to_ascii_lowercase().as_str() {
        "high" => Severity::Error,
        "medium" => Severity::Warning,
        _ => Severity::Info,
    }
}

fn slug(value: &str) -> String {
    let normalized = value
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() {
                ch.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>();
    let slug = normalized
        .split('-')
        .filter(|part| !part.is_empty())
        .collect::<Vec<_>>()
        .join("-");
    if slug.is_empty() {
        "diagnostic".to_string()
    } else {
        slug
    }
}

fn parse_colon_diagnostic(
    source_tool: &str,
    rule_id: &str,
    line: &str,
) -> Option<ExternalDiagnostic> {
    let trimmed = line.trim();
    let (path, rest) = trimmed.split_once(':')?;
    let (line_no, rest) = rest.split_once(':')?;
    let line_no = line_no.parse::<u32>().ok()?;
    let (column, message) = match rest.split_once(':') {
        Some((column, message)) => (column.parse::<u32>().ok(), message.trim()),
        None => (None, rest.trim()),
    };
    if message.is_empty() {
        return None;
    }
    let lower = message.to_ascii_lowercase();
    Some(ExternalDiagnostic {
        source_tool: source_tool.to_string(),
        rule_id: rule_id.to_string(),
        path: PathBuf::from(path),
        line: Some(line_no),
        column,
        message: message.to_string(),
        severity: if lower.contains("error") || lower.contains("failed") {
            Severity::Error
        } else {
            Severity::Warning
        },
    })
}

fn sarif_result_severity(result: &Value) -> Severity {
    result
        .get("level")
        .and_then(Value::as_str)
        .map(|level| match level {
            "error" => Severity::Error,
            "warning" => Severity::Warning,
            "note" => Severity::Info,
            _ => Severity::Info,
        })
        .unwrap_or(Severity::Warning)
}

fn osv_severity(map: &serde_json::Map<String, Value>) -> Severity {
    map.get("database_specific")
        .and_then(|value| value.get("severity"))
        .or_else(|| {
            map.get("severity")
                .and_then(Value::as_array)
                .and_then(|items| items.first())
                .and_then(|item| item.get("score").or_else(|| item.get("type")))
        })
        .and_then(Value::as_str)
        .map(vulnerability_severity)
        .unwrap_or(Severity::Warning)
}

fn vulnerability_severity(value: &str) -> Severity {
    let lower = value.to_ascii_lowercase();
    if lower.contains("critical") || lower.starts_with("9.") || lower.starts_with("10") {
        Severity::Critical
    } else if lower.contains("high") || lower.starts_with('7') || lower.starts_with('8') {
        Severity::Error
    } else if lower.contains("medium")
        || lower.contains("moderate")
        || lower.starts_with('4')
        || lower.starts_with('5')
        || lower.starts_with('6')
    {
        Severity::Warning
    } else {
        Severity::Info
    }
}

fn parse_java_tool_location(source_tool: &str, line: &str) -> Option<ExternalDiagnostic> {
    let (prefix, message) = line.split_once(']')?;
    let (path, location) = prefix.rsplit_once(":[")?;
    let mut parts = location.split(',');
    let line_no = parts.next()?.parse::<u32>().ok()?;
    let column = parts.next().and_then(|value| value.parse::<u32>().ok());
    Some(ExternalDiagnostic {
        source_tool: source_tool.to_string(),
        rule_id: format!("java/{source_tool}"),
        path: PathBuf::from(path),
        line: Some(line_no),
        column,
        message: message.trim_start_matches(':').trim().to_string(),
        severity: Severity::Warning,
    })
}

fn xml_attr(line: &str, name: &str) -> Option<String> {
    let needle = format!("{name}=\"");
    let (_, rest) = line.split_once(&needle)?;
    let (value, _) = rest.split_once('"')?;
    Some(value.to_string())
}

fn xml_text(line: &str, name: &str) -> Option<String> {
    let open = format!("<{name}>");
    let close = format!("</{name}>");
    let (_, rest) = line.split_once(&open)?;
    let (value, _) = rest.split_once(&close)?;
    Some(value.trim().to_string())
}

fn java_severity(value: &str) -> Severity {
    match value.to_ascii_lowercase().as_str() {
        "critical" => Severity::Critical,
        "high" => Severity::Error,
        "medium" | "moderate" => Severity::Warning,
        _ => Severity::Info,
    }
}

fn npm_severity(value: &str) -> Severity {
    match value.to_ascii_lowercase().as_str() {
        "critical" => Severity::Critical,
        "high" => Severity::Error,
        "moderate" | "medium" => Severity::Warning,
        "low" => Severity::Info,
        _ => Severity::Info,
    }
}

