#[must_use]
pub fn parse_go_test_text(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            if line.starts_with("--- FAIL:") || line.starts_with("FAIL") {
                return Some(ExternalDiagnostic {
                    source_tool: "go test".to_string(),
                    rule_id: "go/test-failure".to_string(),
                    path: PathBuf::from("."),
                    line: None,
                    column: None,
                    message: line.trim().to_string(),
                    severity: Severity::Error,
                });
            }
            parse_tool_line("go test", line).map(|mut diagnostic| {
                diagnostic.rule_id = "go/test-failure".to_string();
                diagnostic.severity = Severity::Error;
                diagnostic
            })
        })
        .collect()
}

#[must_use]
pub fn parse_go_list_json(output: &str) -> Vec<GoListPackage> {
    let mut packages = Vec::new();
    for value in parse_json_stream(output) {
        let Some(import_path) = value.get("ImportPath").and_then(Value::as_str) else {
            continue;
        };
        let dir = value.get("Dir").and_then(Value::as_str).map(PathBuf::from);
        let mut files = Vec::new();
        for key in ["GoFiles", "CgoFiles", "TestGoFiles", "XTestGoFiles"] {
            if let Some(items) = value.get(key).and_then(Value::as_array) {
                files.extend(items.iter().filter_map(Value::as_str).map(PathBuf::from));
            }
        }
        files.sort();
        files.dedup();
        let error = value
            .get("Error")
            .and_then(|error| error.get("Err").or(Some(error)))
            .and_then(Value::as_str)
            .map(str::to_string);
        packages.push(GoListPackage {
            import_path: import_path.to_string(),
            dir,
            files,
            error,
        });
    }
    packages
}

fn parse_json_stream(output: &str) -> Vec<Value> {
    let mut values = Vec::new();
    let mut depth = 0i32;
    let mut in_string = false;
    let mut escaped = false;
    let mut start = None;
    for (index, ch) in output.char_indices() {
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }
        match ch {
            '"' => in_string = true,
            '{' => {
                if depth == 0 {
                    start = Some(index);
                }
                depth += 1;
            }
            '}' => {
                depth -= 1;
                if depth == 0 {
                    if let Some(start_index) = start.take() {
                        if let Ok(value) =
                            serde_json::from_str::<Value>(&output[start_index..=index])
                        {
                            values.push(value);
                        }
                    }
                }
            }
            _ => {}
        }
    }
    values
}

#[must_use]
pub fn parse_staticcheck_text(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| {
            parse_tool_line("staticcheck", line).map(|mut diagnostic| {
                if let Some(code) = line
                    .rsplit('(')
                    .next()
                    .and_then(|tail| tail.strip_suffix(')'))
                {
                    if code
                        .chars()
                        .all(|ch| ch.is_ascii_uppercase() || ch.is_ascii_digit())
                    {
                        diagnostic.rule_id = format!("go/staticcheck/{code}");
                    }
                }
                diagnostic
            })
        })
        .collect()
}

#[must_use]
pub fn parse_staticcheck_json(output: &str) -> Vec<ExternalDiagnostic> {
    output
        .lines()
        .filter_map(|line| serde_json::from_str::<Value>(line).ok())
        .filter_map(|value| {
            let location = value.get("location")?;
            let file = location.get("file")?.as_str()?;
            let line = location
                .get("line")
                .and_then(Value::as_u64)
                .and_then(|value| u32::try_from(value).ok());
            let column = location
                .get("column")
                .and_then(Value::as_u64)
                .and_then(|value| u32::try_from(value).ok());
            let code = value
                .get("code")
                .and_then(Value::as_str)
                .unwrap_or("diagnostic");
            let message = value
                .get("message")
                .and_then(Value::as_str)
                .unwrap_or("staticcheck diagnostic");
            Some(ExternalDiagnostic {
                source_tool: "staticcheck".to_string(),
                rule_id: format!("go/staticcheck/{code}"),
                path: PathBuf::from(file),
                line,
                column,
                message: message.to_string(),
                severity: Severity::Warning,
            })
        })
        .collect()
}

#[must_use]
pub fn parse_govulncheck_json(output: &str) -> Vec<ExternalDiagnostic> {
    let Ok(value) = serde_json::from_str::<Value>(output) else {
        return Vec::new();
    };
    let mut diagnostics = Vec::new();
    collect_govulncheck_findings(&value, &mut diagnostics);
    diagnostics
}

fn collect_govulncheck_findings(value: &Value, diagnostics: &mut Vec<ExternalDiagnostic>) {
    match value {
        Value::Object(map) => {
            let osvid = map
                .get("osv")
                .and_then(|osv| osv.get("id"))
                .or_else(|| map.get("osv_id"))
                .or_else(|| map.get("id"))
                .and_then(Value::as_str);
            if let Some(osvid) = osvid {
                let message = map
                    .get("summary")
                    .or_else(|| map.get("message"))
                    .and_then(Value::as_str)
                    .unwrap_or("govulncheck vulnerability");
                diagnostics.push(ExternalDiagnostic {
                    source_tool: "govulncheck".to_string(),
                    rule_id: format!("go/govulncheck/{osvid}"),
                    path: PathBuf::from("."),
                    line: None,
                    column: None,
                    message: message.to_string(),
                    severity: Severity::Critical,
                });
            }
            for child in map.values() {
                collect_govulncheck_findings(child, diagnostics);
            }
        }
        Value::Array(items) => {
            for child in items {
                collect_govulncheck_findings(child, diagnostics);
            }
        }
        _ => {}
    }
}

fn parse_tool_line(source_tool: &str, line: &str) -> Option<ExternalDiagnostic> {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return None;
    }
    let (path, line_no, column, message) = parse_location_prefix(trimmed)?;
    Some(ExternalDiagnostic {
        source_tool: source_tool.to_string(),
        rule_id: format!("go/{}", source_tool.replace(' ', "-")),
        path,
        line: line_no,
        column,
        message,
        severity: Severity::Warning,
    })
}

fn parse_location_prefix(line: &str) -> Option<(PathBuf, Option<u32>, Option<u32>, String)> {
    let parts = line.splitn(4, ':').collect::<Vec<_>>();
    if parts.len() < 3 {
        return None;
    }
    let line_no = parts[1].parse::<u32>().ok()?;
    if let Ok(column) = parts[2].parse::<u32>() {
        Some((
            PathBuf::from(parts[0]),
            Some(line_no),
            Some(column),
            parts.get(3).unwrap_or(&"").trim().to_string(),
        ))
    } else {
        Some((
            PathBuf::from(parts[0]),
            Some(line_no),
            None,
            parts[2..].join(":").trim().to_string(),
        ))
    }
}

#[must_use]
pub fn parse_go_source_facts(text: &str) -> GoSourceFacts {
    let code = strip_go_comments_and_strings(text);
    let lines = code.lines().collect::<Vec<_>>();
    let package = lines.iter().find_map(|line| {
        let trimmed = line.trim();
        trimmed
            .strip_prefix("package ")
            .map(str::trim)
            .filter(|name| !name.is_empty())
            .map(str::to_string)
    });
    let mut facts = GoSourceFacts {
        package,
        ..GoSourceFacts::default()
    };
    let raw_lines = text.lines().collect::<Vec<_>>();
    collect_go_imports(&raw_lines, &mut facts.imports);
    for (index, line) in lines.iter().enumerate() {
        let line_no = u32::try_from(index + 1).unwrap_or(u32::MAX);
        for call in go_calls_in_line(line) {
            facts.call_lines.entry(call).or_default().push(line_no);
        }
    }
    facts
}

fn collect_go_imports(lines: &[&str], imports: &mut BTreeSet<String>) {
    let mut in_block = false;
    for line in lines {
        let trimmed = line.trim();
        if trimmed.starts_with("import (") {
            in_block = true;
            continue;
        }
        if in_block {
            if trimmed.starts_with(')') {
                in_block = false;
                continue;
            }
            if let Some(import) = quoted_go_import(trimmed) {
                imports.insert(import);
            }
            continue;
        }
        if let Some(rest) = trimmed.strip_prefix("import ") {
            if let Some(import) = quoted_go_import(rest.trim()) {
                imports.insert(import);
            }
        }
    }
}

fn quoted_go_import(line: &str) -> Option<String> {
    let start = line.find('"')?;
    let rest = &line[start + 1..];
    let end = rest.find('"')?;
    Some(rest[..end].to_string())
}

fn go_calls_in_line(line: &str) -> Vec<String> {
    let mut calls = Vec::new();
    let bytes = line.as_bytes();
    for (index, ch) in line.char_indices() {
        if ch != '(' || index == 0 {
            continue;
        }
        let mut start = index;
        while start > 0 {
            let previous = bytes[start - 1] as char;
            if previous.is_ascii_alphanumeric() || matches!(previous, '_' | '.') {
                start -= 1;
            } else {
                break;
            }
        }
        let candidate = line[start..index].trim_matches('.');
        if !candidate.is_empty()
            && candidate
                .chars()
                .next()
                .is_some_and(|ch| ch.is_ascii_alphabetic() || ch == '_')
        {
            calls.push(candidate.to_string());
        }
    }
    calls
}

fn strip_go_comments_and_strings(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    let mut in_line_comment = false;
    let mut in_block_comment = false;
    let mut in_string = false;
    let mut string_delimiter = '\0';
    let mut escaped = false;
    while let Some(ch) = chars.next() {
        if in_line_comment {
            if ch == '\n' {
                in_line_comment = false;
                out.push('\n');
            } else {
                out.push(' ');
            }
            continue;
        }
        if in_block_comment {
            if ch == '*' && chars.peek() == Some(&'/') {
                chars.next();
                in_block_comment = false;
                out.push_str("  ");
            } else if ch == '\n' {
                out.push('\n');
            } else {
                out.push(' ');
            }
            continue;
        }
        if in_string {
            if ch == '\n' {
                out.push('\n');
                if string_delimiter != '`' {
                    in_string = false;
                }
                continue;
            }
            if escaped {
                escaped = false;
            } else if ch == '\\' && string_delimiter != '`' {
                escaped = true;
            } else if ch == string_delimiter {
                in_string = false;
            }
            out.push(' ');
            continue;
        }
        if ch == '/' && chars.peek() == Some(&'/') {
            chars.next();
            in_line_comment = true;
            out.push_str("  ");
        } else if ch == '/' && chars.peek() == Some(&'*') {
            chars.next();
            in_block_comment = true;
            out.push_str("  ");
        } else if matches!(ch, '"' | '\'' | '`') {
            in_string = true;
            string_delimiter = ch;
            out.push(' ');
        } else {
            out.push(ch);
        }
    }
    out
}

fn go_rules() -> Vec<RuleMetadata> {
    vec![
        go_rule("go/channel-send-without-select", "Channel send outside select", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["go", "concurrency"], "A blocking send can leak a goroutine when the receiver exits.", "Guard blocking sends with select and a context cancellation case."),
        go_rule("go/context-background-in-request-path", "Background context in request path", Category::Reliability, Severity::Warning, Confidence::High, FixSafety::Guided, &["go", "context"], "Using context.Background in handlers drops request cancellation and deadlines.", "Thread the request context through downstream calls instead of constructing a background context."),
        go_rule("go/error-ignored", "Ignored error", Category::Correctness, Severity::Error, Confidence::High, FixSafety::Guided, &["go", "errors"], "Ignoring errors hides failed I/O, serialization, database, and network operations.", "Check and handle the error, or document an intentional ignore with a narrow suppression."),
        go_rule("go/fake-test-coverage", "Test lacks meaningful assertions", Category::Testing, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["go", "testing"], "A test with no failure path can pass while exercising little behavior.", "Assert observable behavior and call t.Fatal, t.Error, require, or assert on failure."),
        go_rule("go/fiber-cors-wildcard", "Fiber CORS allows every origin", Category::Security, Severity::Error, Confidence::High, FixSafety::Guided, &["go", "fiber", "cors"], "Wildcard CORS can expose authenticated browser APIs to untrusted sites.", "Restrict CORS origins to explicit trusted hosts."),
        go_rule("go/gin-route-missing-auth", "Gin route appears unauthenticated", Category::Security, Severity::Warning, Confidence::Low, FixSafety::Guided, &["go", "gin", "auth"], "Sensitive routes registered without nearby middleware may bypass authorization.", "Attach authentication middleware to route groups or document why the route is public."),
        go_rule("go/duplicate-dto-shape", "Duplicate DTO shape", Category::Architecture, Severity::Info, Confidence::Medium, FixSafety::Guided, &["go", "dto", "semantic"], "Repeated request/response struct shapes can drift when validations, JSON tags, or API contracts change in only one place.", "Extract a shared DTO or document why the wire contracts must remain separate."),
        go_rule("go/global-mutable-state", "Global mutable state", Category::Architecture, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["go", "state"], "Package-level mutable state creates hidden coupling and test bleed.", "Prefer dependency injection or immutable configuration passed at startup."),
        go_rule("go/gofmt-required", "Go file needs formatting", Category::Maintainability, Severity::Warning, Confidence::Medium, FixSafety::Safe, &["go", "format"], "Non-gofmt formatting causes noisy diffs and hides semantic changes.", "Run gofmt on the file."),
        go_rule("go/goroutine-without-cancellation", "Goroutine lacks cancellation", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["go", "concurrency", "context"], "Detached goroutines can leak after requests or services shut down.", "Pass context into the goroutine and exit on ctx.Done()."),
        go_rule("go/handler-bypasses-service-layer", "Handler bypasses service layer", Category::Architecture, Severity::Warning, Confidence::Low, FixSafety::Guided, &["go", "architecture"], "Database access in handlers couples transport logic to persistence.", "Move business and persistence work behind a service/repository boundary."),
        go_rule("go/http-client-no-timeout", "HTTP client without timeout", Category::Reliability, Severity::Error, Confidence::High, FixSafety::Guided, &["go", "http", "timeout"], "HTTP clients without timeouts can hang indefinitely and exhaust workers.", "Configure Timeout on http.Client or use a shared client with bounded request contexts."),
        go_rule("go/log-fatal-in-library", "log.Fatal in library package", Category::Reliability, Severity::Error, Confidence::High, FixSafety::Guided, &["go", "errors"], "log.Fatal exits the process from code that callers cannot recover from.", "Return errors from library code and let main decide whether to exit."),
        go_rule("go/missing-health-endpoint", "Missing health endpoint", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["go", "http", "operations"], "Services without health endpoints are harder to operate and roll out safely.", "Expose a lightweight /health or /ready endpoint."),
        go_rule("go/panic-in-handler", "Panic in request handler", Category::Reliability, Severity::Error, Confidence::High, FixSafety::Guided, &["go", "http"], "Panics in handlers can drop requests and rely on framework recovery behavior.", "Return typed errors or HTTP responses instead of panicking."),
        go_rule("go/request-without-context-deadline", "Request created without context deadline", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["go", "http", "context"], "Outbound requests without context deadlines can outlive the caller.", "Use http.NewRequestWithContext with a context that has a timeout or deadline."),
        go_rule("go/response-body-not-closed", "HTTP response body not closed", Category::Reliability, Severity::Error, Confidence::High, FixSafety::Guided, &["go", "http", "resources"], "Unclosed response bodies leak sockets and prevent connection reuse.", "Defer resp.Body.Close after checking the request error."),
        go_rule("go/sql-string-concat", "SQL built with string concatenation", Category::Security, Severity::Critical, Confidence::Medium, FixSafety::Guided, &["go", "sql", "injection"], "Building SQL with string concatenation can introduce injection bugs.", "Use parameterized queries and pass user input as arguments."),
        go_rule("go/transaction-across-remote-call", "Transaction spans remote call", Category::Reliability, Severity::Warning, Confidence::Low, FixSafety::Guided, &["go", "sql", "http"], "Holding database transactions across network calls increases lock time and failure coupling.", "Move remote calls outside the transaction or persist an intermediate state."),
        go_rule("go/unbounded-retry-loop", "Unbounded retry loop", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["go", "retry"], "Infinite retries can amplify outages and burn resources.", "Bound retry attempts and add backoff with context cancellation."),
    ]
}

fn core_rules() -> Vec<RuleMetadata> {
    vec![RuleMetadata {
        id: "core/unsupported-language-coverage".to_string(),
        title: "Language has generic coverage only".to_string(),
        category: Category::Maintainability,
        default_severity: Severity::Info,
        default_confidence: Confidence::High,
        languages: Vec::new(),
        frameworks: Vec::new(),
        tags: vec!["coverage".to_string(), "maturity".to_string()],
        cwe: Vec::new(),
        owasp: Vec::new(),
        fixability: FixSafety::None,
        enabled_by_default: true,
        supports_diff_mode: true,
        docs: None,
        explanation: "The language was detected, but Backend Doctor currently applies detection-only language coverage plus generic security, dependency, and infrastructure checks.".to_string(),
        remediation: "Review the coverage summary and run language-specific linters or tests for deeper analysis.".to_string(),
    }]
}

fn agent_rules() -> Vec<RuleMetadata> {
    vec![
        agent_rule("agent/placeholder-test", "Test appears to be a placeholder", Category::Testing, Severity::Warning, Confidence::Medium, &["testing"], "Tests without assertions or failure paths can pass while proving little behavior.", "Replace placeholder tests with assertions that exercise observable behavior and fail on regression."),
        agent_rule("agent/production-placeholder", "Production code contains placeholder behavior", Category::Maintainability, Severity::Warning, Confidence::Medium, &["placeholder"], "TODO, placeholder, and not-implemented paths in production code can ship incomplete behavior.", "Replace the placeholder with implemented behavior or remove the path before release."),
        agent_rule("agent/semantic-copy-paste", "Repeated semantic shape detected", Category::Architecture, Severity::Info, Confidence::Medium, &["duplication", "semantic"], "Repeated DTO/helper shapes are observable maintenance risks because fixes and validations can diverge across copies.", "Consolidate the repeated shape or add a narrow suppression explaining why the contracts intentionally stay separate."),
        agent_rule("agent/spaghetti-control-flow", "Deeply nested control flow detected", Category::Maintainability, Severity::Warning, Confidence::Medium, &["complexity", "spaghetti"], "Deeply nested branch-heavy functions are hard to review and easy to break when adding edge cases.", "Extract named helpers or table-driven branches until the control flow can be tested in smaller pieces."),
        agent_rule("agent/swallowed-error", "Error handling appears to swallow failures", Category::Correctness, Severity::Error, Confidence::Medium, &["errors"], "Empty or ignored error paths hide operational failures from callers and telemetry.", "Handle the error explicitly by returning, logging, retrying with bounds, or documenting a narrow suppression."),
    ]
}

#[allow(clippy::too_many_arguments)]
fn agent_rule(
    id: &str,
    title: &str,
    category: Category,
    severity: Severity,
    confidence: Confidence,
    tags: &[&str],
    explanation: &str,
    remediation: &str,
) -> RuleMetadata {
    RuleMetadata {
        id: id.to_string(),
        title: title.to_string(),
        category,
        default_severity: severity,
        default_confidence: confidence,
        languages: vec![
            "Go".to_string(),
            "Java".to_string(),
            "Node/TypeScript".to_string(),
        ],
        frameworks: Vec::new(),
        tags: tags
            .iter()
            .map(|tag| (*tag).to_string())
            .chain(["agent-pattern".to_string()])
            .collect(),
        cwe: Vec::new(),
        owasp: Vec::new(),
        fixability: FixSafety::Guided,
        enabled_by_default: true,
        supports_diff_mode: true,
        docs: None,
        explanation: explanation.to_string(),
        remediation: remediation.to_string(),
    }
}

#[allow(clippy::too_many_arguments)]
fn go_rule(
    id: &str,
    title: &str,
    category: Category,
    severity: Severity,
    confidence: Confidence,
    fixability: FixSafety,
    tags: &[&str],
    explanation: &str,
    remediation: &str,
) -> RuleMetadata {
    RuleMetadata {
        id: id.to_string(),
        title: title.to_string(),
        category,
        default_severity: severity,
        default_confidence: confidence,
        languages: vec!["Go".to_string()],
        frameworks: framework_tags(tags),
        tags: tags.iter().map(|tag| (*tag).to_string()).collect(),
        cwe: cwe_for(id),
        owasp: Vec::new(),
        fixability,
        enabled_by_default: true,
        supports_diff_mode: true,
        docs: None,
        explanation: explanation.to_string(),
        remediation: remediation.to_string(),
    }
}

fn framework_tags(tags: &[&str]) -> Vec<String> {
    tags.iter()
        .filter_map(|tag| match *tag {
            "gin" => Some("Gin"),
            "echo" => Some("Echo"),
            "fiber" => Some("Fiber"),
            "chi" => Some("Chi"),
            "grpc" => Some("gRPC"),
            _ => None,
        })
        .map(str::to_string)
        .collect()
}

fn cwe_for(id: &str) -> Vec<String> {
    match id {
        "go/sql-string-concat" => vec!["CWE-89".to_string()],
        "go/fiber-cors-wildcard" => vec!["CWE-942".to_string()],
        "node/eval-or-function-constructor" => vec!["CWE-95".to_string()],
        "node/child-process-shell-injection" => vec!["CWE-78".to_string()],
        "node/sql-string-concat" => vec!["CWE-89".to_string()],
        "node/cors-wildcard-production" => vec!["CWE-942".to_string()],
        "java/sql-string-concat" => vec!["CWE-89".to_string()],
        "java/hardcoded-spring-secret" => vec!["CWE-798".to_string()],
        "java/actuator-exposed-sensitive-endpoints" => vec!["CWE-200".to_string()],
        "python/sql-string-format"
        | "csharp/sql-string-interpolation"
        | "php/pdo-query-string-concat"
        | "rust/sql-format-string"
        | "ruby/sql-string-interpolation"
        | "kotlin/unsafe-sql-string-template"
        | "scala/unsafe-sql-interpolation" => vec!["CWE-89".to_string()],
        "python/subprocess-shell-true"
        | "php/shell-exec-user-input"
        | "rust/command-shell-format" => vec!["CWE-78".to_string()],
        "python/unsafe-yaml-load" | "php/unserialize-user-input" => vec!["CWE-502".to_string()],
        "elixir/unsafe-atom-conversion" => vec!["CWE-400".to_string()],
        "c/unsafe-gets" | "cpp/unsafe-strcpy" => vec!["CWE-120".to_string()],
        "csharp/cors-allow-any-origin" | "rust/cors-allow-any-origin" => {
            vec!["CWE-942".to_string()]
        }
        _ => Vec::new(),
    }
}

fn node_rules() -> Vec<RuleMetadata> {
    vec![
        node_rule("node/floating-promise", "Promise is not awaited", Category::Correctness, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "typescript", "async"], "Unawaited promises can reject outside the request path and bypass error handling.", "Await the promise, return it, or explicitly detach it with void plus rejection handling.", true),
        node_rule("node/express-async-error-unhandled", "Express async handler lacks error forwarding", Category::Reliability, Severity::Error, Confidence::Medium, FixSafety::Guided, &["node", "express"], "Express 4 does not automatically route async rejections to error middleware.", "Wrap async handlers or call next(error) from a catch block.", true),
        node_rule("node/route-missing-validation", "Route reads request input without validation", Category::Security, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "express", "validation"], "Request body, query, or params are consumed without an obvious schema or validator.", "Validate request input with a schema library or middleware before using it.", true),
        node_rule("node/route-missing-auth", "Sensitive route lacks obvious auth middleware", Category::Security, Severity::Warning, Confidence::Low, FixSafety::Guided, &["node", "express", "auth"], "Sensitive-looking routes registered without nearby auth middleware can bypass authorization.", "Attach authentication middleware to protected route groups or document that the route is public.", true),
        node_rule("node/cors-wildcard-production", "CORS allows every origin", Category::Security, Severity::Error, Confidence::High, FixSafety::Guided, &["node", "express", "cors"], "Wildcard CORS can expose authenticated browser APIs to untrusted sites.", "Restrict CORS origins to explicit trusted hosts in production.", true),
        node_rule("node/no-rate-limit-on-auth-route", "Auth route lacks rate limiting", Category::Security, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "express", "rate-limit"], "Login and token routes without rate limiting are easier to brute force.", "Apply rate limiting middleware to authentication routes.", true),
        node_rule("node/eval-or-function-constructor", "Dynamic code execution", Category::Security, Severity::Critical, Confidence::High, FixSafety::Guided, &["node", "injection"], "eval and Function execute strings as code and can turn input bugs into remote code execution.", "Replace dynamic code execution with explicit dispatch or a constrained parser.", true),
        node_rule("node/child-process-shell-injection", "Child process command uses shell-like string interpolation", Category::Security, Severity::Critical, Confidence::Medium, FixSafety::Guided, &["node", "child-process"], "Interpolated shell commands can execute attacker-controlled arguments.", "Use execFile or spawn with an argument array and strict input allowlists.", true),
        node_rule("node/sql-string-concat", "SQL built with string concatenation", Category::Security, Severity::Critical, Confidence::Medium, FixSafety::Guided, &["node", "sql", "injection"], "Building SQL with string concatenation can introduce injection bugs.", "Use parameterized queries or ORM parameter binding.", true),
        node_rule("node/prisma-unbounded-findmany", "Prisma findMany lacks bounds", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "prisma"], "Unbounded findMany calls can return excessive rows and overload services.", "Add take, cursor, pagination, or a bounded where clause.", true),
        node_rule("node/unbounded-json-body", "JSON body parser lacks size limit", Category::Reliability, Severity::Warning, Confidence::High, FixSafety::Guided, &["node", "express"], "Unbounded JSON body parsing can consume memory on large requests.", "Set an explicit size limit for JSON body parsing.", true),
        node_rule("node/no-timeout-server-or-client", "Server or HTTP client lacks timeout", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "timeout"], "Servers and outbound clients without timeouts can hang indefinitely.", "Configure request, headers, and client timeouts appropriate to the service.", true),
        node_rule("node/console-log-production", "Production code uses console logging", Category::Maintainability, Severity::Warning, Confidence::Medium, FixSafety::Safe, &["node", "eslint"], "Console logging in production code is noisy and can leak operational context.", "Use a structured logger or remove debug logging.", true),
        node_rule("node/overbroad-any", "Overbroad TypeScript any", Category::Maintainability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "typescript"], "any disables useful type checking at service boundaries.", "Replace any with precise types, unknown plus narrowing, or DTO interfaces.", true),
        node_rule("node/duplicate-dto-shape", "Duplicate DTO shape", Category::Architecture, Severity::Info, Confidence::Medium, FixSafety::Guided, &["node", "typescript", "dto", "semantic"], "Repeated request/response interface or type-literal shapes can drift when validation and API contracts evolve.", "Extract a shared DTO type or document why the public contracts must remain separate.", true),
        node_rule("node/generated-placeholder-test", "Generated placeholder test", Category::Testing, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "testing"], "Placeholder tests can pass without verifying behavior.", "Assert observable behavior and include a failure path.", true),
        node_rule("node/express-error-handler-missing", "Express error middleware missing", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "express"], "Express apps without error middleware can leak default errors and miss structured logging.", "Add a final four-argument error handling middleware.", true),
        node_rule("node/missing-lockfile", "Node package lacks lockfile", Category::Dependencies, Severity::Warning, Confidence::High, FixSafety::Guided, &["node", "dependencies"], "A package manifest without a lockfile weakens deterministic installs.", "Commit the lockfile for the package manager used by this service.", true),
        node_rule("node/multiple-lockfiles", "Multiple Node lockfiles", Category::Dependencies, Severity::Warning, Confidence::High, FixSafety::Guided, &["node", "dependencies"], "Multiple package-manager lockfiles make installs ambiguous.", "Keep only the lockfile for the intended package manager.", true),
        node_rule("node/dead-export", "Export is not imported inside the service", Category::Maintainability, Severity::Info, Confidence::Low, FixSafety::Guided, &["node", "typescript", "import-graph"], "Unused exported symbols add API surface and make refactors harder. This conservative graph check ignores entrypoint files and default exports.", "Remove the export, make it private, or add an explicit internal import if it is part of a dynamic/plugin contract.", true),
        node_rule("node/circular-import-risk", "Import cycle detected", Category::Architecture, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["node", "typescript", "import-graph"], "Circular imports can create partially initialized modules and fragile load ordering.", "Break the cycle by moving shared contracts to a lower-level module or inverting the dependency.", true),
    ]
}

#[allow(clippy::too_many_arguments)]
