fn java_rules() -> Vec<RuleMetadata> {
    vec![
        java_rule("java/http-client-no-timeout", "Java HTTP client without timeout", Category::Reliability, Severity::Error, Confidence::High, FixSafety::Guided, &["java", "spring", "timeout"], "HTTP clients without connect/read/response timeouts can hang request workers.", "Configure bounded connect and read/response timeouts on RestTemplate, WebClient, or HttpClient."),
        java_rule("java/controller-bypasses-service-layer", "Controller bypasses service layer", Category::Architecture, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["java", "spring", "layers"], "Controllers that call repositories directly couple transport code to persistence.", "Route controller work through an application service."),
        java_rule("java/missing-request-validation", "Request body lacks validation", Category::Security, Severity::Warning, Confidence::High, FixSafety::Guided, &["java", "spring", "validation"], "Spring will deserialize request bodies without bean validation unless @Valid or @Validated is present.", "Annotate request DTO parameters with @Valid and define validation constraints on the DTO."),
        java_rule("java/missing-auth-annotation-or-filter", "Sensitive endpoint lacks obvious auth", Category::Security, Severity::Warning, Confidence::Low, FixSafety::Guided, &["java", "spring", "auth"], "Sensitive controllers without method security or a filter chain can expose protected operations.", "Add method authorization such as @PreAuthorize or configure a SecurityFilterChain."),
        java_rule("java/duplicate-dto-shape", "Duplicate DTO shape", Category::Architecture, Severity::Info, Confidence::Medium, FixSafety::Guided, &["java", "spring", "dto", "semantic"], "Repeated request/response DTO field shapes can drift when validation annotations or API contracts change in only one copy.", "Extract a shared DTO, use composition, or document why the contracts must remain separate."),
        java_rule("java/transactional-remote-call", "Transaction spans remote call", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["java", "spring", "transaction"], "Holding database transactions while waiting on remote services extends lock duration and couples rollback to network failures.", "Move remote calls outside @Transactional methods or persist state before making the call."),
        java_rule("java/transactional-private-method", "Private @Transactional method", Category::Correctness, Severity::Warning, Confidence::High, FixSafety::Guided, &["java", "spring", "transaction"], "Spring proxy-based transactions do not apply to private methods.", "Make the transactional boundary public on a proxied bean or move it to another service."),
        java_rule("java/blocking-call-in-reactive-flow", "Blocking call in reactive flow", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["java", "spring", "reactive"], "Blocking inside WebFlux or Reactor flows can starve event-loop threads.", "Keep the chain nonblocking or shift unavoidable blocking work to boundedElastic."),
        java_rule("java/sql-string-concat", "SQL built with string concatenation", Category::Security, Severity::Critical, Confidence::Medium, FixSafety::Guided, &["java", "sql", "injection"], "Building SQL or JPQL with string concatenation can introduce injection bugs.", "Use bind parameters, Criteria APIs, or repository methods."),
        java_rule("java/jpa-n-plus-one-risk", "JPA N+1 query risk", Category::Reliability, Severity::Warning, Confidence::Low, FixSafety::Guided, &["java", "jpa"], "Returning entity graphs or eager relationships can create hidden N+1 query behavior.", "Return DTOs and use fetch joins or entity graphs for deliberate loading."),
        java_rule("java/swallowed-exception", "Swallowed exception", Category::Correctness, Severity::Error, Confidence::Medium, FixSafety::Guided, &["java", "exceptions"], "Empty catch blocks hide failures from callers and logs.", "Log, rethrow, translate, or handle the exception explicitly."),
        java_rule("java/too-broad-exception", "Too broad exception catch", Category::Maintainability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["java", "exceptions"], "Catching Exception or Throwable makes error handling imprecise.", "Catch the narrow exception type that can be recovered from."),
        java_rule("java/system-out-in-backend", "System.out in backend code", Category::Maintainability, Severity::Warning, Confidence::High, FixSafety::Guided, &["java", "logging"], "System.out bypasses structured logging and runtime log controls.", "Use a framework logger such as SLF4J."),
        java_rule("java/hardcoded-spring-secret", "Hardcoded Spring secret", Category::Security, Severity::Critical, Confidence::High, FixSafety::Guided, &["java", "spring", "secret"], "Secrets committed in Spring configuration can leak credentials.", "Move secrets to environment-backed configuration or a secret manager."),
        java_rule("java/actuator-exposed-sensitive-endpoints", "Sensitive actuator endpoints exposed", Category::Security, Severity::Error, Confidence::High, FixSafety::Guided, &["java", "spring", "actuator"], "Exposing all actuator endpoints can leak environment, metrics, or heap data.", "Expose only health and info unless protected by strong authentication."),
        java_rule("java/open-session-in-view-enabled", "Open Session in View enabled", Category::Architecture, Severity::Warning, Confidence::High, FixSafety::Guided, &["java", "spring", "jpa"], "Open Session in View lets web rendering trigger lazy database access outside service boundaries.", "Set spring.jpa.open-in-view=false and load required data in the service layer."),
        java_rule("java/entity-returned-from-controller", "Controller returns JPA entity", Category::Architecture, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["java", "spring", "jpa"], "Returning entities from controllers leaks persistence shape into the API contract.", "Map entities to response DTOs before returning."),
        java_rule("java/missing-health-readiness", "Missing readiness health exposure", Category::Reliability, Severity::Warning, Confidence::Medium, FixSafety::Guided, &["java", "spring", "operations"], "Services without readiness health groups are harder to roll out safely.", "Enable Spring Boot health probes or define a readiness health endpoint."),
        java_rule("java/controller-service-layer-missing", "Spring service layer missing", Category::Architecture, Severity::Info, Confidence::Low, FixSafety::Guided, &["java", "spring", "layers"], "Spring controllers without a service layer leave little room for business logic boundaries.", "Introduce a @Service boundary for controller orchestration when the service grows."),
    ]
}

