fn looks_like_python_requests_without_timeout(line: &str) -> bool {
    [
        "requests.get(",
        "requests.post(",
        "requests.put(",
        "requests.delete(",
        "requests.request(",
    ]
    .iter()
    .any(|needle| line.contains(needle))
        && !line.contains("timeout=")
}

