fn catch_block_swallowed(lines: &[&str], index: usize) -> bool {
    let body = lines
        .iter()
        .skip(index)
        .take(8)
        .take_while(|line| !line.trim().starts_with('}') || line.trim() == "}")
        .map(|line| line.trim())
        .collect::<Vec<_>>()
        .join(" ");
    ![
        "throw ",
        "logger.",
        "log.",
        "return ",
        "System.err",
        "metrics.",
    ]
    .iter()
    .any(|needle| body.contains(needle))
}

fn java_class_name(lines: &[&str]) -> Option<String> {
    lines.iter().find_map(|line| {
        let trimmed = line.trim();
        let (_, rest) = trimmed.split_once(" class ")?;
        rest.split(|ch: char| !ch.is_ascii_alphanumeric() && ch != '_')
            .next()
            .filter(|name| !name.is_empty())
            .map(str::to_string)
    })
}

fn java_project_entity_names(graph: &ProjectGraph, service_id: &Option<String>) -> Vec<String> {
    let service_root = service_id.as_deref().map(Path::new);
    graph
        .inventory
        .files
        .iter()
        .filter(|path| {
            path.extension().is_some_and(|ext| ext == "java")
                && service_root.is_none_or(|root| root == Path::new(".") || path.starts_with(root))
        })
        .filter_map(|relative| {
            let text = fs::read_to_string(graph.root.join(relative)).ok()?;
            if text.contains("@Entity") {
                java_class_name(&text.lines().collect::<Vec<_>>())
            } else {
                None
            }
        })
        .collect()
}

fn java_service_has_security(graph: &ProjectGraph, service_id: &Option<String>) -> bool {
    let service_root = service_id.as_deref().map(Path::new);
    graph.inventory.files.iter().any(|relative| {
        relative.extension().is_some_and(|ext| ext == "java")
            && service_root.is_none_or(|root| root == Path::new(".") || relative.starts_with(root))
            && fs::read_to_string(graph.root.join(relative)).is_ok_and(|text| {
                text.contains("SecurityFilterChain")
                    || text.contains("@EnableMethodSecurity")
                    || text.contains("@PreAuthorize")
                    || text.contains("spring-boot-starter-security")
            })
    })
}

