fn scan_transaction_remote_call(
    graph: &ProjectGraph,
    service: &Option<String>,
    relative: &Path,
    text: &str,
    metadata: &BTreeMap<String, RuleMetadata>,
    disabled: &BTreeSet<String>,
    findings: &mut Vec<Finding>,
) {
    let lines = text.lines().collect::<Vec<_>>();
    for (index, line) in lines.iter().enumerate() {
        if !line.contains("BeginTx") && !line.contains(".Begin()") {
            continue;
        }
        let window = lines.iter().skip(index).take(40).collect::<Vec<_>>();
        let remote_before_commit = window.iter().position(|candidate| {
            candidate.contains("http.")
                || candidate.contains(".Do(")
                || candidate.contains("grpc.")
                || candidate.contains(".Invoke(")
        });
        let commit = window
            .iter()
            .position(|candidate| candidate.contains(".Commit()") || candidate.contains("Commit("));
        if remote_before_commit.is_some()
            && commit.is_some_and(|commit| remote_before_commit.unwrap_or(usize::MAX) < commit)
        {
            push_line_finding(graph, service, relative, text, metadata, disabled, findings, "go/transaction-across-remote-call", u32::try_from(index + 1).unwrap_or(u32::MAX), "Database transaction includes a remote call before commit.", "Avoid holding database transactions while waiting on remote services.", Some("Remote latency extends lock duration and makes rollback behavior harder to reason about."), None);
        }
    }
}

fn scan_fake_tests(
    graph: &ProjectGraph,
    service: &Option<String>,
    relative: &Path,
    text: &str,
    metadata: &BTreeMap<String, RuleMetadata>,
    disabled: &BTreeSet<String>,
    findings: &mut Vec<Finding>,
) {
    if !relative
        .file_name()
        .is_some_and(|name| name.to_string_lossy().ends_with("_test.go"))
    {
        return;
    }
    let lower = text.to_ascii_lowercase();
    let has_failure = lower.contains("t.error")
        || lower.contains("t.fatal")
        || lower.contains("require.")
        || lower.contains("assert.");
    if !has_failure {
        push_line_finding(
            graph,
            service,
            relative,
            text,
            metadata,
            disabled,
            findings,
            "go/fake-test-coverage",
            1,
            "Test file has no obvious assertion or failure path.",
            "Add assertions that fail the test when behavior regresses.",
            Some("Coverage without assertions can hide broken behavior."),
            None,
        );
    }
}

#[allow(clippy::too_many_arguments)]
fn push_generic_finding(
    graph: &ProjectGraph,
    relative: &Path,
    text: &str,
    metadata: &BTreeMap<String, RuleMetadata>,
    disabled: &BTreeSet<String>,
    findings: &mut Vec<Finding>,
    rule_id: &str,
    line: u32,
    message: &str,
    snippet: &str,
    secret_fingerprint: Option<String>,
    extra_metadata: BTreeMap<String, String>,
) {
    let Some(rule) = metadata.get(rule_id) else {
        return;
    };
    push_generic_finding_with_severity(
        graph,
        relative,
        text,
        metadata,
        disabled,
        findings,
        rule_id,
        rule.default_severity.clone(),
        line,
        message,
        snippet,
        secret_fingerprint,
        extra_metadata,
    );
}

#[allow(clippy::too_many_arguments)]
fn push_generic_finding_with_severity(
    graph: &ProjectGraph,
    relative: &Path,
    text: &str,
    metadata: &BTreeMap<String, RuleMetadata>,
    disabled: &BTreeSet<String>,
    findings: &mut Vec<Finding>,
    rule_id: &str,
    severity: Severity,
    line: u32,
    message: &str,
    snippet: &str,
    secret_fingerprint: Option<String>,
    extra_metadata: BTreeMap<String, String>,
) {
    if disabled.contains(rule_id) {
        return;
    }
    let Some(rule) = metadata.get(rule_id) else {
        return;
    };
    if !rule.enabled_by_default {
        return;
    }
    let service = service_for_path(graph, relative);
    let line_index = usize::try_from(line.saturating_sub(1)).unwrap_or(0);
    let column = text
        .lines()
        .nth(line_index)
        .and_then(|value| value.chars().position(|ch| !ch.is_whitespace()))
        .and_then(|value| u32::try_from(value + 1).ok());
    let evidence_redacted = secret_fingerprint.is_some()
        || rule.category == Category::Security
        || snippet.contains("[REDACTED]");
    let evidence_snippet = if evidence_redacted {
        backend_doctor_core::redact_text(snippet)
    } else {
        snippet.to_string()
    };
    let fingerprint = fingerprint(rule_id, relative, line, &evidence_snippet);
    findings.push(Finding {
        id: fingerprint.clone(),
        fingerprint,
        rule_id: rule_id.to_string(),
        tool: "backend-doctor-rules".to_string(),
        source_tool: "builtin-security".to_string(),
        title: rule.title.clone(),
        message: message.to_string(),
        category: rule.category.clone(),
        severity,
        confidence: rule.default_confidence.clone(),
        service: service.clone(),
        language: language_for_path(relative).or_else(|| {
            service.as_ref().and_then(|service_id| {
                graph
                    .services
                    .iter()
                    .find(|candidate| &candidate.id == service_id)
                    .and_then(|candidate| candidate.languages.first().cloned())
            })
        }),
        framework: framework_for(graph, &service),
        location: Some(Location {
            path: relative.to_path_buf(),
            line: Some(line),
            column,
            end_line: None,
            end_column: None,
        }),
        evidence: Some(Evidence {
            snippet: evidence_snippet,
            redacted: evidence_redacted,
            secret_fingerprint,
        }),
        impact: Some(rule.explanation.clone()),
        remediation: rule.remediation.clone(),
        fix: FixInfo {
            available: rule.fixability != FixSafety::None,
            safety: rule.fixability.clone(),
            description: None,
        },
        links: Vec::new(),
        metadata: extra_metadata,
        suppressed: false,
    });
}

fn is_security_text_file(path: &Path) -> bool {
    let name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("");
    if matches!(
        name,
        ".env"
            | ".env.local"
            | ".env.production"
            | "application.yml"
            | "application.yaml"
            | "application.properties"
            | "Dockerfile"
            | "docker-compose.yml"
            | "docker-compose.yaml"
            | "package.json"
            | "pom.xml"
            | "go.mod"
    ) {
        return true;
    }
    matches!(
        path.extension().and_then(|ext| ext.to_str()),
        Some(
            "env"
                | "json"
                | "yaml"
                | "yml"
                | "toml"
                | "ini"
                | "properties"
                | "conf"
                | "go"
                | "java"
                | "js"
                | "ts"
                | "tsx"
                | "jsx"
                | "py"
                | "rb"
                | "php"
                | "cs"
                | "rs"
                | "kt"
                | "kts"
                | "scala"
                | "ex"
                | "exs"
                | "c"
                | "h"
                | "cc"
                | "cpp"
                | "cxx"
                | "hpp"
                | "sh"
        )
    )
}

fn secret_value_from_line(line: &str) -> Option<&str> {
    let trimmed = line.trim();
    if trimmed.is_empty() || trimmed.starts_with('#') || trimmed.starts_with("//") {
        return None;
    }
    if looks_like_jwt(trimmed) {
        return Some(trimmed);
    }
    let lower = trimmed.to_ascii_lowercase();
    if lower.contains("example") || lower.contains("placeholder") {
        return None;
    }
    let secret_key = [
        "api_key",
        "apikey",
        "secret",
        "token",
        "password",
        "passwd",
        "pwd",
        "database_url",
        "authorization",
        "client_secret",
        "oauth",
    ]
    .iter()
    .any(|needle| lower.contains(needle));
    let assignment_value = trimmed
        .split_once('=')
        .or_else(|| trimmed.split_once(':'))
        .map(|(_, value)| {
            value
                .trim()
                .trim_matches(',')
                .trim_matches('"')
                .trim_matches('\'')
        });
    if lower.contains("postgres://")
        || lower.contains("postgresql://")
        || lower.contains("mysql://")
        || lower.contains("mongodb://")
    {
        return Some(assignment_value.unwrap_or(trimmed));
    }
    if !secret_key {
        return None;
    }

    if let Some(value) = assignment_value {
        if looks_like_env_var_reference_message(value) {
            return None;
        }
        return secret_candidate_from_expression(value);
    }

    secret_candidate_from_expression(trimmed)
}

fn secret_candidate_from_expression(value: &str) -> Option<&str> {
    let literals = quoted_string_literals(value);
    if !literals.is_empty() {
        return literals
            .into_iter()
            .filter(|literal| {
                !(looks_like_env_var_reference_message(literal.value)
                    || looks_like_env_var_lookup_arg(value, literal.quote_start)
                        && looks_like_env_var_name(literal.value))
            })
            .find_map(|literal| secret_candidate(literal.value));
    }

    if looks_like_env_var_lookup(value) || looks_like_env_var_reference_message(value) {
        return None;
    }

    secret_candidate(value)
}

#[derive(Clone, Copy)]
struct QuotedLiteral<'a> {
    value: &'a str,
    quote_start: usize,
}

fn secret_candidate(value: &str) -> Option<&str> {
    let candidate = value
        .strip_prefix("Bearer ")
        .unwrap_or(value)
        .trim_matches('"')
        .trim_matches('\'');
    let enough_entropy = candidate.len() >= 12
        && candidate.chars().any(|ch| ch.is_ascii_alphabetic())
        && (candidate.chars().any(|ch| ch.is_ascii_digit())
            || candidate.contains('_')
            || candidate.contains('-'));
    enough_entropy.then_some(candidate)
}

fn quoted_string_literals(line: &str) -> Vec<QuotedLiteral<'_>> {
    let mut literals = Vec::new();
    let mut start = None;
    let mut quote = b'\0';
    let mut escaped = false;

    for (index, byte) in line.bytes().enumerate() {
        if let Some((quote_start, literal_start)) = start {
            if escaped {
                escaped = false;
                continue;
            }
            if byte == b'\\' {
                escaped = true;
                continue;
            }
            if byte == quote {
                literals.push(QuotedLiteral {
                    value: &line[literal_start..index],
                    quote_start,
                });
                start = None;
            }
            continue;
        }

        if byte == b'"' || byte == b'\'' {
            start = Some((index, index + 1));
            quote = byte;
        }
    }

    literals
}

fn looks_like_env_var_lookup_arg(line: &str, quote_start: usize) -> bool {
    let prefix = line[..quote_start].trim_end().to_ascii_lowercase();
    prefix.ends_with("getenv(")
        || prefix.ends_with("getenvironmentvariable(")
        || prefix.ends_with("env::var(")
}

fn looks_like_env_var_reference_message(value: &str) -> bool {
    let trimmed = value.trim();
    let Some((name, message)) = trimmed.split_once(char::is_whitespace) else {
        return false;
    };
    if !looks_like_env_var_name(name) {
        return false;
    }

    matches!(
        message.trim().to_ascii_lowercase().as_str(),
        "is required" | "required" | "must be set" | "is missing" | "missing" | "not configured"
    )
}

fn looks_like_env_var_lookup(value: &str) -> bool {
    let lower = value.to_ascii_lowercase();
    if !(lower.contains("getenv(")
        || lower.contains("getenvironmentvariable(")
        || lower.contains("env::var(")
        || lower.contains("process.env."))
    {
        return false;
    }

    let literals = quoted_string_literals(value);
    if !literals.is_empty() {
        let mut lookup_literals = literals
            .iter()
            .filter(|literal| looks_like_env_var_lookup_arg(value, literal.quote_start))
            .peekable();
        return lookup_literals.peek().is_some()
            && lookup_literals.all(|literal| looks_like_env_var_name(literal.value));
    }

    value
        .trim()
        .strip_prefix("process.env.")
        .is_some_and(looks_like_env_var_name)
}

fn looks_like_env_var_name(value: &str) -> bool {
    let trimmed = value.trim_matches(|ch: char| !ch.is_ascii_alphanumeric() && ch != '_');
    trimmed.contains('_')
        && trimmed.chars().any(|ch| ch.is_ascii_alphabetic())
        && trimmed
            .chars()
            .all(|ch| ch.is_ascii_uppercase() || ch.is_ascii_digit() || ch == '_')
        && trimmed.chars().all(|ch| !ch.is_ascii_lowercase())
}

fn looks_like_jwt(value: &str) -> bool {
    let parts = value.split('.').collect::<Vec<_>>();
    parts.len() == 3
        && parts[0].starts_with("eyJ")
        && parts.iter().all(|part| {
            part.len() >= 8
                && part
                    .chars()
                    .all(|ch| ch.is_ascii_alphanumeric() || ch == '-' || ch == '_')
        })
}

fn redacted_secret_snippet(line: &str) -> String {
    let trimmed = line.trim();
    if let Some((key, _)) = trimmed.split_once('=') {
        return format!("{}=[REDACTED]", key.trim());
    }
    if let Some((key, _)) = trimmed.split_once(':') {
        return format!("{}: [REDACTED]", key.trim());
    }
    "[REDACTED secret-like value]".to_string()
}

fn secret_fingerprint(value: &str) -> String {
    fingerprint("secret", Path::new("."), 0, value)
}

fn looks_like_sensitive_logging(line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    let logs = lower.contains("console.log")
        || lower.contains("logger.")
        || lower.contains("log.")
        || lower.contains("system.out")
        || lower.contains("println!");
    logs && [
        "password",
        "token",
        "authorization",
        "cookie",
        "set-cookie",
        "api_key",
        "apikey",
        "secret",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
}

fn looks_like_curl_pipe_shell(line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    (lower.contains("curl ") || lower.contains("wget "))
        && lower.contains('|')
        && (lower.contains(" sh") || lower.contains(" bash") || lower.contains("sh -"))
}

fn is_dynamic_dependency_version(version: &str) -> bool {
    let trimmed = version.trim();
    trimmed == "*"
        || trimmed.eq_ignore_ascii_case("latest")
        || trimmed.starts_with('>')
        || trimmed.starts_with("http://")
        || trimmed.starts_with("https://")
}

fn is_commit_sha(value: &str) -> bool {
    value.len() == 40 && value.chars().all(|ch| ch.is_ascii_hexdigit())
}

fn line_containing(text: &str, needle: &str) -> Option<u32> {
    text.lines()
        .position(|line| line.contains(needle))
        .and_then(|index| u32::try_from(index + 1).ok())
}

fn package_metadata(manager: &str) -> BTreeMap<String, String> {
    let mut metadata = BTreeMap::new();
    metadata.insert("packageManager".to_string(), manager.to_string());
    metadata
}

fn language_for_path(path: &Path) -> Option<String> {
    match path.extension().and_then(|ext| ext.to_str()) {
        Some("go") => Some("Go".to_string()),
        Some("java") => Some("Java".to_string()),
        Some("js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs") => Some("Node/TypeScript".to_string()),
        Some("py") => Some("Python".to_string()),
        Some("rb") => Some("Ruby".to_string()),
        Some("php") => Some("PHP".to_string()),
        Some("cs") => Some("C#".to_string()),
        Some("rs") => Some("Rust".to_string()),
        Some("clj" | "cljs" | "cljc") => Some("Clojure".to_string()),
        Some("kt" | "kts") => Some("Kotlin".to_string()),
        Some("scala" | "sc") => Some("Scala".to_string()),
        Some("ex" | "exs") => Some("Elixir".to_string()),
        Some("c") => Some("C".to_string()),
        Some("h" | "cc" | "cpp" | "cxx" | "hpp" | "hh" | "hxx") => Some("C++".to_string()),
        _ => None,
    }
}

fn is_mvp_language(language: &str) -> bool {
    matches!(
        language,
        "Go" | "Java" | "Node/TypeScript" | "Python" | "C#" | "PHP" | "Rust"
    ) || is_tier3_language_name(language)
}

fn is_agent_supported_source(path: &Path) -> bool {
    matches!(
        path.extension().and_then(|ext| ext.to_str()),
        Some("go" | "java" | "js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs")
    )
}

fn is_low_signal_path(path: &Path) -> bool {
    let normalized = path
        .to_string_lossy()
        .replace('\\', "/")
        .to_ascii_lowercase();
    normalized.contains("/vendor/")
        || normalized.starts_with("vendor/")
        || normalized.contains("/node_modules/")
        || normalized.starts_with("node_modules/")
        || normalized.contains("/generated/")
        || normalized.starts_with("generated/")
        || normalized.contains(".generated.")
        || normalized.ends_with(".pb.go")
        || normalized.ends_with(".gen.go")
}

fn is_test_like_path(path: &Path) -> bool {
    let normalized = path
        .to_string_lossy()
        .replace('\\', "/")
        .to_ascii_lowercase();
    normalized.contains("/test/")
        || normalized.contains("/tests/")
        || normalized.ends_with("_test.go")
        || normalized.ends_with("test.java")
        || normalized.ends_with(".test.ts")
        || normalized.ends_with(".test.tsx")
        || normalized.ends_with(".test.js")
        || normalized.ends_with(".spec.ts")
        || normalized.ends_with(".spec.js")
}

fn test_appears_placeholder(path: &Path, text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    if lower.contains("todo") || lower.contains("placeholder") || lower.contains("not implemented")
    {
        return true;
    }
    match path.extension().and_then(|ext| ext.to_str()) {
        Some("go") => {
            !lower.contains("t.error")
                && !lower.contains("t.fatal")
                && !lower.contains("require.")
                && !lower.contains("assert.")
        }
        Some("java") => {
            !lower.contains("assert")
                && !lower.contains("verify(")
                && !lower.contains("fail(")
                && !lower.contains("expect")
        }
        Some("js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs") => {
            !lower.contains("expect(")
                && !lower.contains("assert")
                && !lower.contains("toequal")
                && !lower.contains("t.is(")
                && !lower.contains("throws")
        }
        _ => false,
    }
}

fn production_placeholder_line(line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    if line.starts_with("//")
        || line.starts_with('*')
        || line.starts_with("/*")
        || line.starts_with("<!--")
    {
        return lower.contains("todo")
            || lower.contains("fixme")
            || lower.contains("placeholder")
            || lower.contains("not implemented");
    }
    lower.contains("todo")
        || lower.contains("fixme")
        || lower.contains("placeholder")
        || lower.contains("not implemented")
        || lower.contains("panic(\"todo")
        || lower.contains("panic!(\"todo")
        || lower.contains("todo!()")
        || lower.contains("unimplemented!()")
        || lower.contains("throw new error(\"not implemented")
        || lower.contains("throw new unsupportedoperationexception")
}

fn swallowed_error_line(lines: &[&str], index: usize, path: &Path) -> bool {
    let trimmed = lines[index].trim();
    let lower = trimmed.to_ascii_lowercase();
    match path.extension().and_then(|ext| ext.to_str()) {
        Some("go") => {
            lower.contains(", _ :=")
                || lower.contains(", _ =")
                || lower == "_ = err"
                || lower.contains("; _ = err")
                || (lower.starts_with("if err")
                    && block_body_is_empty_or_comment_only(lines, index, 8))
        }
        Some("java") => {
            lower.contains("catch (") && block_body_is_empty_or_comment_only(lines, index, 8)
        }
        Some("js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs") => {
            (lower.starts_with("catch") || lower.contains(" catch "))
                && block_body_is_empty_or_comment_only(lines, index, 8)
                || lower.contains(".catch(() => {})")
                || lower.contains(".catch(function")
                    && block_body_is_empty_or_comment_only(lines, index, 8)
        }
        _ => false,
    }
}

fn block_body_is_empty_or_comment_only(lines: &[&str], index: usize, limit: usize) -> bool {
    let mut saw_open = false;
    let mut depth = 0usize;
    let mut body_tokens = Vec::new();
    for line in lines.iter().skip(index).take(limit) {
        for ch in line.chars() {
            match ch {
                '{' => {
                    saw_open = true;
                    depth = depth.saturating_add(1);
                }
                '}' if saw_open => {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        return body_tokens.iter().all(|token: &&str| {
                            token.is_empty()
                                || token.starts_with("//")
                                || token.starts_with("/*")
                                || token.starts_with('*')
                        });
                    }
                }
                _ => {}
            }
        }
        if saw_open && depth > 0 {
            let trimmed = line.trim();
            if !trimmed.contains('{') {
                body_tokens.push(trimmed);
            }
        }
    }
    false
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct SpaghettiControlFlowSignal {
    line: u32,
    max_control_flow_depth: usize,
    control_flow_branches: usize,
}

const SPAGHETTI_MIN_CONTROL_FLOW_DEPTH: usize = 5;
const SPAGHETTI_MIN_BRANCHES: usize = 8;
const SPAGHETTI_MIN_BODY_LINES: usize = 20;
const SPAGHETTI_MAX_FUNCTION_SCAN_LINES: usize = 240;

fn spaghetti_control_flow_signal(
    relative: &Path,
    lines: &[&str],
) -> Option<SpaghettiControlFlowSignal> {
    if !spaghetti_supported_brace_source(relative) {
        return None;
    }

    let mut best = None;
    let mut index = 0usize;
    while index < lines.len() {
        let line = source_line_for_complexity(lines[index]);
        if !line_looks_like_function_start(relative, line) {
            index += 1;
            continue;
        }

        let (signal, end_index) = scan_spaghetti_function(lines, index);
        if let Some(signal) = signal {
            let replace = best
                .as_ref()
                .is_none_or(|current: &SpaghettiControlFlowSignal| {
                    signal.max_control_flow_depth > current.max_control_flow_depth
                        || (signal.max_control_flow_depth == current.max_control_flow_depth
                            && signal.control_flow_branches > current.control_flow_branches)
                });
            if replace {
                best = Some(signal);
            }
        }
        index = end_index.saturating_add(1).max(index + 1);
    }
    best
}

fn scan_spaghetti_function(
    lines: &[&str],
    start_index: usize,
) -> (Option<SpaghettiControlFlowSignal>, usize) {
    let mut saw_open = false;
    let mut depth = 0usize;
    let mut body_lines = 0usize;
    let mut branches = 0usize;
    let mut max_control_flow_depth = 0usize;
    let mut end_index = start_index;

    for (index, raw_line) in lines
        .iter()
        .enumerate()
        .skip(start_index)
        .take(SPAGHETTI_MAX_FUNCTION_SCAN_LINES)
    {
        end_index = index;
        let line = source_line_for_complexity(raw_line);
        let trimmed = line.trim();
        if saw_open
            && !trimmed.is_empty()
            && !trimmed.starts_with("/*")
            && !trimmed.starts_with('*')
        {
            body_lines = body_lines.saturating_add(1);
            if line_has_spaghetti_control_flow(trimmed) {
                branches = branches.saturating_add(1);
                max_control_flow_depth = max_control_flow_depth.max(depth);
            }
        }

        for ch in line.chars() {
            match ch {
                '{' => {
                    saw_open = true;
                    depth = depth.saturating_add(1);
                }
                '}' if saw_open => {
                    depth = depth.saturating_sub(1);
                }
                _ => {}
            }
        }

        if saw_open && depth == 0 {
            break;
        }
    }

    let signal = (max_control_flow_depth >= SPAGHETTI_MIN_CONTROL_FLOW_DEPTH
        && branches >= SPAGHETTI_MIN_BRANCHES
        && body_lines >= SPAGHETTI_MIN_BODY_LINES)
        .then(|| SpaghettiControlFlowSignal {
            line: u32::try_from(start_index + 1).unwrap_or(u32::MAX),
            max_control_flow_depth,
            control_flow_branches: branches,
        });
    (signal, end_index)
}

fn spaghetti_supported_brace_source(path: &Path) -> bool {
    matches!(
        path.extension().and_then(|ext| ext.to_str()),
        Some("go" | "java" | "js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs")
    )
}

fn line_looks_like_function_start(relative: &Path, line: &str) -> bool {
    let trimmed = line.trim();
    if trimmed.is_empty()
        || trimmed.starts_with("//")
        || !trimmed.contains('{')
        || line_has_spaghetti_control_flow(trimmed)
    {
        return false;
    }
    match relative.extension().and_then(|ext| ext.to_str()) {
        Some("go") => trimmed.starts_with("func "),
        Some("js" | "jsx" | "ts" | "tsx" | "mjs" | "cjs") => {
            trimmed.starts_with("function ")
                || trimmed.starts_with("async function ")
                || trimmed.starts_with("export function ")
                || trimmed.starts_with("export async function ")
                || trimmed.contains(" function ")
                || trimmed.contains("=> {")
                || trimmed.contains("=>{")
        }
        Some("java") => {
            trimmed.contains('(')
                && trimmed.contains(')')
                && !trimmed.starts_with("class ")
                && !trimmed.starts_with("interface ")
                && !trimmed.starts_with("enum ")
                && [
                    "public ",
                    "private ",
                    "protected ",
                    "static ",
                    "void ",
                    "String ",
                    "int ",
                    "long ",
                    "boolean ",
                ]
                .iter()
                .any(|needle| trimmed.contains(needle))
        }
        _ => false,
    }
}

fn line_has_spaghetti_control_flow(line: &str) -> bool {
    let mut candidate = line.trim();
    while let Some(rest) = candidate.strip_prefix('}') {
        candidate = rest.trim_start();
    }
    let lower = candidate.to_ascii_lowercase();
    let lower = lower.as_str();
    lower.starts_with("if ")
        || lower.starts_with("if(")
        || lower.starts_with("else if ")
        || lower.starts_with("else if(")
        || lower.starts_with("for ")
        || lower.starts_with("for(")
        || lower.starts_with("while ")
        || lower.starts_with("while(")
        || lower.starts_with("switch ")
        || lower.starts_with("switch(")
        || lower.starts_with("case ")
        || lower.starts_with("catch ")
        || lower.starts_with("catch(")
        || lower.starts_with("try ")
        || lower == "try {"
}

fn source_line_for_complexity(line: &str) -> &str {
    line.split_once("//").map_or(line, |(before, _)| before)
}

fn agent_pattern_metadata(pattern: &str) -> BTreeMap<String, String> {
    let mut metadata = BTreeMap::new();
    metadata.insert("pattern".to_string(), pattern.to_string());
    metadata.insert("authorshipClaim".to_string(), "none".to_string());
    metadata
}

fn is_suppressed(finding: &Finding, suppressions: &[Suppression]) -> bool {
    suppressions.iter().any(|suppression| {
        if suppression.rule != finding.rule_id {
            return false;
        }
        let Some(path_pattern) = &suppression.path else {
            return suppression.allow_broad;
        };
        let normalized_pattern = path_pattern.replace('\\', "/");
        if normalized_pattern.trim().is_empty() {
            return suppression.allow_broad;
        }
        finding.location.as_ref().is_some_and(|location| {
            location
                .path
                .to_string_lossy()
                .replace('\\', "/")
                .contains(&normalized_pattern)
        })
    })
}

fn dedupe_findings(findings: Vec<Finding>) -> Vec<Finding> {
    let mut seen = BTreeSet::new();
    let mut deduped = Vec::new();
    for finding in backend_doctor_core::sort_findings(findings) {
        let key = (
            finding.rule_id.clone(),
            finding.source_tool.clone(),
            finding
                .location
                .as_ref()
                .map(|location| location.path.clone()),
            finding.location.as_ref().and_then(|location| location.line),
            finding
                .location
                .as_ref()
                .and_then(|location| location.column),
            finding.message.clone(),
        );
        if seen.insert(key) {
            deduped.push(finding);
        }
    }
    deduped
}

fn fingerprint(rule_id: &str, path: &Path, line: u32, snippet: &str) -> String {
    let input = format!("{}:{}:{}:{}", rule_id, path.display(), line, snippet);
    let mut hash = 0xcbf29ce484222325u64;
    for byte in input.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("fnv64:{hash:016x}")
}

