    fn copy_fixture_to_temp(name: &str) -> PathBuf {
        let root = temp_root(name);
        copy_dir_all(&fixture_path(name), &root);
        root
    }

    fn copy_dir_all(source: &Path, target: &Path) {
        fs::create_dir_all(target).expect("create fixture copy directory");
        for entry in fs::read_dir(source).expect("read fixture directory") {
            let entry = entry.expect("read fixture entry");
            if entry.file_name().to_str() == Some(".backend-doctor") {
                continue;
            }
            let source_path = entry.path();
            let target_path = target.join(entry.file_name());
            if entry.file_type().expect("fixture entry type").is_dir() {
                copy_dir_all(&source_path, &target_path);
            } else {
                fs::copy(&source_path, &target_path).expect("copy fixture file");
            }
        }
    }

    fn assert_fixture_has_rule(findings: &[Finding], id: &str) {
        assert!(
            findings.iter().any(|finding| finding.rule_id == id),
            "missing {id}; findings: {:?}",
            findings
                .iter()
                .map(|finding| &finding.rule_id)
                .collect::<Vec<_>>()
        );
    }

    fn suppression_fixture_finding(rule_id: &str, path: &str) -> Finding {
        Finding {
            id: format!("{rule_id}:{path}"),
            fingerprint: format!("test:{rule_id}:{path}"),
            rule_id: rule_id.to_string(),
            tool: "backend-doctor-rules".to_string(),
            source_tool: "backend-doctor-rules".to_string(),
            title: "Suppression fixture finding".to_string(),
            message: "Synthetic finding for suppression matching tests.".to_string(),
            category: Category::Maintainability,
            severity: Severity::Warning,
            confidence: Confidence::High,
            service: None,
            language: Some("Node/TypeScript".to_string()),
            framework: None,
            location: Some(Location {
                path: PathBuf::from(path),
                line: Some(1),
                column: Some(1),
                end_line: None,
                end_column: None,
            }),
            evidence: None,
            impact: None,
            remediation: "Fix the synthetic issue.".to_string(),
            fix: FixInfo {
                available: false,
                safety: FixSafety::None,
                description: None,
            },
            links: Vec::new(),
            metadata: BTreeMap::new(),
            suppressed: false,
        }
    }

    fn suppression_fixture(rule: &str, path: Option<&str>, allow_broad: bool) -> Suppression {
        Suppression {
            rule: rule.to_string(),
            path: path.map(str::to_string),
            allow_broad,
            reason: "suppression matching fixture".to_string(),
            expires: None,
        }
    }

    #[test]
    fn pathless_suppression_without_allow_broad_does_not_match_all_same_rule_findings() {
        let finding = suppression_fixture_finding("agent/production-placeholder", "src/app.ts");
        let suppressions = [suppression_fixture(
            "agent/production-placeholder",
            None,
            false,
        )];

        assert!(
            !is_suppressed(&finding, &suppressions),
            "pathless rule-only suppressions must not broadly suppress without allowBroad"
        );
    }

    #[test]
    fn pathless_suppression_with_allow_broad_matches_same_rule_findings() {
        let finding = suppression_fixture_finding("agent/production-placeholder", "src/app.ts");
        let suppressions = [suppression_fixture(
            "agent/production-placeholder",
            None,
            true,
        )];

        assert!(
            is_suppressed(&finding, &suppressions),
            "allowBroad makes a pathless same-rule suppression intentional"
        );
    }

    #[test]
    fn path_scoped_suppression_behavior_is_preserved() {
        let matching = suppression_fixture_finding(
            "agent/production-placeholder",
            "src/suppressed/issue-001.ts",
        );
        let visible =
            suppression_fixture_finding("agent/production-placeholder", "src/visible/issue-001.ts");
        let suppressions = [suppression_fixture(
            "agent/production-placeholder",
            Some("src/suppressed/"),
            false,
        )];

        assert!(
            is_suppressed(&matching, &suppressions),
            "path-scoped suppression should still match the configured path fragment"
        );
        assert!(
            !is_suppressed(&visible, &suppressions),
            "path-scoped suppression must not match unrelated paths"
        );
    }

    #[test]
    fn broad_suppression_does_not_match_different_rules() {
        let finding = suppression_fixture_finding("security/hardcoded-secret", "src/app.ts");
        let suppressions = [suppression_fixture(
            "agent/production-placeholder",
            None,
            true,
        )];

        assert!(
            !is_suppressed(&finding, &suppressions),
            "allowBroad is still limited to the configured rule"
        );
    }

    fn assert_fixture_lacks_rules(fixture: &str, findings: &[Finding], ids: &[&str]) {
        let triggered = findings
            .iter()
            .filter(|finding| ids.contains(&finding.rule_id.as_str()))
            .map(|finding| (&finding.rule_id, &finding.location))
            .collect::<Vec<_>>();
        assert!(
            triggered.is_empty(),
            "{fixture} unexpectedly triggered clean-fixture rules: {triggered:?}; all findings: {:?}",
            findings
                .iter()
                .map(|finding| (&finding.rule_id, &finding.location))
                .collect::<Vec<_>>()
        );
    }

    fn assert_fixture_scanned(
        fixture: &str,
        graph: &ProjectGraph,
        language: &str,
        expected_sources: &[&str],
    ) {
        assert!(
            graph
                .languages
                .iter()
                .any(|detected| detected.name == language),
            "{fixture} should detect {language}; languages={:?}; inventory={:?}",
            graph.languages,
            graph.inventory
        );
        for expected_source in expected_sources {
            assert!(
                graph
                    .inventory
                    .files
                    .iter()
                    .any(|path| path.as_path() == Path::new(expected_source)),
                "{fixture} should inventory source {expected_source}; inventory={:?}",
                graph.inventory
            );
        }
        assert!(
            graph.inventory.source_files >= expected_sources.len(),
            "{fixture} should scan at least {} source files; inventory={:?}",
            expected_sources.len(),
            graph.inventory
        );
    }

