    #[test]
    fn low_signal_generated_vendor_dependency_paths_do_not_report_agent_findings() {
        let root = temp_root("low-signal-generated-noise");
        let files = [
            PathBuf::from("generated/client.ts"),
            PathBuf::from("src/schema.generated.ts"),
            PathBuf::from("src/types.pb.go"),
            PathBuf::from("src/types.gen.go"),
            PathBuf::from("vendor/package/client.ts"),
            PathBuf::from("node_modules/package/index.ts"),
            PathBuf::from("src/handler.ts"),
        ];

        for relative in &files {
            fs::create_dir_all(root.join(relative.parent().expect("fixture parent")))
                .expect("create fixture directory");
            fs::write(
                root.join(relative),
                "// TODO replace generated placeholder implementation\nexport const value = 1;\n",
            )
            .expect("write fixture source");
        }

        let mut graph = ProjectGraph::empty(root.clone());
        graph.inventory.total_files = files.len();
        graph.inventory.source_files = files.len();
        graph.inventory.files = files.to_vec();

        let findings = scan_project(&graph, &Config::default());
        let normal_source = Path::new("src/handler.ts");
        assert!(
            findings.iter().any(|finding| {
                finding.rule_id == "agent/production-placeholder"
                    && finding
                        .location
                        .as_ref()
                        .is_some_and(|location| location.path == normal_source)
            }),
            "normal source placeholder should still report; findings: {:?}",
            findings
        );

        let low_signal_paths = [
            Path::new("generated/client.ts"),
            Path::new("src/schema.generated.ts"),
            Path::new("src/types.pb.go"),
            Path::new("src/types.gen.go"),
            Path::new("vendor/package/client.ts"),
            Path::new("node_modules/package/index.ts"),
        ];
        for path in low_signal_paths {
            assert!(
                is_low_signal_path(path),
                "expected low-signal path: {path:?}"
            );
            assert!(
                !findings.iter().any(|finding| finding
                    .location
                    .as_ref()
                    .is_some_and(|location| location.path == path)),
                "low-signal path should not produce findings for {path:?}; findings: {:?}",
                findings
            );
        }

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn low_signal_generated_vendor_dependency_paths_do_not_report_semantic_duplicate_findings() {
        let root = temp_root("low-signal-semantic-duplicate-noise");
        let files = [
            (
                PathBuf::from("src/create.ts"),
                "export interface CreateUserRequest {\n  id: string;\n  email: string;\n  role: string;\n}\n",
            ),
            (
                PathBuf::from("src/update.ts"),
                "export interface UpdateUserRequest {\n  id: string;\n  email: string;\n  role: string;\n}\n",
            ),
            (
                PathBuf::from("generated/client.ts"),
                "export interface GeneratedUserRequest {\n  id: string;\n  email: string;\n  role: string;\n}\n",
            ),
            (
                PathBuf::from("src/schema.generated.ts"),
                "export interface SchemaUserRequest {\n  id: string;\n  email: string;\n  role: string;\n}\n",
            ),
            (
                PathBuf::from("vendor/package/types.ts"),
                "export interface VendorUserRequest {\n  id: string;\n  email: string;\n  role: string;\n}\n",
            ),
            (
                PathBuf::from("node_modules/package/types.ts"),
                "export interface DependencyUserRequest {\n  id: string;\n  email: string;\n  role: string;\n}\n",
            ),
        ];

        for (relative, text) in &files {
            fs::create_dir_all(root.join(relative.parent().expect("fixture parent")))
                .expect("create fixture directory");
            fs::write(root.join(relative), text).expect("write fixture source");
        }

        let mut graph = ProjectGraph::empty(root.clone());
        graph.inventory.total_files = files.len();
        graph.inventory.source_files = files.len();
        graph.inventory.files = files
            .iter()
            .map(|(relative, _)| relative.clone())
            .collect::<Vec<_>>();

        let findings = scan_project(&graph, &Config::default());
        let update_path = Path::new("src/update.ts");
        assert!(
            findings.iter().any(|finding| {
                finding.rule_id == "node/duplicate-dto-shape"
                    && finding
                        .location
                        .as_ref()
                        .is_some_and(|location| location.path == update_path)
            }),
            "normal source duplicate DTO should report at {update_path:?}; findings: {findings:?}"
        );
        assert!(
            findings.iter().any(|finding| {
                finding.rule_id == "agent/semantic-copy-paste"
                    && finding
                        .location
                        .as_ref()
                        .is_some_and(|location| location.path == update_path)
                    && finding.metadata.get("matchedRule").map(String::as_str)
                        == Some("node/duplicate-dto-shape")
            }),
            "normal source semantic copy-paste should report at {update_path:?}; findings: {findings:?}"
        );

        let low_signal_paths = [
            Path::new("generated/client.ts"),
            Path::new("src/schema.generated.ts"),
            Path::new("vendor/package/types.ts"),
            Path::new("node_modules/package/types.ts"),
        ];
        for path in low_signal_paths {
            assert!(
                is_low_signal_path(path),
                "expected low-signal path: {path:?}"
            );
            assert!(
                !findings.iter().any(|finding| {
                    matches!(
                        finding.rule_id.as_str(),
                        "node/duplicate-dto-shape" | "agent/semantic-copy-paste"
                    ) && finding
                        .location
                        .as_ref()
                        .is_some_and(|location| location.path == path)
                }),
                "low-signal path should not produce semantic duplicate findings for {path:?}; findings: {findings:?}"
            );
        }

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn low_signal_generated_go_java_paths_do_not_report_semantic_duplicate_findings() {
        let root = temp_root("low-signal-go-java-semantic-duplicate-noise");
        let files = [
            (
                PathBuf::from("src/create.go"),
                "package main\n\ntype CreateUserRequest struct {\n\tID string\n\tEmail string\n\tRole string\n}\n",
            ),
            (
                PathBuf::from("src/update.go"),
                "package main\n\ntype UpdateUserRequest struct {\n\tID string\n\tEmail string\n\tRole string\n}\n",
            ),
            (
                PathBuf::from("generated/client.go"),
                "package generated\n\ntype GeneratedUserRequest struct {\n\tID string\n\tEmail string\n\tRole string\n}\n",
            ),
            (
                PathBuf::from("src/types.pb.go"),
                "package main\n\ntype ProtoUserRequest struct {\n\tID string\n\tEmail string\n\tRole string\n}\n",
            ),
            (
                PathBuf::from("src/types.gen.go"),
                "package main\n\ntype GenUserRequest struct {\n\tID string\n\tEmail string\n\tRole string\n}\n",
            ),
            (
                PathBuf::from("vendor/package/types.go"),
                "package package\n\ntype VendorUserRequest struct {\n\tID string\n\tEmail string\n\tRole string\n}\n",
            ),
            (
                PathBuf::from("src/CreateUserRequest.java"),
                "public class CreateUserRequest {\n    private String id;\n    private String email;\n    private String role;\n}\n",
            ),
            (
                PathBuf::from("src/UpdateUserRequest.java"),
                "public class UpdateUserRequest {\n    private String id;\n    private String email;\n    private String role;\n}\n",
            ),
            (
                PathBuf::from("generated/GeneratedUserRequest.java"),
                "public class GeneratedUserRequest {\n    private String id;\n    private String email;\n    private String role;\n}\n",
            ),
            (
                PathBuf::from("src/SchemaUserRequest.generated.java"),
                "public class SchemaUserRequest {\n    private String id;\n    private String email;\n    private String role;\n}\n",
            ),
            (
                PathBuf::from("vendor/package/VendorUserRequest.java"),
                "public class VendorUserRequest {\n    private String id;\n    private String email;\n    private String role;\n}\n",
            ),
        ];

        for (relative, text) in &files {
            fs::create_dir_all(root.join(relative.parent().expect("fixture parent")))
                .expect("create fixture directory");
            fs::write(root.join(relative), text).expect("write fixture source");
        }

        let mut graph = ProjectGraph::empty(root.clone());
        graph.inventory.total_files = files.len();
        graph.inventory.source_files = files.len();
        graph.inventory.files = files
            .iter()
            .map(|(relative, _)| relative.clone())
            .collect::<Vec<_>>();

        let findings = scan_project(&graph, &Config::default());
        for (path, rule_id) in [
            (Path::new("src/update.go"), "go/duplicate-dto-shape"),
            (
                Path::new("src/UpdateUserRequest.java"),
                "java/duplicate-dto-shape",
            ),
        ] {
            assert!(
                findings.iter().any(|finding| {
                    finding.rule_id == rule_id
                        && finding
                            .location
                            .as_ref()
                            .is_some_and(|location| location.path == path)
                }),
                "normal source duplicate DTO should report {rule_id} at {path:?}; findings: {findings:?}"
            );
            assert!(
                findings.iter().any(|finding| {
                    finding.rule_id == "agent/semantic-copy-paste"
                        && finding
                            .location
                            .as_ref()
                            .is_some_and(|location| location.path == path)
                        && finding.metadata.get("matchedRule").map(String::as_str)
                            == Some(rule_id)
                }),
                "normal source semantic copy-paste should report matchedRule={rule_id} at {path:?}; findings: {findings:?}"
            );
        }

        let low_signal_paths = [
            Path::new("generated/client.go"),
            Path::new("src/types.pb.go"),
            Path::new("src/types.gen.go"),
            Path::new("vendor/package/types.go"),
            Path::new("generated/GeneratedUserRequest.java"),
            Path::new("src/SchemaUserRequest.generated.java"),
            Path::new("vendor/package/VendorUserRequest.java"),
        ];
        for path in low_signal_paths {
            assert!(
                is_low_signal_path(path),
                "expected low-signal path: {path:?}"
            );
            assert!(
                !findings.iter().any(|finding| {
                    matches!(
                        finding.rule_id.as_str(),
                        "go/duplicate-dto-shape"
                            | "java/duplicate-dto-shape"
                            | "agent/semantic-copy-paste"
                    ) && finding
                        .location
                        .as_ref()
                        .is_some_and(|location| location.path == path)
                }),
                "low-signal path should not produce Go/Java semantic duplicate findings for {path:?}; findings: {findings:?}"
            );
        }

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn synthetic_large_monorepo_scan_stays_bounded_and_suppresses_generated_noise() {
        let root = temp_root("synthetic-large-monorepo");
        for service_index in 0..12 {
            let service_name = format!("service-{service_index:02}");
            let service_root = root.join("apps").join(&service_name);
            fs::create_dir_all(service_root.join("src")).expect("create service source");
            fs::create_dir_all(service_root.join("generated")).expect("create generated source");
            fs::create_dir_all(service_root.join("node_modules").join("package"))
                .expect("create dependency source");
            fs::create_dir_all(service_root.join("vendor").join("package"))
                .expect("create vendor source");

            fs::write(
                service_root.join("package.json"),
                format!(
                    r#"{{"name":"@synthetic/{service_name}","version":"0.0.0","type":"module"}}"#
                ),
            )
            .expect("write package manifest");

            for module_index in 0..20 {
                let body = if module_index == 0 {
                    "// TODO replace placeholder implementation\nexport const value = 0;\n"
                        .to_string()
                } else {
                    format!("export const value{module_index} = {module_index};\n")
                };
                fs::write(
                    service_root
                        .join("src")
                        .join(format!("module-{module_index:02}.ts")),
                    body,
                )
                .expect("write service source");
            }

            for generated_index in 0..5 {
                fs::write(
                    service_root
                        .join("generated")
                        .join(format!("client-{generated_index:02}.ts")),
                    "// TODO generated placeholder client\nexport const generated = true;\n",
                )
                .expect("write generated source");
                fs::write(
                    service_root
                        .join("src")
                        .join(format!("schema-{generated_index:02}.generated.ts")),
                    "// TODO generated placeholder schema\nexport const schema = true;\n",
                )
                .expect("write generated schema source");
            }

            fs::write(
                service_root
                    .join("node_modules")
                    .join("package")
                    .join("index.ts"),
                "// TODO dependency placeholder\nexport const dependency = true;\n",
            )
            .expect("write dependency source");
            fs::write(
                service_root
                    .join("vendor")
                    .join("package")
                    .join("client.ts"),
                "// TODO vendor placeholder\nexport const vendor = true;\n",
            )
            .expect("write vendor source");
        }

        let started = std::time::Instant::now();
        let graph = detect_project(root.clone());
        let findings = scan_project(&graph, &Config::default());
        let elapsed = started.elapsed();

        assert!(
            elapsed <= Duration::from_secs(15),
            "synthetic scan should stay bounded; elapsed={elapsed:?}, files={}",
            graph.inventory.total_files
        );
        assert!(graph.monorepo, "synthetic apps tree should be a monorepo");
        assert_eq!(
            graph.services.len(),
            12,
            "expected one service per synthetic app: {:?}",
            graph
                .services
                .iter()
                .map(|service| &service.id)
                .collect::<Vec<_>>()
        );
        assert!(
            graph
                .languages
                .iter()
                .any(|language| language.name == "Node/TypeScript"),
            "Node/TypeScript should be detected: {:?}",
            graph.languages
        );
        assert!(
            graph.services.iter().all(|service| service
                .languages
                .iter()
                .any(|language| language == "Node/TypeScript")),
            "each service should detect Node/TypeScript: {:?}",
            graph.services
        );
        assert!(
            graph.inventory.total_files <= 400,
            "synthetic fixture should stay bounded; inventory={:?}",
            graph.inventory
        );
        assert!(
            graph.inventory.source_files >= 300,
            "expected substantial source inventory; inventory={:?}",
            graph.inventory
        );
        assert!(
            graph.inventory.files.iter().all(|path| {
                let normalized = path.to_string_lossy().replace('\\', "/");
                !normalized.contains("/node_modules/") && !normalized.contains("/vendor/")
            }),
            "dependency/vendor paths should be excluded from inventory: {:?}",
            graph.inventory.files
        );

        let normal_source = Path::new("apps/service-00/src/module-00.ts");
        assert!(
            findings.iter().any(|finding| {
                finding.rule_id == "agent/production-placeholder"
                    && finding
                        .location
                        .as_ref()
                        .is_some_and(|location| location.path == normal_source)
            }),
            "normal source placeholder should still report; findings: {:?}",
            findings
        );

        let noisy_paths = [
            Path::new("apps/service-00/generated/client-00.ts"),
            Path::new("apps/service-00/src/schema-00.generated.ts"),
            Path::new("apps/service-00/node_modules/package/index.ts"),
            Path::new("apps/service-00/vendor/package/client.ts"),
        ];
        assert!(
            graph
                .inventory
                .files
                .contains(&noisy_paths[0].to_path_buf()),
            "generated directory file should remain in inventory for suppression coverage"
        );
        assert!(
            graph
                .inventory
                .files
                .contains(&noisy_paths[1].to_path_buf()),
            "dot-generated source file should remain in inventory for suppression coverage"
        );
        for path in noisy_paths {
            assert!(
                !findings.iter().any(|finding| finding
                    .location
                    .as_ref()
                    .is_some_and(|location| location.path == path)),
                "noisy path should not produce findings for {path:?}; findings: {:?}",
                findings
            );
        }

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn many_suppressed_findings_performance_metrics_baseline() {
        const SUPPRESSED_FIXTURES: usize = 96;
        const VISIBLE_FIXTURES: usize = 32;
        const TOTAL_FIXTURES: usize = SUPPRESSED_FIXTURES + VISIBLE_FIXTURES;

        let root = temp_root("many-suppressed-findings-baseline");
        let mut files = Vec::with_capacity(TOTAL_FIXTURES);
        let mut suppressions = Vec::with_capacity(SUPPRESSED_FIXTURES);

        for index in 0..SUPPRESSED_FIXTURES {
            let relative = PathBuf::from(format!("src/suppressed/issue-{index:03}.js"));
            fs::create_dir_all(root.join(relative.parent().expect("fixture parent")))
                .expect("create suppressed fixture directory");
            fs::write(
                root.join(&relative),
                format!("// TODO replace temporary suppressed implementation {index}\nconst value = {index};\n"),
            )
            .expect("write suppressed fixture");
            suppressions.push(Suppression {
                rule: "agent/production-placeholder".to_string(),
                path: Some(relative.to_string_lossy().replace('\\', "/")),
                allow_broad: false,
                reason: "synthetic baseline path-scoped suppression".to_string(),
                expires: None,
            });
            files.push(relative);
        }

        for index in 0..VISIBLE_FIXTURES {
            let relative = PathBuf::from(format!("src/visible/issue-{index:03}.js"));
            fs::create_dir_all(root.join(relative.parent().expect("fixture parent")))
                .expect("create visible fixture directory");
            fs::write(
                root.join(&relative),
                format!("// TODO replace temporary visible implementation {index}\nconst value = {index};\n"),
            )
            .expect("write visible fixture");
            files.push(relative);
        }

        let mut graph = ProjectGraph::empty(root.clone());
        graph.inventory.total_files = files.len();
        graph.inventory.source_files = files.len();
        graph.inventory.files = files;

        let config = Config {
            suppressions,
            ..Config::default()
        };

        let started = std::time::Instant::now();
        let output = scan_project_with_external(&graph, &config);
        let elapsed = started.elapsed();

        assert!(
            elapsed <= Duration::from_secs(10),
            "many suppressed findings scan should stay bounded; elapsed={elapsed:?}, files={TOTAL_FIXTURES}, suppressions={SUPPRESSED_FIXTURES}"
        );

        let placeholder_findings = output
            .findings
            .iter()
            .filter(|finding| finding.rule_id == "agent/production-placeholder")
            .collect::<Vec<_>>();
        assert_eq!(
            placeholder_findings.len(),
            TOTAL_FIXTURES,
            "fixture should produce exactly one placeholder finding per source file; findings={:?}",
            output.findings
        );

        let suppressed_count = placeholder_findings
            .iter()
            .filter(|finding| finding.suppressed)
            .count();
        let visible_count = placeholder_findings
            .iter()
            .filter(|finding| !finding.suppressed)
            .count();
        assert_eq!(
            suppressed_count, SUPPRESSED_FIXTURES,
            "path-scoped suppressions should suppress only matching synthetic files"
        );
        assert_eq!(
            visible_count, VISIBLE_FIXTURES,
            "unsuppressed synthetic files must remain visible"
        );

        for index in 0..VISIBLE_FIXTURES {
            let visible_path = PathBuf::from(format!("src/visible/issue-{index:03}.js"));
            assert!(
                placeholder_findings.iter().any(|finding| {
                    !finding.suppressed
                        && finding
                            .location
                            .as_ref()
                            .is_some_and(|location| location.path == visible_path)
                }),
                "visible placeholder should remain active for {visible_path:?}; findings={placeholder_findings:?}"
            );
        }

        let (active_findings, suppressed_findings): (Vec<_>, Vec<_>) = output
            .findings
            .iter()
            .cloned()
            .partition(|finding| !finding.suppressed);
        let summary =
            backend_doctor_core::Summary::from_findings(&active_findings, &suppressed_findings);
        assert_eq!(
            summary.suppressed_findings, SUPPRESSED_FIXTURES,
            "report summary suppression metric should count suppressed findings accurately"
        );
        assert_eq!(
            summary.total_findings, VISIBLE_FIXTURES,
            "report summary active total should exclude suppressed findings"
        );

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn backend_doctor_cache_artifact_ports_do_not_trigger_port_mismatch() {
        let root = temp_root("cache-artifact-ports");
        fs::create_dir_all(root.join("src")).expect("create src");
        fs::create_dir_all(root.join(".backend-doctor").join("cache")).expect("create cache");
        fs::create_dir_all(root.join("vendor").join(".backend-doctor")).expect("create nested");
        fs::write(root.join("src").join("server.js"), "app.listen(3000);\n").expect("write app");
        fs::write(root.join("Dockerfile"), "FROM node:20\nEXPOSE 3000\n")
            .expect("write Dockerfile");
        fs::write(
            root.join("vendor")
                .join(".backend-doctor")
                .join("service.js"),
            "app.listen(3000);\n",
        )
        .expect("write nested backend-doctor file");
        fs::write(
            root.join(".backend-doctor")
                .join("cache")
                .join("external.json"),
            r#"{"redactedStdout":"database listens on 5432"}"#,
        )
        .expect("write cache artifact");

        let mut graph = ProjectGraph::empty(root.clone());
        graph.inventory.total_files = 3;
        graph.inventory.source_files = 1;
        graph.inventory.infra_files = 1;
        graph.inventory.files = vec![
            PathBuf::from("src/server.js"),
            PathBuf::from("Dockerfile"),
            PathBuf::from("vendor/.backend-doctor/service.js"),
            PathBuf::from(".backend-doctor/cache/external.json"),
        ];
        graph.infra.dockerfiles = vec![PathBuf::from("Dockerfile")];

        assert_eq!(collect_ports(&graph), BTreeSet::from(["3000".to_string()]));
        assert!(!is_backend_doctor_generated_artifact(Path::new(
            "vendor/.backend-doctor/service.js"
        )));
        assert!(is_backend_doctor_generated_artifact(Path::new(
            ".backend-doctor/cache/external.json"
        )));
        let findings = scan_project(&graph, &Config::default());
        assert!(
            !findings
                .iter()
                .any(|finding| finding.rule_id == "infra/port-mismatch"),
            "cache artifact port should not create infra/port-mismatch: {:?}",
            findings
                .iter()
                .map(|finding| &finding.rule_id)
                .collect::<Vec<_>>()
        );

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn security_bad_fixture_deep_cache_miss_hit_findings_and_scores_are_deterministic() {
        let root = copy_fixture_to_temp("security-bad-service");
        let mut config = Config::default();
        config.external_tools.deep = true;

        let first_graph = detect_project(root.clone());
        let first = scan_project_with_external(&first_graph, &config);
        assert!(
            first.external_tool_executions.iter().any(|execution| {
                execution
                    .cache
                    .as_ref()
                    .is_some_and(|cache| cache.status == "miss")
            }),
            "deep scan should populate repo-local cache on first run"
        );

        let second_graph = detect_project(root.clone());
        let second = scan_project_with_external(&second_graph, &config);
        assert!(
            second.external_tool_executions.iter().any(|execution| {
                execution
                    .cache
                    .as_ref()
                    .is_some_and(|cache| cache.status == "hit")
            }),
            "second deep scan should reuse repo-local cache"
        );

        assert_eq!(first.findings, second.findings);
        assert_eq!(
            backend_doctor_core::score_findings(&first.findings),
            backend_doctor_core::score_findings(&second.findings)
        );

        let _ = fs::remove_dir_all(root);
    }

