    #[test]
    fn go_http_timeout_unusable_facts_do_not_create_or_suppress_fallback() {
        let no_fallback_root = temp_root("go-http-timeout-unusable-no-create");
        let no_fallback_source = "package main\n\
\n\
func load() {\n\
\t_ = \"ok\"\n\
}\n";
        let no_fallback_graph = go_source_graph(&no_fallback_root, no_fallback_source);
        let fallback_root = temp_root("go-http-timeout-unusable-fallback");
        let fallback_source = "package main\n\
\n\
func load() {\n\
\t_, _ = http.Get(\"https://example.test\")\n\
}\n";
        let fallback_graph = go_source_graph(&fallback_root, fallback_source);
        let base_facts = go_route_test_facts();
        let file_id = base_facts.source_files[0].id.clone();

        let empty_facts = AnalysisFacts::empty();

        let mut wrong_language_facts = go_http_timeout_facts("http.Get", 4, 4);
        wrong_language_facts.source_files[0].language = "Java".to_string();

        let mut wrong_file_facts = AnalysisFacts::empty();
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/main.go", "Go"));
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/other.go", "Go"));
        let wrong_file_id = wrong_file_facts.source_files[1].id.clone();
        wrong_file_facts.sinks.push(go_http_network_sink(
            "http-get-other-file",
            &wrong_file_id,
            "http.Get",
            4,
            4,
        ));

        let mut wrong_source_adapter_facts = go_http_timeout_facts("http.Get", 4, 4);
        wrong_source_adapter_facts.source_files[0]
            .metadata
            .insert("adapter".to_string(), "node-typescript".to_string());

        let mut wrong_sink_adapter_facts = go_http_timeout_facts("http.Get", 4, 4);
        wrong_sink_adapter_facts.sinks[0]
            .metadata
            .insert("adapter".to_string(), "node-typescript".to_string());

        let mut wrong_kind_facts = base_facts.clone();
        let mut wrong_kind_sink = sink_fact_with_scope(
            "http-get-sql",
            &file_id,
            None,
            SinkKind::SqlQuery,
            Some("http.Get"),
            4,
            4,
        );
        wrong_kind_sink
            .metadata
            .insert("adapter".to_string(), "go".to_string());
        wrong_kind_facts.sinks.push(wrong_kind_sink);

        let mut missing_file_facts = go_http_timeout_facts("http.Get", 4, 4);
        missing_file_facts.sinks[0].file_id = None;

        let mut missing_range_facts = go_http_timeout_facts("http.Get", 4, 4);
        missing_range_facts.sinks[0].range = None;

        let non_target_network_facts = go_http_timeout_facts("http.Head", 4, 4);

        for (case, facts) in [
            ("empty", empty_facts),
            ("wrong-language", wrong_language_facts),
            ("wrong-file", wrong_file_facts),
            ("wrong-source-adapter", wrong_source_adapter_facts),
            ("wrong-sink-adapter", wrong_sink_adapter_facts),
            ("wrong-kind", wrong_kind_facts),
            ("missing-file", missing_file_facts),
            ("missing-range", missing_range_facts),
            ("non-target-network", non_target_network_facts),
        ] {
            let no_fallback_findings =
                scan_go_file_with_facts_raw(&no_fallback_graph, no_fallback_source, &facts);
            assert!(
                go_http_timeout_findings(&no_fallback_findings).is_empty(),
                "{case} facts should not create Go http timeout findings; findings: {no_fallback_findings:?}"
            );

            let fallback_findings =
                scan_go_file_with_facts_raw(&fallback_graph, fallback_source, &facts);
            assert_eq!(
                go_http_timeout_findings(&fallback_findings).len(),
                1,
                "{case} facts should not suppress Go http timeout text fallback; findings: {fallback_findings:?}"
            );
        }

        let _ = fs::remove_dir_all(no_fallback_root);
        let _ = fs::remove_dir_all(fallback_root);
    }

