    #[test]
    fn go_sql_unusable_facts_do_not_create_or_suppress_fallback() {
        let no_fallback_root = temp_root("go-sql-unusable-no-create");
        let no_fallback_source = "package main\n\
\n\
func show(r *http.Request, db DB) {\n\
\tid := r.URL.Query().Get(\"id\")\n\
\tdb.Query(\"SELECT * FROM users WHERE id = ?\", id)\n\
}\n";
        let no_fallback_graph = go_source_graph(&no_fallback_root, no_fallback_source);
        let fallback_root = temp_root("go-sql-unusable-fallback");
        let fallback_source = "package main\n\
\n\
func show(r *http.Request, db DB) {\n\
\tdb.Query(\"SELECT * FROM users WHERE id = \" + r.URL.Query().Get(\"id\"))\n\
}\n";
        let fallback_graph = go_source_graph(&fallback_root, fallback_source);

        let empty_facts = AnalysisFacts::empty();

        let mut wrong_file_facts = AnalysisFacts::empty();
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/main.go", "Go"));
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/other.go", "Go"));
        let wrong_file_id = wrong_file_facts.source_files[1].id.clone();
        wrong_file_facts
            .data_sources
            .push(request_source_fact_with_scope(
                "request-query",
                &wrong_file_id,
                Some("show"),
                Some("r.URL.Query"),
                4,
                4,
            ));
        wrong_file_facts.sinks.push(sink_fact_with_scope(
            "sql-query",
            &wrong_file_id,
            Some("show"),
            SinkKind::SqlQuery,
            Some("db.Query"),
            4,
            4,
        ));
        wrong_file_facts.taint_edges.push(taint_edge(
            "request-to-sql",
            "request-query",
            "sql-query",
            TaintEdgeKind::SourceToSink,
            None,
        ));
        mark_facts_as_adapter_shaped(&mut wrong_file_facts, "go");
        mark_go_edges_as_real_local_shape(&mut wrong_file_facts);

        let mut wrong_language_facts = go_sql_flow_facts(4, 4, SinkKind::SqlQuery);
        wrong_language_facts.source_files[0].language = "Java".to_string();

        let mut wrong_adapter_facts = go_sql_flow_facts(4, 4, SinkKind::SqlQuery);
        mark_facts_as_adapter_shaped(&mut wrong_adapter_facts, "node-typescript");

        let mut missing_source_range_facts = go_sql_flow_facts(4, 4, SinkKind::SqlQuery);
        missing_source_range_facts.data_sources[0].range = None;

        let mut missing_sink_range_facts = go_sql_flow_facts(4, 4, SinkKind::SqlQuery);
        missing_sink_range_facts.sinks[0].range = None;

        let mut unusable_source_range_facts = go_sql_flow_facts(4, 4, SinkKind::SqlQuery);
        unusable_source_range_facts.data_sources[0].range = Some(fact_range(99, 99));

        let mut unusable_sink_range_facts = go_sql_flow_facts(4, 4, SinkKind::SqlQuery);
        unusable_sink_range_facts.sinks[0].range = Some(fact_range(99, 99));

        let command_sink_facts = go_sql_flow_facts(4, 4, SinkKind::Command);

        let mut sanitized_facts = go_sql_flow_facts(4, 4, SinkKind::SqlQuery);
        let sanitized_file_id = sanitized_facts.source_files[0].id.clone();
        sanitized_facts.sanitizers.push(sanitizer_fact_with_scope(
            "query-params",
            &sanitized_file_id,
            Some("show"),
            SanitizerKind::Parameterization,
            Some("db.Query params"),
            4,
            4,
        ));
        sanitized_facts.taint_edges[0].sanitizer_id = Some("query-params".to_string());

        for (case, facts) in [
            ("empty", empty_facts),
            ("wrong-file", wrong_file_facts),
            ("wrong-language", wrong_language_facts),
            ("wrong-adapter", wrong_adapter_facts),
            ("missing-source-range", missing_source_range_facts),
            ("missing-sink-range", missing_sink_range_facts),
            ("unusable-source-range", unusable_source_range_facts),
            ("unusable-sink-range", unusable_sink_range_facts),
            ("command-sink", command_sink_facts),
            ("sanitized", sanitized_facts),
        ] {
            let no_fallback_findings = scan_project_with_external_and_facts(
                &no_fallback_graph,
                &Config::default(),
                Some(&facts),
            )
            .findings;
            assert!(
                go_sql_findings(&no_fallback_findings).is_empty(),
                "{case} facts should not create Go SQL findings; findings: {no_fallback_findings:?}"
            );

            let fallback_findings = scan_project_with_external_and_facts(
                &fallback_graph,
                &Config::default(),
                Some(&facts),
            )
            .findings;
            assert_eq!(
                go_sql_findings(&fallback_findings).len(),
                1,
                "{case} facts should not suppress Go SQL heuristic fallback; findings: {fallback_findings:?}"
            );
        }

        let _ = fs::remove_dir_all(no_fallback_root);
        let _ = fs::remove_dir_all(fallback_root);
    }

