    #[test]
    fn node_bad_fixture_produces_deterministic_findings() {
        let first = fixture_findings("node-express-bad-service");
        let second = fixture_findings("node-express-bad-service");
        assert_eq!(first, second);
        assert!(first.len() >= 15, "findings: {}", first.len());
        for id in [
            "node/floating-promise",
            "node/express-async-error-unhandled",
            "node/route-missing-validation",
            "node/route-missing-auth",
            "node/cors-wildcard-production",
            "node/eval-or-function-constructor",
            "node/child-process-shell-injection",
            "node/sql-string-concat",
            "node/prisma-unbounded-findmany",
            "node/unbounded-json-body",
            "node/missing-lockfile",
            "node/multiple-lockfiles",
            "node/express-error-handler-missing",
            "node/duplicate-dto-shape",
            "node/dead-export",
            "node/circular-import-risk",
            "agent/placeholder-test",
            "agent/semantic-copy-paste",
            "agent/spaghetti-control-flow",
        ] {
            assert!(
                first.iter().any(|finding| finding.rule_id == id),
                "missing {id}"
            );
        }
        let floating_promise = first
            .iter()
            .find(|finding| finding.rule_id == "node/floating-promise")
            .expect("node/floating-promise finding");
        assert_eq!(floating_promise.confidence, Confidence::Medium);
        assert_eq!(floating_promise.fix.safety, FixSafety::Guided);
        assert!(floating_promise.fix.available);
        assert!(floating_promise.location.is_some());
        assert!(floating_promise
            .evidence
            .as_ref()
            .is_some_and(|evidence| evidence.snippet.contains("saveLoginAttempt")));
        assert!(floating_promise.remediation.contains("Await the promise"));
        assert!(first
            .iter()
            .all(|finding| finding.language.as_deref() == Some("Node/TypeScript")));
        assert!(first
            .iter()
            .filter(|finding| finding.severity == Severity::Critical)
            .all(|finding| finding
                .evidence
                .as_ref()
                .is_some_and(|evidence| evidence.redacted)));
    }

    #[test]
    fn node_route_auth_fact_middleware_suppresses_missing_auth() {
        let root = temp_root("node-route-auth-facts-suppress");
        let source = "const app = require('express')();\n\
app.use('/admin', requireAuth);\n\
app.get('/admin/users', listUsers);\n\
function requireAuth(req, res, next) { next(); }\n\
function listUsers(req, res) { res.json({ ok: true }); }\n";
        let graph = node_source_graph(&root, source);
        let mut facts = node_route_test_facts();
        let file_id = facts.source_files[0].id.clone();
        facts.routes.push(node_route_fact_with_scope(
            "admin-middleware",
            "ANY",
            "/admin",
            &file_id,
            Some("requireAuth"),
            2,
            2,
            "app.use",
        ));
        facts.routes.push(node_route_fact_with_scope(
            "admin-users",
            "GET",
            "/admin/users",
            &file_id,
            Some("listUsers"),
            3,
            3,
            "app.get",
        ));
        facts.sanitizers.push(sanitizer_fact_with_scope(
            "auth-sanitizer",
            &file_id,
            Some("requireAuth"),
            SanitizerKind::Authorization,
            Some("requireAuth"),
            4,
            4,
        ));

        let findings =
            scan_project_with_external_and_facts(&graph, &Config::default(), Some(&facts)).findings;
        assert!(
            !findings
                .iter()
                .any(|finding| finding.rule_id == "node/route-missing-auth"),
            "auth middleware fact should suppress missing auth; findings: {findings:?}"
        );

        let _ = fs::remove_dir_all(root);
    }

