    #[test]
    fn csharp_sql_unusable_facts_do_not_create_or_suppress_fallback() {
        let flow_root = temp_root("csharp-sql-unusable-facts-flow");
        let flow_source = "using Microsoft.AspNetCore.Http;\n\
using Microsoft.Data.SqlClient;\n\
\n\
void Show(HttpRequest request, SqlConnection connection)\n\
{\n\
    var id = request.Query[\"id\"];\n\
    var sql = $\"SELECT * FROM users WHERE id = {id}\";\n\
    using var command = new SqlCommand(sql, connection);\n\
    command.ExecuteReader();\n\
}\n";
        let flow_graph = csharp_source_graph(&flow_root, flow_source);
        let fallback_root = temp_root("csharp-sql-unusable-facts-fallback");
        let fallback_source = "using Microsoft.AspNetCore.Http;\n\
using Microsoft.Data.SqlClient;\n\
\n\
void Show(HttpRequest request, SqlConnection connection)\n\
{\n\
    using var command = new SqlCommand($\"SELECT * FROM users WHERE id = {request.Query[\"id\"]}\", connection);\n\
}\n";
        let fallback_graph = csharp_source_graph(&fallback_root, fallback_source);

        let mut base_facts = csharp_route_test_facts();
        let file_id = base_facts.source_files[0].id.clone();
        base_facts.data_sources.push(request_source_fact_with_scope(
            "request-id",
            &file_id,
            Some("Show"),
            Some("request.Query"),
            6,
            6,
        ));
        base_facts.sinks.push(csharp_sql_sink(
            "sql-query",
            &file_id,
            Some("Show"),
            "new SqlCommand",
            8,
            8,
        ));
        base_facts.taint_edges.push(taint_edge(
            "request-to-sql",
            "request-id",
            "sql-query",
            TaintEdgeKind::SourceToSink,
            None,
        ));
        mark_facts_as_adapter_shaped(&mut base_facts, "csharp");

        let mut missing_source_range_facts = base_facts.clone();
        missing_source_range_facts.data_sources[0].range = None;

        let mut missing_sink_range_facts = base_facts.clone();
        missing_sink_range_facts.sinks[0].range = None;

        let mut wrong_adapter_facts = base_facts.clone();
        mark_facts_as_adapter_shaped(&mut wrong_adapter_facts, "node-typescript");

        let mut wrong_file_facts = base_facts.clone();
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/Other.cs", "C#"));
        let wrong_file_id = wrong_file_facts.source_files[1].id.clone();
        wrong_file_facts.data_sources[0].file_id = Some(wrong_file_id.clone());
        wrong_file_facts.sinks[0].file_id = Some(wrong_file_id);

        let mut wrong_sink_kind_facts = base_facts.clone();
        wrong_sink_kind_facts.sinks[0].kind = SinkKind::Command;

        for (case, facts) in [
            ("missing-source-range", missing_source_range_facts),
            ("missing-sink-range", missing_sink_range_facts),
            ("wrong-adapter", wrong_adapter_facts),
            ("wrong-file", wrong_file_facts),
            ("wrong-sink-kind", wrong_sink_kind_facts),
        ] {
            let flow_findings =
                scan_project_with_external_and_facts(&flow_graph, &Config::default(), Some(&facts))
                    .findings;
            assert!(
                csharp_sql_findings(&flow_findings).is_empty(),
                "{case} facts should not create C# SQL findings; findings: {flow_findings:?}"
            );

            let fallback_findings = scan_project_with_external_and_facts(
                &fallback_graph,
                &Config::default(),
                Some(&facts),
            )
            .findings;
            let fallback_sql_findings = csharp_sql_findings(&fallback_findings);
            assert_eq!(
                fallback_sql_findings.len(),
                1,
                "{case} facts should not suppress C# SQL text fallback; findings: {fallback_findings:?}"
            );
            assert_eq!(
                fallback_sql_findings[0]
                    .location
                    .as_ref()
                    .and_then(|location| location.line),
                Some(6),
                "{case} fallback finding should stay on the text line"
            );
        }

        let _ = fs::remove_dir_all(flow_root);
        let _ = fs::remove_dir_all(fallback_root);
    }

