    #[test]
    fn python_yaml_wrong_file_call_fact_preserves_current_file_fallback() {
        let root = temp_root("python-yaml-wrong-file-call-fallback");
        let source = "import yaml\n\
\n\
def parse(data):\n\
    print(data)\n\
    return yaml.load(data)\n";
        let graph = python_source_graph(&root, source);

        let mut facts = AnalysisFacts::empty();
        let current_file =
            SourceFileFact::new("src/app.py", "Python").with_content(source.as_bytes());
        let current_file_id = current_file.id.clone();
        let other_source = "import yaml\n\
\n\
def parse_other(data):\n\
    return yaml.load(data)\n";
        let other_file =
            SourceFileFact::new("src/other.py", "Python").with_content(other_source.as_bytes());
        let other_file_id = other_file.id.clone();
        assert_ne!(
            current_file_id, other_file_id,
            "regression setup requires distinct source file ids"
        );
        facts.source_files.push(current_file);
        facts.source_files.push(other_file);
        facts.calls.push(CallFact {
            id: "print-current-file-call".to_string(),
            file_id: Some(current_file_id),
            caller_symbol_id: None,
            callee_symbol_id: None,
            callee_name: "print".to_string(),
            range: Some(source_range_for_first(source, "print(data)")),
            arguments: vec!["data".to_string()],
            metadata: BTreeMap::new(),
        });
        facts.calls.push(CallFact {
            id: "yaml-load-wrong-file-call".to_string(),
            file_id: Some(other_file_id),
            caller_symbol_id: None,
            callee_symbol_id: None,
            callee_name: "yaml.load".to_string(),
            range: Some(source_range_for_first(source, "yaml.load(data)")),
            arguments: vec!["data".to_string()],
            metadata: BTreeMap::new(),
        });

        let findings =
            scan_project_with_external_and_facts(&graph, &Config::default(), Some(&facts)).findings;
        let yaml_findings = python_yaml_findings(&findings);
        assert_eq!(
            yaml_findings.len(),
            1,
            "wrong-file YAML CallFact should not suppress current-file text fallback; findings: {findings:?}; facts: {facts:?}"
        );
        assert_eq!(
            yaml_findings[0]
                .location
                .as_ref()
                .and_then(|location| location.line),
            Some(5)
        );

        let _ = fs::remove_dir_all(root);
    }

