    #[test]
    fn node_child_process_real_adapter_cross_line_exec_flags_once() {
        let root = temp_root("node-child-process-real-adapter-exec");
        let source = "const { exec } = require('node:child_process');\n\
function run(req) {\n\
  const cmd = req.query.cmd;\n\
  return exec(cmd);\n\
}\n";
        let graph = node_source_graph(&root, source);
        let facts = node_adapter_facts(&graph, source);
        assert!(
            facts
                .data_sources
                .iter()
                .any(|source| source.kind == DataSourceKind::Request)
                && facts.sinks.iter().any(|sink| sink.kind == SinkKind::Command)
                && facts.taint_edges.iter().all(|edge| {
                    !facts.data_sources.iter().any(|source| {
                        source.id == edge.source_id && source.kind == DataSourceKind::Request
                    }) || !facts.sinks.iter().any(|sink| {
                        sink.id == edge.target_id && sink.kind == SinkKind::Command
                    })
                }),
            "real Node adapter should expose request and command facts without a dedicated request-to-command edge for this shape; facts: {facts:?}"
        );

        let findings =
            scan_project_with_external_and_facts(&graph, &Config::default(), Some(&facts)).findings;
        let command_findings = node_child_process_findings(&findings);
        assert_eq!(
            command_findings.len(),
            1,
            "fact-backed cross-line Node request-to-exec flow should flag once; findings: {findings:?}"
        );
        assert_eq!(
            command_findings[0]
                .location
                .as_ref()
                .and_then(|location| location.line),
            Some(4)
        );

        let _ = fs::remove_dir_all(root);
    }

