    #[test]
    fn node_child_process_unusable_facts_do_not_create_or_suppress_fallback() {
        let flow_root = temp_root("node-child-process-unusable-facts-flow");
        let flow_source = "const { exec } = require('node:child_process');\n\
function run(req) {\n\
  const cmd = req.query.cmd;\n\
  return exec(cmd);\n\
}\n";
        let flow_graph = node_source_graph(&flow_root, flow_source);
        let fallback_root = temp_root("node-child-process-unusable-facts-fallback");
        let fallback_source = "const { exec } = require('node:child_process');\n\
function run(req) {\n\
  return exec('ls ' + req.query.path);\n\
}\n";
        let fallback_graph = node_source_graph(&fallback_root, fallback_source);

        let empty_facts = AnalysisFacts::empty();

        let mut wrong_file_facts = AnalysisFacts::empty();
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/app.ts", "Node/TypeScript"));
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/other.ts", "Node/TypeScript"));
        let wrong_file_id = wrong_file_facts.source_files[1].id.clone();
        wrong_file_facts
            .data_sources
            .push(request_source_fact_with_scope(
                "request-cmd",
                &wrong_file_id,
                Some("run"),
                Some("req.query.cmd"),
                3,
                3,
            ));
        wrong_file_facts.sinks.push(sink_fact_with_scope(
            "command-sink",
            &wrong_file_id,
            Some("run"),
            SinkKind::Command,
            Some("exec"),
            4,
            4,
        ));
        wrong_file_facts.taint_edges.push(taint_edge(
            "request-to-command",
            "request-cmd",
            "command-sink",
            TaintEdgeKind::SourceToSink,
            None,
        ));
        mark_facts_as_adapter_shaped(&mut wrong_file_facts, "node-typescript");
        mark_node_edges_as_real_local_shape(&mut wrong_file_facts);

        let mut wrong_adapter_facts = node_command_flow_facts(3, 4, SinkKind::Command, "exec");
        mark_facts_as_adapter_shaped(&mut wrong_adapter_facts, "python");

        let mut missing_source_range_facts =
            node_command_flow_facts(3, 4, SinkKind::Command, "exec");
        missing_source_range_facts.data_sources[0].range = None;

        let mut missing_sink_range_facts = node_command_flow_facts(3, 4, SinkKind::Command, "exec");
        missing_sink_range_facts.sinks[0].range = None;

        let mut unusable_source_range_facts =
            node_command_flow_facts(3, 4, SinkKind::Command, "exec");
        unusable_source_range_facts.data_sources[0].range = Some(fact_range(99, 99));

        let mut unsupported_confidence_facts =
            node_command_flow_facts(3, 4, SinkKind::Command, "exec");
        unsupported_confidence_facts.taint_edges[0].confidence = Confidence::Medium;

        let mut sanitized_facts = node_command_flow_facts(3, 4, SinkKind::Command, "exec");
        sanitized_facts.taint_edges[0].sanitizer_id = Some("validator".to_string());

        let wrong_sink_facts = node_command_flow_facts(3, 4, SinkKind::SqlQuery, "exec");

        for (case, facts) in [
            ("empty", empty_facts),
            ("wrong-file", wrong_file_facts),
            ("wrong-adapter", wrong_adapter_facts),
            ("missing-source-range", missing_source_range_facts),
            ("missing-sink-range", missing_sink_range_facts),
            ("unusable-source-range", unusable_source_range_facts),
            ("unsupported-confidence", unsupported_confidence_facts),
            ("sanitized", sanitized_facts),
            ("wrong-sink", wrong_sink_facts),
        ] {
            let flow_findings =
                scan_project_with_external_and_facts(&flow_graph, &Config::default(), Some(&facts))
                    .findings;
            assert!(
                node_child_process_findings(&flow_findings).is_empty(),
                "{case} facts should not create Node child-process findings; findings: {flow_findings:?}"
            );

            let fallback_findings = scan_project_with_external_and_facts(
                &fallback_graph,
                &Config::default(),
                Some(&facts),
            )
            .findings;
            assert_eq!(
                node_child_process_findings(&fallback_findings).len(),
                1,
                "{case} facts should not suppress Node child-process text fallback; findings: {fallback_findings:?}"
            );
        }

        let _ = fs::remove_dir_all(flow_root);
        let _ = fs::remove_dir_all(fallback_root);
    }

