    #[test]
    fn java_timeout_real_adapter_webclient_facts_emit_and_respect_timeout_evidence() {
        let unconfigured_root = temp_root("java-timeout-real-adapter-unconfigured");
        let unconfigured_source =
            "import org.springframework.web.reactive.function.client.WebClient;\n\
class Client {\n\
  void run() {\n\
    WebClient client = WebClient.create();\n\
    client.get().uri(\"https://example.test\").retrieve();\n\
  }\n\
}\n";
        let unconfigured_graph = java_source_graph(&unconfigured_root, unconfigured_source);
        let unconfigured_facts = java_adapter_facts(&unconfigured_graph, unconfigured_source);
        assert!(
            unconfigured_facts.sinks.iter().any(|sink| {
                sink.kind == SinkKind::NetworkRequest
                    && sink
                        .metadata
                        .get("adapter")
                        .is_some_and(|adapter| adapter == "java")
                    && sink.name.as_deref().is_some_and(|name| name.contains("client.get"))
                    && !sink.metadata.contains_key("timeoutEvidence")
            }),
            "real Java adapter should emit unconfigured WebClient NetworkRequest facts for a variable named client; facts: {unconfigured_facts:?}"
        );
        let unconfigured_findings = scan_project_with_external_and_facts(
            &unconfigured_graph,
            &Config::default(),
            Some(&unconfigured_facts),
        )
        .findings;
        let unconfigured_timeout_findings = java_timeout_findings(&unconfigured_findings);
        assert_eq!(
            unconfigured_timeout_findings.len(),
            1,
            "unconfigured real Java WebClient facts should emit a timeout finding; findings: {unconfigured_findings:?}"
        );
        assert_eq!(
            unconfigured_timeout_findings[0]
                .location
                .as_ref()
                .and_then(|location| location.line),
            Some(5)
        );

        let configured_root = temp_root("java-timeout-real-adapter-configured");
        let configured_source = "import java.time.Duration;\n\
import reactor.netty.http.client.HttpClient;\n\
import org.springframework.http.client.reactive.ReactorClientHttpConnector;\n\
import org.springframework.web.reactive.function.client.WebClient;\n\
class Client {\n\
  void run() {\n\
    HttpClient responseClient = HttpClient.create().responseTimeout(Duration.ofSeconds(2));\n\
    WebClient client = WebClient.builder()\n\
        .clientConnector(new ReactorClientHttpConnector(responseClient))\n\
        .build();\n\
    client.get().uri(\"https://example.test\").retrieve();\n\
  }\n\
}\n";
        let configured_graph = java_source_graph(&configured_root, configured_source);
        let configured_facts = java_adapter_facts(&configured_graph, configured_source);
        assert!(
            configured_facts.sinks.iter().any(|sink| {
                sink.kind == SinkKind::NetworkRequest
                    && sink.metadata.get("timeoutEvidence").map(String::as_str)
                        == Some("present")
                    && sink
                        .metadata
                        .get("timeoutEvidenceKind")
                        .is_some_and(|kind| kind == "responseTimeout")
            }),
            "real Java adapter should mark configured WebClient timeout evidence; facts: {configured_facts:?}"
        );
        let configured_findings = scan_project_with_external_and_facts(
            &configured_graph,
            &Config::default(),
            Some(&configured_facts),
        )
        .findings;
        assert!(
            java_timeout_findings(&configured_findings).is_empty(),
            "configured real Java WebClient timeout evidence should stay quiet; findings: {configured_findings:?}"
        );

        let _ = fs::remove_dir_all(unconfigured_root);
        let _ = fs::remove_dir_all(configured_root);
    }

