    #[test]
    fn java_sql_unusable_facts_do_not_create_or_suppress_fallback() {
        let no_fallback_root = temp_root("java-sql-unusable-no-create");
        let no_fallback_source = "import org.springframework.web.bind.annotation.*;\n\
@RestController\n\
class UserController {\n\
  @GetMapping(\"/users/{id}\")\n\
  Object show(@RequestParam String id) {\n\
    return jdbcTemplate.query(\"SELECT * FROM users WHERE id = ?\", mapper, id);\n\
  }\n\
}\n";
        let no_fallback_graph = java_source_graph(&no_fallback_root, no_fallback_source);
        let fallback_root = temp_root("java-sql-unusable-fallback");
        let fallback_source = "import org.springframework.web.bind.annotation.*;\n\
@RestController\n\
class UserController {\n\
  @GetMapping(\"/users/{id}\")\n\
  Object show(@RequestParam String id) {\n\
    return jdbcTemplate.query(\"SELECT * FROM users WHERE id = \" + id, mapper);\n\
  }\n\
}\n";
        let fallback_graph = java_source_graph(&fallback_root, fallback_source);

        let empty_facts = AnalysisFacts::empty();

        let mut wrong_file_facts = AnalysisFacts::empty();
        wrong_file_facts.source_files.push(SourceFileFact::new(
            "src/main/java/com/acme/UserController.java",
            "Java",
        ));
        wrong_file_facts.source_files.push(SourceFileFact::new(
            "src/main/java/com/acme/OtherController.java",
            "Java",
        ));
        let wrong_file_id = wrong_file_facts.source_files[1].id.clone();
        wrong_file_facts
            .data_sources
            .push(request_source_fact_with_scope(
                "request-param",
                &wrong_file_id,
                Some("show"),
                Some("id"),
                5,
                5,
            ));
        wrong_file_facts.sinks.push(sink_fact_with_scope(
            "sql-query",
            &wrong_file_id,
            Some("show"),
            SinkKind::SqlQuery,
            Some("jdbcTemplate.query"),
            6,
            6,
        ));
        wrong_file_facts.taint_edges.push(taint_edge(
            "request-to-sql",
            "request-param",
            "sql-query",
            TaintEdgeKind::SourceToSink,
            None,
        ));
        mark_facts_as_adapter_shaped(&mut wrong_file_facts, "java");
        mark_java_edges_as_real_local_shape(&mut wrong_file_facts);

        let mut wrong_language_facts = java_sql_flow_facts(5, 6, SinkKind::SqlQuery);
        wrong_language_facts.source_files[0].language = "Python".to_string();

        let mut wrong_adapter_facts = java_sql_flow_facts(5, 6, SinkKind::SqlQuery);
        mark_facts_as_adapter_shaped(&mut wrong_adapter_facts, "node-typescript");

        let mut missing_source_range_facts = java_sql_flow_facts(5, 6, SinkKind::SqlQuery);
        missing_source_range_facts.data_sources[0].range = None;

        let mut missing_sink_range_facts = java_sql_flow_facts(5, 6, SinkKind::SqlQuery);
        missing_sink_range_facts.sinks[0].range = None;

        let mut unusable_source_range_facts = java_sql_flow_facts(5, 6, SinkKind::SqlQuery);
        unusable_source_range_facts.data_sources[0].range = Some(fact_range(99, 99));

        let mut unusable_sink_range_facts = java_sql_flow_facts(5, 6, SinkKind::SqlQuery);
        unusable_sink_range_facts.sinks[0].range = Some(fact_range(99, 99));

        let command_sink_facts = java_sql_flow_facts(5, 6, SinkKind::Command);

        let mut sanitized_facts = java_sql_flow_facts(5, 6, SinkKind::SqlQuery);
        let sanitized_file_id = sanitized_facts.source_files[0].id.clone();
        sanitized_facts.sanitizers.push(sanitizer_fact_with_scope(
            "validator",
            &sanitized_file_id,
            Some("show"),
            SanitizerKind::Validation,
            Some("validateId"),
            6,
            6,
        ));
        sanitized_facts.taint_edges[0].sanitizer_id = Some("validator".to_string());

        let mut parameterized_facts = java_sql_flow_facts(5, 6, SinkKind::SqlQuery);
        let parameterized_file_id = parameterized_facts.source_files[0].id.clone();
        parameterized_facts
            .sanitizers
            .push(sanitizer_fact_with_scope(
                "query-params",
                &parameterized_file_id,
                Some("show"),
                SanitizerKind::Parameterization,
                Some("jdbcTemplate query args"),
                6,
                6,
            ));
        parameterized_facts.taint_edges.push(taint_edge(
            "request-to-sql-sanitized",
            "request-param",
            "sql-query",
            TaintEdgeKind::Sanitized,
            Some("query-params"),
        ));

        for (case, facts) in [
            ("empty", empty_facts),
            ("wrong-file", wrong_file_facts),
            ("wrong-language", wrong_language_facts),
            ("wrong-adapter", wrong_adapter_facts),
            ("missing-source-range", missing_source_range_facts),
            ("missing-sink-range", missing_sink_range_facts),
            ("unusable-source-range", unusable_source_range_facts),
            ("unusable-sink-range", unusable_sink_range_facts),
            ("command-sink", command_sink_facts),
            ("sanitized", sanitized_facts),
            ("parameterized", parameterized_facts),
        ] {
            let no_fallback_findings = scan_project_with_external_and_facts(
                &no_fallback_graph,
                &Config::default(),
                Some(&facts),
            )
            .findings;
            assert!(
                java_sql_findings(&no_fallback_findings).is_empty(),
                "{case} facts should not create Java SQL findings; findings: {no_fallback_findings:?}"
            );

            let fallback_findings = scan_project_with_external_and_facts(
                &fallback_graph,
                &Config::default(),
                Some(&facts),
            )
            .findings;
            assert_eq!(
                java_sql_findings(&fallback_findings).len(),
                1,
                "{case} facts should not suppress Java SQL heuristic fallback; findings: {fallback_findings:?}"
            );
        }

        let _ = fs::remove_dir_all(no_fallback_root);
        let _ = fs::remove_dir_all(fallback_root);
    }

