    #[test]
    fn python_subprocess_unusable_facts_do_not_create_or_suppress_fallback() {
        let flow_root = temp_root("python-subprocess-unusable-facts-flow");
        let flow_source = r#"import subprocess

def run_cmd(request):
    cmd = request.args.get("cmd")
    return subprocess.run(cmd, shell=True)
"#;
        let flow_graph = python_source_graph(&flow_root, flow_source);
        let fallback_root = temp_root("python-subprocess-unusable-facts-fallback");
        let fallback_source = r#"import subprocess

def run_cmd(request):
    return subprocess.run("ls " + request.args["path"], shell=True)
"#;
        let fallback_graph = python_source_graph(&fallback_root, fallback_source);

        let empty_facts = AnalysisFacts::empty();

        let mut wrong_file_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::Command, "subprocess.run");
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/other.py", "Python"));
        let wrong_file_id = wrong_file_facts.source_files[1].id.clone();
        wrong_file_facts.data_sources[0].file_id = Some(wrong_file_id.clone());
        wrong_file_facts.sinks[0].file_id = Some(wrong_file_id);

        let mut wrong_language_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::Command, "subprocess.run");
        wrong_language_facts.source_files[0].language = "Java".to_string();

        let mut wrong_adapter_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::Command, "subprocess.run");
        mark_facts_as_adapter_shaped(&mut wrong_adapter_facts, "node-typescript");

        let mut missing_source_range_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::Command, "subprocess.run");
        missing_source_range_facts.data_sources[0].range = None;

        let mut missing_sink_range_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::Command, "subprocess.run");
        missing_sink_range_facts.sinks[0].range = None;

        let mut unusable_source_range_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::Command, "subprocess.run");
        unusable_source_range_facts.data_sources[0].range = Some(fact_range(99, 99));

        let mut unsupported_confidence_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::Command, "subprocess.run");
        unsupported_confidence_facts.taint_edges[0].confidence = Confidence::Medium;

        let mut sanitized_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::Command, "subprocess.run");
        sanitized_facts.taint_edges[0].sanitizer_id = Some("validator".to_string());

        let wrong_sink_facts =
            python_subprocess_flow_facts(4, 5, SinkKind::SqlQuery, "subprocess.run");

        for (case, facts) in [
            ("empty", empty_facts),
            ("wrong-file", wrong_file_facts),
            ("wrong-language", wrong_language_facts),
            ("wrong-adapter", wrong_adapter_facts),
            ("missing-source-range", missing_source_range_facts),
            ("missing-sink-range", missing_sink_range_facts),
            ("unusable-source-range", unusable_source_range_facts),
            ("unsupported-confidence", unsupported_confidence_facts),
            ("sanitized", sanitized_facts),
            ("wrong-sink", wrong_sink_facts),
        ] {
            let flow_findings =
                scan_project_with_external_and_facts(&flow_graph, &Config::default(), Some(&facts))
                    .findings;
            assert!(
                python_subprocess_shell_findings(&flow_findings).is_empty(),
                "{case} facts should not create Python subprocess findings; findings: {flow_findings:?}"
            );

            let fallback_findings = scan_project_with_external_and_facts(
                &fallback_graph,
                &Config::default(),
                Some(&facts),
            )
            .findings;
            let fallback_subprocess_findings = python_subprocess_shell_findings(&fallback_findings);
            assert_eq!(
                fallback_subprocess_findings.len(),
                1,
                "{case} facts should not suppress Python subprocess text fallback; findings: {fallback_findings:?}"
            );
            assert_eq!(
                fallback_subprocess_findings[0]
                    .location
                    .as_ref()
                    .and_then(|location| location.line),
                Some(4),
                "{case} fallback finding should stay on the text line"
            );
        }

        let _ = fs::remove_dir_all(flow_root);
        let _ = fs::remove_dir_all(fallback_root);
    }

    #[test]
    fn python_subprocess_sanitized_edge_does_not_report() {
        let root = temp_root("python-subprocess-sanitized-edge");
        let source = r#"from flask import request
import shlex
import subprocess

def run_cmd():
    cmd = request.args.get("cmd")
    safe_cmd = shlex.quote(cmd)
    return subprocess.run(safe_cmd, shell=True)
"#;
        let graph = python_source_graph(&root, source);
        let facts = python_adapter_facts(&graph, source);
        let shell_quote_sanitizer_ids = facts
            .sanitizers
            .iter()
            .filter(|sanitizer| {
                sanitizer.kind == SanitizerKind::Escaping
                    && sanitizer
                        .name
                        .as_deref()
                        .is_some_and(|name| name.ends_with("quote"))
            })
            .map(|sanitizer| sanitizer.id.as_str())
            .collect::<BTreeSet<_>>();
        assert!(
            !python_request_command_edges(&facts).is_empty(),
            "real Python adapter should expose a separate request-to-command edge; facts: {facts:?}"
        );
        assert!(
            facts.taint_edges.iter().any(|edge| {
                edge.kind == TaintEdgeKind::Sanitized
                    && shell_quote_sanitizer_ids.contains(edge.target_id.as_str())
                    && facts.data_sources.iter().any(|source| {
                        source.id == edge.source_id && source.kind == DataSourceKind::Request
                    })
            }),
            "real Python adapter should expose a separate request-to-shlex.quote sanitized edge; facts: {facts:?}"
        );

        let findings =
            scan_project_with_external_and_facts(&graph, &Config::default(), Some(&facts)).findings;
        assert!(
            python_subprocess_shell_findings(&findings).is_empty(),
            "real-adapter shlex.quote command flows must not emit subprocess shell findings; findings: {findings:?}"
        );

        let _ = fs::remove_dir_all(root);
    }

