    #[test]
    fn php_shell_exec_unusable_facts_do_not_create_or_suppress_fallback() {
        let flow_root = temp_root("php-shell-exec-unusable-facts-flow");
        let flow_source = "<?php\n\
function run_cmd() {\n\
    $cmd = $_POST['cmd'];\n\
    return shell_exec($cmd);\n\
}\n";
        let flow_graph = php_source_graph(&flow_root, flow_source);
        let fallback_root = temp_root("php-shell-exec-unusable-facts-fallback");
        let fallback_source = "<?php\n\
function run_cmd() {\n\
    return shell_exec($_POST['cmd']);\n\
}\n";
        let fallback_graph = php_source_graph(&fallback_root, fallback_source);

        let mut missing_file_facts = AnalysisFacts::empty();
        missing_file_facts
            .data_sources
            .push(request_source_fact_with_scope(
                "request-cmd",
                "missing-file",
                Some("run_cmd"),
                Some("$_POST['cmd']"),
                3,
                3,
            ));
        missing_file_facts.sinks.push(sink_fact_with_scope(
            "command-sink",
            "missing-file",
            Some("run_cmd"),
            SinkKind::Command,
            Some("shell_exec"),
            4,
            4,
        ));
        missing_file_facts.taint_edges.push(taint_edge(
            "request-to-command",
            "request-cmd",
            "command-sink",
            TaintEdgeKind::SourceToSink,
            None,
        ));
        mark_facts_as_adapter_shaped(&mut missing_file_facts, "php");

        let mut missing_range_facts =
            php_shell_exec_flow_facts(3, 4, SinkKind::Command, "shell_exec");
        missing_range_facts.data_sources[0].range = None;

        let mut wrong_file_facts = php_shell_exec_flow_facts(3, 4, SinkKind::Command, "shell_exec");
        wrong_file_facts
            .source_files
            .push(SourceFileFact::new("src/other.php", "PHP"));
        let wrong_file_id = wrong_file_facts.source_files[1].id.clone();
        wrong_file_facts.data_sources[0].file_id = Some(wrong_file_id.clone());
        wrong_file_facts.sinks[0].file_id = Some(wrong_file_id);

        let mut non_php_facts = AnalysisFacts::empty();
        non_php_facts
            .source_files
            .push(SourceFileFact::new("src/app.php", "Java"));
        let non_php_file_id = non_php_facts.source_files[0].id.clone();
        non_php_facts
            .data_sources
            .push(request_source_fact_with_scope(
                "request-cmd",
                &non_php_file_id,
                Some("run_cmd"),
                Some("$_POST['cmd']"),
                3,
                3,
            ));
        non_php_facts.sinks.push(sink_fact_with_scope(
            "command-sink",
            &non_php_file_id,
            Some("run_cmd"),
            SinkKind::Command,
            Some("shell_exec"),
            4,
            4,
        ));
        non_php_facts.taint_edges.push(taint_edge(
            "request-to-command",
            "request-cmd",
            "command-sink",
            TaintEdgeKind::SourceToSink,
            None,
        ));
        mark_facts_as_adapter_shaped(&mut non_php_facts, "php");

        let mut low_confidence_facts =
            php_shell_exec_flow_facts(3, 4, SinkKind::Command, "shell_exec");
        low_confidence_facts.taint_edges[0].confidence = Confidence::Low;

        let mut sanitized_facts = php_shell_exec_flow_facts(3, 4, SinkKind::Command, "shell_exec");
        sanitized_facts.taint_edges[0].sanitizer_id = Some("validator".to_string());

        let mut wrong_adapter_facts =
            php_shell_exec_flow_facts(3, 4, SinkKind::Command, "shell_exec");
        mark_facts_as_adapter_shaped(&mut wrong_adapter_facts, "node-typescript");

        let mut unrelated_database_facts =
            php_shell_exec_flow_facts(3, 4, SinkKind::Command, "shell_exec");
        unrelated_database_facts.data_sources[0].kind = DataSourceKind::Database;

        let non_command_sink_facts = php_shell_exec_flow_facts(3, 4, SinkKind::SqlQuery, "exec");

        for (case, facts) in [
            ("missing-file", missing_file_facts),
            ("missing-range", missing_range_facts),
            ("wrong-file", wrong_file_facts),
            ("non-php-source-file", non_php_facts),
            ("low-confidence-edge", low_confidence_facts),
            ("sanitized-edge", sanitized_facts),
            ("wrong-adapter", wrong_adapter_facts),
            ("unrelated-database-source", unrelated_database_facts),
            ("non-command-sink", non_command_sink_facts),
        ] {
            let flow_findings =
                scan_project_with_external_and_facts(&flow_graph, &Config::default(), Some(&facts))
                    .findings;
            assert!(
                php_shell_exec_findings(&flow_findings).is_empty(),
                "{case} facts should not create PHP shell exec findings; findings: {flow_findings:?}"
            );

            let fallback_findings = scan_project_with_external_and_facts(
                &fallback_graph,
                &Config::default(),
                Some(&facts),
            )
            .findings;
            let fallback_shell_exec_findings = php_shell_exec_findings(&fallback_findings);
            assert_eq!(
                fallback_shell_exec_findings.len(),
                1,
                "{case} facts should not suppress PHP shell exec text fallback; findings: {fallback_findings:?}"
            );
            assert_eq!(
                fallback_shell_exec_findings[0]
                    .location
                    .as_ref()
                    .and_then(|location| location.line),
                Some(3),
                "{case} fallback finding should stay on the text line"
            );
        }

        let _ = fs::remove_dir_all(flow_root);
        let _ = fs::remove_dir_all(fallback_root);
    }

