    #[test]
    fn node_graph_controls_cover_exports_aliases_barrels_and_registries() {
        let package = r#"{
  "main": "./src/index.ts",
  "exports": {"./plugin": "./src/plugin.ts"},
  "backendDoctor": {"ignoreExports": ["./src/generated.ts"]}
}"#;
        let mut public = BTreeSet::new();
        collect_node_package_exports(package, Path::new("svc"), &mut public);
        assert!(public.contains(&PathBuf::from("svc/src/index.ts")));
        assert!(public.contains(&PathBuf::from("svc/src/plugin.ts")));
        let mut ignored = BTreeSet::new();
        collect_node_graph_ignores(package, Path::new("svc"), &mut ignored);
        assert!(ignored.contains(&PathBuf::from("svc/src/generated.ts")));
        assert!(tsconfig_has_path_aliases(
            r#"{"compilerOptions":{"paths":{"@app/*":["src/*"]}}}"#
        ));
        assert!(is_node_barrel_file(
            Path::new("src/index.ts"),
            "export * from './types';\nexport { x } from './x';"
        ));
        assert!(has_dynamic_node_registry(
            "const plugin = require(registry[name]);"
        ));
    }

    #[test]
    fn node_dead_export_suppresses_namespace_imported_modules_only() {
        let root = temp_root("node-dead-export-namespace-import");
        fs::create_dir_all(root.join("src")).expect("create source directory");
        fs::write(
            root.join("src/module.ts"),
            "export function usedByNamespace() { return 1; }\n\
export function exportedMember() { return 2; }\n",
        )
        .expect("write namespace imported module");
        fs::write(
            root.join("src/consumer.ts"),
            "import * as api from './module';\n\
api.exportedMember();\n",
        )
        .expect("write namespace import consumer");
        fs::write(
            root.join("src/orphan.ts"),
            "export function trulyUnused() { return 3; }\n",
        )
        .expect("write orphan module");

        let mut graph = ProjectGraph::empty(root.clone());
        graph.inventory.total_files = 3;
        graph.inventory.source_files = 3;
        graph.inventory.files = vec![
            PathBuf::from("src/module.ts"),
            PathBuf::from("src/consumer.ts"),
            PathBuf::from("src/orphan.ts"),
        ];

        let findings = scan_project(&graph, &Config::default());
        let dead_exports = findings
            .iter()
            .filter(|finding| finding.rule_id == "node/dead-export")
            .filter_map(|finding| {
                let location = finding.location.as_ref()?;
                Some((location.path.clone(), finding.message.as_str().to_string()))
            })
            .collect::<Vec<_>>();

        assert!(
            dead_exports
                .iter()
                .any(|(path, message)| path == Path::new("src/orphan.ts")
                    && message.contains("trulyUnused")),
            "non-namespace unused export should still be reported: {dead_exports:?}"
        );
        assert!(
            dead_exports
                .iter()
                .all(|(path, _)| path != Path::new("src/module.ts")),
            "namespace-imported module exports should not be reported dead: {dead_exports:?}"
        );

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn spaghetti_control_flow_detector_requires_depth_and_branch_count() {
        let flat = "export function flat(value: number) {\n\
  if (value > 0) { return 1; }\n\
  if (value > 1) { return 2; }\n\
  if (value > 2) { return 3; }\n\
  if (value > 3) { return 4; }\n\
  return 0;\n\
}\n";
        let flat_lines = flat.lines().collect::<Vec<_>>();
        assert!(
            spaghetti_control_flow_signal(Path::new("src/flat.ts"), &flat_lines).is_none(),
            "flat branch lists should not be treated as spaghetti control flow"
        );

        let nested = fs::read_to_string(fixture_path(
            "node-express-bad-service/src/graph/spaghetti.ts",
        ))
        .expect("read spaghetti fixture");
        let nested_lines = nested.lines().collect::<Vec<_>>();
        let signal =
            spaghetti_control_flow_signal(Path::new("src/graph/spaghetti.ts"), &nested_lines)
                .expect("deep branch-heavy fixture should be flagged");

        assert!(signal.max_control_flow_depth >= SPAGHETTI_MIN_CONTROL_FLOW_DEPTH);
        assert!(signal.control_flow_branches >= SPAGHETTI_MIN_BRANCHES);
        assert_eq!(signal.line, 9);
    }

