    #[test]
    fn fixture_scan_has_stable_semantic_fingerprints_and_perf_sanity() {
        let started = std::time::Instant::now();
        let findings = fixture_findings("node-express-bad-service");
        assert!(
            started.elapsed() < Duration::from_secs(2),
            "node fixture scan took {:?}",
            started.elapsed()
        );
        let duplicate = findings
            .iter()
            .find(|finding| finding.rule_id == "node/duplicate-dto-shape")
            .expect("node duplicate DTO finding");
        assert!(duplicate.metadata.contains_key("syntaxFingerprint"));
        let agent = findings
            .iter()
            .find(|finding| finding.rule_id == "agent/semantic-copy-paste")
            .expect("semantic copy-paste finding");
        assert!(agent.metadata.contains_key("semanticFingerprint"));
        assert_eq!(
            agent.metadata.get("authorshipClaim").map(String::as_str),
            Some("none")
        );
        for id in [
            "node/circular-import-risk",
            "node/dead-export",
            "agent/spaghetti-control-flow",
        ] {
            assert_fixture_has_rule(&findings, id);
        }
        let spaghetti = findings
            .iter()
            .find(|finding| finding.rule_id == "agent/spaghetti-control-flow")
            .expect("spaghetti control flow finding");
        assert_eq!(
            spaghetti.metadata.get("pattern").map(String::as_str),
            Some("spaghetti-control-flow")
        );
        assert!(spaghetti.metadata.contains_key("maxControlFlowDepth"));
        assert!(spaghetti.metadata.contains_key("controlFlowBranches"));
    }

    #[test]
    fn java_bad_fixture_produces_deterministic_redacted_findings() {
        let first = fixture_findings("java-spring-bad-service");
        let second = fixture_findings("java-spring-bad-service");
        assert_eq!(first, second);
        assert!(first.len() >= 15, "findings: {}", first.len());
        for id in [
            "java/http-client-no-timeout",
            "java/controller-bypasses-service-layer",
            "java/missing-request-validation",
            "java/missing-auth-annotation-or-filter",
            "java/transactional-remote-call",
            "java/transactional-private-method",
            "java/blocking-call-in-reactive-flow",
            "java/sql-string-concat",
            "java/jpa-n-plus-one-risk",
            "java/swallowed-exception",
            "java/too-broad-exception",
            "java/system-out-in-backend",
            "java/hardcoded-spring-secret",
            "java/actuator-exposed-sensitive-endpoints",
            "java/open-session-in-view-enabled",
            "java/entity-returned-from-controller",
            "java/missing-health-readiness",
            "java/duplicate-dto-shape",
            "agent/swallowed-error",
            "agent/semantic-copy-paste",
        ] {
            assert!(
                first.iter().any(|finding| finding.rule_id == id),
                "missing {id}"
            );
        }
        assert!(first
            .iter()
            .all(|finding| finding.language.as_deref() == Some("Java")));
        assert!(first.iter().all(|finding| finding.location.is_some()));
        assert!(first
            .iter()
            .filter(|finding| finding.severity == Severity::Critical)
            .all(|finding| finding
                .evidence
                .as_ref()
                .is_some_and(|evidence| evidence.redacted)));
        let valid = first
            .iter()
            .find(|finding| finding.rule_id == "java/missing-request-validation")
            .expect("validation finding");
        assert!(valid
            .fix
            .description
            .as_deref()
            .is_some_and(|fix| fix.contains("@Valid")));
        let transactional_remote_lines = first
            .iter()
            .filter(|finding| finding.rule_id == "java/transactional-remote-call")
            .filter_map(|finding| finding.location.as_ref()?.line)
            .collect::<Vec<_>>();
        assert_eq!(transactional_remote_lines, vec![22]);
        let controller_repository_lines = first
            .iter()
            .filter(|finding| finding.rule_id == "java/controller-bypasses-service-layer")
            .filter_map(|finding| finding.location.as_ref()?.line)
            .collect::<Vec<_>>();
        assert_eq!(controller_repository_lines, vec![27, 37]);
    }

    #[test]
    fn tier2_language_fixtures_produce_language_specific_findings() {
        for (fixture, language, prefix, ids) in [
            (
                "python-bad-service",
                "Python",
                "python/",
                vec![
                    "python/requests-without-timeout",
                    "python/sql-string-format",
                    "python/unsafe-yaml-load",
                    "python/subprocess-shell-true",
                ],
            ),
            (
                "python-fastapi-bad-service",
                "Python",
                "python/",
                vec![
                    "python/requests-without-timeout",
                    "python/sql-string-format",
                    "python/unsafe-yaml-load",
                    "python/subprocess-shell-true",
                ],
            ),
            (
                "csharp-bad-service",
                "C#",
                "csharp/",
                vec![
                    "csharp/httpclient-without-timeout",
                    "csharp/sql-string-interpolation",
                    "csharp/cors-allow-any-origin",
                    "csharp/sensitive-endpoint-missing-authorize",
                ],
            ),
            (
                "php-bad-service",
                "PHP",
                "php/",
                vec![
                    "php/pdo-query-string-concat",
                    "php/unserialize-user-input",
                    "php/shell-exec-user-input",
                    "php/display-errors-enabled",
                ],
            ),
            (
                "rust-bad-service",
                "Rust",
                "rust/",
                vec![
                    "rust/reqwest-client-without-timeout",
                    "rust/command-shell-format",
                    "rust/sql-format-string",
                    "rust/cors-allow-any-origin",
                ],
            ),
        ] {
            let first = fixture_findings(fixture);
            let second = fixture_findings(fixture);
            assert_eq!(first, second);
            for id in ids {
                assert!(
                    first.iter().any(|finding| finding.rule_id == id),
                    "{fixture} missing {id}; findings: {:?}",
                    first
                        .iter()
                        .map(|finding| &finding.rule_id)
                        .collect::<Vec<_>>()
                );
            }
            assert!(first
                .iter()
                .filter(|finding| finding.rule_id.starts_with(prefix))
                .all(|finding| finding.language.as_deref() == Some(language)));
            assert!(!first
                .iter()
                .any(|finding| finding.rule_id == "core/unsupported-language-coverage"));
        }
    }

