    #[test]
    fn infra_external_parser_examples_are_supported() {
        let hadolint = parse_hadolint_json(
            r#"[{"file":"Dockerfile","line":3,"column":1,"code":"DL3008","message":"pin versions","level":"warning"}]"#,
        );
        assert_eq!(hadolint[0].rule_id, "infra/hadolint/DL3008");
        assert_eq!(hadolint[0].line, Some(3));

        let kubelinter = parse_kubelinter_json(
            r#"{"Reports":[{"Check":"no-readiness-probe","File":"k8s/deployment.yaml","Line":12,"Diagnostic":"container has no readiness probe"}]}"#,
        );
        assert_eq!(kubelinter[0].rule_id, "k8s/kubelinter/no-readiness-probe");

        let checkov = parse_checkov_json(
            r#"{"results":{"failed_checks":[{"check_id":"CKV_AWS_20","check_name":"S3 public read","file_path":"/terraform/main.tf","file_line_range":[8,12]}]}}"#,
        );
        assert_eq!(checkov[0].rule_id, "terraform/checkov/CKV_AWS_20");
        assert_eq!(checkov[0].line, Some(8));

        let conftest = parse_conftest_json(
            r#"[{"filename":"deployment.yaml","failures":[{"msg":"no limits","metadata":{"code":"K8S001"}}]}]"#,
        );
        assert_eq!(conftest[0].rule_id, "infra/conftest/K8S001");
    }

    #[test]
    fn false_positive_good_service_does_not_trigger_covered_high_severity_rules() {
        let findings = fixture_findings("false-positive-good-service");
        let triggered = findings
            .iter()
            .map(|finding| finding.rule_id.clone())
            .collect::<BTreeSet<_>>();
        let covered = false_positive_good_service_covered_high_severity_rules();
        let false_positives = covered
            .intersection(&triggered)
            .cloned()
            .collect::<Vec<_>>();

        assert!(
            false_positives.is_empty(),
            "false-positive-good-service triggered covered high-severity rules: {false_positives:?}; all findings: {:?}",
            findings
                .iter()
                .map(|finding| (&finding.rule_id, &finding.location))
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn false_positive_good_service_exercises_java_http_timeout_safe_pattern() {
        let text = fs::read_to_string(
            fixture_path("false-positive-good-service")
                .join("src/main/java/com/example/good/Application.java"),
        )
        .expect("read false-positive Java fixture");
        let lines = text.lines().collect::<Vec<_>>();
        let builder_line = lines
            .iter()
            .position(|line| line.contains("RestTemplateBuilder()"))
            .expect("false-positive fixture should exercise a matched Java HTTP client pattern");

        assert!(
            nearby_has_any(
                &lines,
                builder_line,
                8,
                &["setConnectTimeout", "setReadTimeout"]
            ),
            "false-positive fixture Java HTTP client coverage must configure explicit timeouts"
        );
        assert!(
            !looks_like_java_http_client_without_timeout(&lines, builder_line),
            "false-positive fixture should cover the Java HTTP timeout detector without firing it"
        );
    }

    #[test]
    fn false_positive_good_service_exercises_java_swallowed_exception_safe_pattern() {
        let text = fs::read_to_string(
            fixture_path("false-positive-good-service")
                .join("src/main/java/com/example/good/Application.java"),
        )
        .expect("read false-positive Java fixture");
        let lines = text.lines().collect::<Vec<_>>();
        let catch_line = lines
            .iter()
            .position(|line| line.contains("catch (RuntimeException ex)"))
            .expect("false-positive fixture should exercise a matched Java catch pattern");

        assert!(
            nearby_has_any(&lines, catch_line, 4, &["logger.warn"]),
            "false-positive fixture Java catch coverage must log explicitly"
        );
        assert!(
            nearby_has_any(&lines, catch_line, 4, &["throw ex"]),
            "false-positive fixture Java catch coverage must rethrow explicitly"
        );
        assert!(
            !catch_block_swallowed(&lines, catch_line),
            "false-positive fixture should cover the Java swallowed-exception detector without firing it"
        );
    }

    #[test]
    fn enabled_high_severity_rules_have_false_positive_fixture_coverage_or_reviewed_exception() {
        let covered = false_positive_good_service_covered_high_severity_rules();
        let exceptions = reviewed_false_positive_exceptions_for_high_severity_rules();

        for id in &covered {
            let rule = builtin_rules()
                .into_iter()
                .find(|rule| &rule.id == id)
                .unwrap_or_else(|| panic!("false-positive coverage references unknown rule {id}"));
            assert!(
                rule.enabled_by_default
                    && matches!(
                        rule.default_severity,
                        Severity::Critical | Severity::Error
                    ),
                "false-positive coverage for {id} must stay limited to enabled Critical/Error rules"
            );
        }

        for rule in builtin_rules().into_iter().filter(|rule| {
            rule.enabled_by_default
                && matches!(rule.default_severity, Severity::Critical | Severity::Error)
        }) {
            assert!(
                covered.contains(&rule.id) || exceptions.contains_key(rule.id.as_str()),
                "enabled high-severity rule {} needs false-positive-good-service coverage or an explicit reviewed exception",
                rule.id
            );
        }

        for id in exceptions.keys() {
            assert!(
                builtin_rules().into_iter().any(|rule| {
                    rule.id == *id
                        && rule.enabled_by_default
                        && matches!(
                            rule.default_severity,
                            Severity::Critical | Severity::Error
                        )
                }),
                "reviewed false-positive exception references unknown or non-high-severity rule {id}"
            );
        }
    }

    #[test]
    fn enabled_builtin_rules_have_fixture_or_explicit_deferred_coverage() {
        let fixture_sets = [
            ("go-bad-service", fixture_findings("go-bad-service")),
            (
                "node-express-bad-service",
                fixture_findings("node-express-bad-service"),
            ),
            (
                "java-spring-bad-service",
                fixture_findings("java-spring-bad-service"),
            ),
            (
                "java-no-service-layer-bad-service",
                fixture_findings("java-no-service-layer-bad-service"),
            ),
            ("python-bad-service", fixture_findings("python-bad-service")),
            (
                "python-route-fact-analysis",
                python_sensitive_route_fact_findings(),
            ),
            (
                "python-route-validation-fact-analysis",
                python_route_validation_fact_findings(),
            ),
            ("csharp-bad-service", fixture_findings("csharp-bad-service")),
            ("php-bad-service", fixture_findings("php-bad-service")),
            ("rust-bad-service", fixture_findings("rust-bad-service")),
            (
                "security-bad-service",
                fixture_findings("security-bad-service"),
            ),
            ("infra-bad-config", fixture_findings("infra-bad-config")),
            ("polyglot-monorepo", fixture_findings("polyglot-monorepo")),
            (
                "unsupported-language-bad-service",
                fixture_findings("unsupported-language-bad-service"),
            ),
            ("ruby-bad-service", fixture_findings("ruby-bad-service")),
            ("kotlin-bad-service", fixture_findings("kotlin-bad-service")),
            ("scala-bad-service", fixture_findings("scala-bad-service")),
            ("elixir-bad-service", fixture_findings("elixir-bad-service")),
            ("c-bad-service", fixture_findings("c-bad-service")),
            ("cpp-bad-service", fixture_findings("cpp-bad-service")),
        ];
        let triggered = fixture_sets
            .iter()
            .flat_map(|(_, findings)| findings.iter().map(|finding| finding.rule_id.clone()))
            .collect::<BTreeSet<_>>();
        let deferred_disabled: BTreeMap<String, String> = BTreeMap::new();

        for rule in builtin_rules() {
            if rule.enabled_by_default {
                assert!(
                    triggered.contains(&rule.id),
                    "enabled builtin rule {} has no fixture trigger or explicit classification",
                    rule.id
                );
            } else {
                assert!(
                    deferred_disabled.contains_key(rule.id.as_str()),
                    "disabled builtin rule {} needs an explicit deferred classification",
                    rule.id
                );
            }
        }

        assert_fixture_has_rule(
            &fixture_findings("java-no-service-layer-bad-service"),
            "java/controller-service-layer-missing",
        );
        assert_fixture_has_rule(
            &fixture_findings("security-bad-service"),
            "security/private-key-material",
        );
    }

    fn temp_root(name: &str) -> PathBuf {
        let suffix = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or(Duration::from_secs(0))
            .as_nanos();
        let root = std::env::temp_dir().join(format!("backend-doctor-rules-{name}-{suffix}"));
        fs::create_dir_all(&root).expect("temp dir");
        root
    }

    fn go_source_graph(root: &Path, source_text: &str) -> ProjectGraph {
        let source = PathBuf::from("src/main.go");
        fs::create_dir_all(root.join("src")).expect("create source directory");
        fs::write(root.join(&source), source_text).expect("write go source");

        let mut graph = ProjectGraph::empty(root.to_path_buf());
        graph.inventory.total_files = 1;
        graph.inventory.source_files = 1;
        graph.inventory.files = vec![source];
        graph
    }

    fn go_gin_source_graph(root: &Path, source_text: &str) -> ProjectGraph {
        let mut graph = go_source_graph(root, source_text);
        graph.services.push(Service {
            id: "go-app".to_string(),
            path: root.to_path_buf(),
            languages: vec!["Go".to_string()],
            frameworks: vec!["Gin".to_string()],
            metadata: BTreeMap::new(),
        });
        graph
    }

