    fn ruby_sql_flow_facts(source_line: u32, sink_line: u32, sink_kind: SinkKind) -> AnalysisFacts {
        let mut facts = ruby_test_facts();
        let file_id = facts.source_files[0].id.clone();
        facts.data_sources.push(request_source_fact_with_scope(
            "request-id",
            &file_id,
            Some("show"),
            Some("params"),
            source_line,
            source_line,
        ));
        facts.sinks.push(sink_fact_with_scope(
            "sql-query",
            &file_id,
            Some("show"),
            sink_kind,
            Some("User.find_by_sql"),
            sink_line,
            sink_line,
        ));
        facts.taint_edges.push(taint_edge(
            "request-to-sql",
            "request-id",
            "sql-query",
            TaintEdgeKind::SourceToSink,
            None,
        ));
        mark_facts_as_adapter_shaped(&mut facts, "ruby");
        facts
    }

