    fn fact_range(start_line: u32, end_line: u32) -> SourceRange {
        SourceRange::new(
            SourcePosition::new(start_line, 1),
            SourcePosition::new(end_line, 120),
        )
    }

    fn source_range_for_first(source: &str, needle: &str) -> SourceRange {
        let start = source.find(needle).expect("source should contain needle");
        source_range_for_offsets(source, start, start + needle.len())
    }

    fn source_range_between_first(
        source: &str,
        start_needle: &str,
        end_needle: &str,
    ) -> SourceRange {
        let start = source
            .find(start_needle)
            .expect("source should contain start needle");
        let end = source[start..]
            .find(end_needle)
            .map(|relative| start + relative + end_needle.len())
            .expect("source should contain end needle after start needle");
        source_range_for_offsets(source, start, end)
    }

    fn source_range_for_offsets(source: &str, start: usize, end: usize) -> SourceRange {
        SourceRange::new(
            source_position_for_offset(source, start),
            source_position_for_offset(source, end),
        )
    }

    fn source_position_for_offset(source: &str, offset: usize) -> SourcePosition {
        let prefix = &source[..offset];
        let line = u32::try_from(prefix.bytes().filter(|byte| *byte == b'\n').count() + 1)
            .unwrap_or(u32::MAX);
        let line_start = prefix.rfind('\n').map_or(0, |index| index + 1);
        let column =
            u32::try_from(source[line_start..offset].chars().count() + 1).unwrap_or(u32::MAX);
        SourcePosition::new(line, column)
            .with_byte_offset(u32::try_from(offset).unwrap_or(u32::MAX))
    }

    #[allow(clippy::too_many_arguments)]
    fn node_route_fact_with_scope(
        id: &str,
        method: &str,
        path: &str,
        file_id: &str,
        symbol_id: Option<&str>,
        start_line: u32,
        end_line: u32,
        callee: &str,
    ) -> RouteFact {
        let mut metadata = BTreeMap::new();
        metadata.insert("adapter".to_string(), "node-typescript".to_string());
        metadata.insert("callee".to_string(), callee.to_string());
        RouteFact {
            id: id.to_string(),
            file_id: Some(file_id.to_string()),
            symbol_id: symbol_id.map(str::to_string),
            service_id: None,
            method: method.to_string(),
            path: path.to_string(),
            framework: Some("Express".to_string()),
            range: Some(fact_range(start_line, end_line)),
            metadata,
        }
    }

