    fn mark_facts_as_adapter_shaped(facts: &mut AnalysisFacts, adapter: &str) {
        for source in &mut facts.data_sources {
            source
                .metadata
                .insert("adapter".to_string(), adapter.to_string());
        }
        for sink in &mut facts.sinks {
            sink.metadata
                .insert("adapter".to_string(), adapter.to_string());
            if let Some(name) = sink.name.as_deref() {
                sink.metadata.insert("callee".to_string(), name.to_string());
            }
        }
        for edge in &mut facts.taint_edges {
            edge.metadata
                .insert("adapter".to_string(), adapter.to_string());
        }
    }

    fn route_drift_graph(root: &Path, source_text: &str, openapi_text: &str) -> ProjectGraph {
        let source = PathBuf::from("src/app.ts");
        let spec = PathBuf::from("openapi.yaml");
        fs::create_dir_all(root.join("src")).expect("create source directory");
        fs::write(root.join(&source), source_text).expect("write route source");
        fs::write(root.join(&spec), openapi_text).expect("write OpenAPI spec");

        let mut graph = ProjectGraph::empty(root.to_path_buf());
        graph.inventory.total_files = 2;
        graph.inventory.source_files = 1;
        graph.inventory.infra_files = 1;
        graph.inventory.files = vec![source, spec.clone()];
        graph.infra.open_api_specs = vec![spec];
        graph
    }

    fn openapi_spec(paths: &str) -> String {
        format!(
            "openapi: 3.0.0\ncomponents:\n  securitySchemes:\n    bearerAuth:\n      type: http\n      scheme: bearer\nsecurity:\n  - bearerAuth: []\npaths:\n{paths}"
        )
    }

