    fn go_sensitive_gin_source() -> &'static str {
        "package main\n\
\n\
func main() {\n\
\trouter := gin.Default()\n\
\trouter.GET(\"/admin/users\", listUsers)\n\
}\n\
\n\
func listUsers(c *gin.Context) {}\n"
    }

