    fn scan_go_file_with_facts_raw(
        graph: &ProjectGraph,
        source_text: &str,
        facts: &AnalysisFacts,
    ) -> Vec<Finding> {
        let metadata = builtin_rules()
            .into_iter()
            .map(|rule| (rule.id.clone(), rule))
            .collect::<BTreeMap<_, _>>();
        let disabled = BTreeSet::new();
        let go_frameworks = BTreeSet::from(["Gin".to_string()]);
        let mut findings = Vec::new();
        let context = GoFileScanContext {
            graph,
            metadata: &metadata,
            disabled: &disabled,
            analysis_facts: Some(facts),
            go_frameworks: &go_frameworks,
        };
        scan_go_file(
            &context,
            Path::new("src/main.go"),
            source_text,
            &mut findings,
        );
        findings
    }

    fn assert_go_text_fallback_flags_once(
        graph: &ProjectGraph,
        source_text: &str,
        facts: &AnalysisFacts,
    ) {
        let findings = scan_go_file_with_facts_raw(graph, source_text, facts);
        let auth_findings = go_gin_missing_auth_findings(&findings);
        assert_eq!(
            auth_findings.len(),
            1,
            "Go text fallback should flag once; findings: {findings:?}"
        );
        assert_eq!(
            auth_findings[0]
                .location
                .as_ref()
                .and_then(|location| location.line),
            Some(5)
        );
        assert_eq!(
            auth_findings[0].impact.as_deref(),
            Some("This conservative heuristic flags routes in files with no auth middleware reference.")
        );
    }

    fn assert_java_text_fallback_flags_once(graph: &ProjectGraph, facts: &AnalysisFacts) {
        let findings =
            scan_project_with_external_and_facts(graph, &Config::default(), Some(facts)).findings;
        let validation_findings = java_missing_validation_findings(&findings);
        assert_eq!(
            validation_findings.len(),
            1,
            "Java text fallback should flag once; findings: {findings:?}"
        );
        assert_eq!(
            validation_findings[0]
                .location
                .as_ref()
                .and_then(|location| location.line),
            Some(5)
        );
    }

    fn assert_java_auth_text_fallback_flags_once(graph: &ProjectGraph, facts: &AnalysisFacts) {
        let findings =
            scan_project_with_external_and_facts(graph, &Config::default(), Some(facts)).findings;
        let auth_findings = java_missing_auth_findings(&findings);
        assert_eq!(
            auth_findings.len(),
            1,
            "Java auth text fallback should flag once; findings: {findings:?}"
        );
        assert_eq!(
            auth_findings[0]
                .location
                .as_ref()
                .and_then(|location| location.line),
            Some(4)
        );
        assert_eq!(
            auth_findings[0].impact.as_deref(),
            Some("Protected data can be exposed when authorization is not enforced.")
        );
    }

    fn route_fact(method: &str, path: &str) -> RouteFact {
        RouteFact {
            id: format!("route:{method}:{path}"),
            file_id: None,
            symbol_id: None,
            service_id: None,
            method: method.to_string(),
            path: path.to_string(),
            framework: None,
            range: None,
            metadata: BTreeMap::new(),
        }
    }
